def _country_code(raw: Any) -> str:
    """国家码 → 两字母大写；**不成形状就返回空串**（由调用方去说人话，这里不编）。"""
    got = str(raw or "").strip().upper()
    return got if re.fullmatch(r"[A-Z]{2}", got) else ""


def _run_country_tool(*, tool: str, timeout: float, country: str = "", url: str = "") -> tuple:
    """换国家那条路的**默认实现**：起 `tools/set-country.py`。

    返回 `(成没成, 它自己说的话)`。⚠️ 判据**只有**它那一个：那个脚本只有在「经 :1081 问到的
    国家 == 要的那个」时才回 0 —— 所以这里不重算、不猜、也不拿「命令跑完了」当成功
    （`subprocess` 回 0 与「出口真变了」是两件事）。
    `country` 空 = 只读（问一句现在哪国，**一个字节都不写**）。
    """
    #: 与本文件那一处同一条风格：**子进程那两样在函数内导入**（`service.py` 不为它多背两个
    #: 顶层名字；`subprocess` 在 `_cdp_bin_source` 那条路上也是这么导的）。
    import subprocess
    import sys

    argv = [sys.executable, str(tool)]
    argv += ["--show"] if not country else ["--country", country, "--url", url]
    try:
        done = subprocess.run(argv, capture_output=True, text=True, timeout=timeout)
    except (OSError, subprocess.TimeoutExpired) as exc:
        return False, "起不来：%s" % exc
    said = "\n".join(x for x in (done.stdout or "", done.stderr or "") if str(x).strip()).strip()
    return done.returncode == 0, said


def _backend_key(url: Any, fix_site: Any, fix_site_url: Any) -> str:
    """「这一次要动的**后端键**」那一条判据（`_stage_fix_source` 与 py 上传**共用一处**）。

    ⚠️ 失败记录里那个键优先，但它只在**还跟着它来的时候那一串网址**时才算数：
    人把「站点网址」那一格改了，这趟活要修的**就不是那条失败记录那个站**了 —— 键继续用会
    **静默改错站**（面板上开的是 B 站，服务拿 A 站的键去读、去传，中间没有一处会响）。
    """
    u = str(url or "").strip()
    key = str(fix_site or "").strip()
    came_with = str(fix_site_url or "").strip()
    return key if (key and came_with and u == came_with) else _key_from_url(u)


def _key_from_url(url: Any) -> str:
    """`https://host/path?q#f` → `host/path` —— 后端认的键是**主机名 + 路径**。

    ★ 2026-09-22（**真上传之后**发现的）：面板那条 py 上传路对新站取的是**原样 URL**
    （带 `https://`、带查询串），而后端认的键是 `主机名/路径`（`fmr.py` 里自己写着
    「真实 key 形如 `主机名/路径`」，`formLog` 行里那个 `site` 也是这个形状）。
    同一个站**两个键** = 后端建出**两条行** ⇒ 生产按其中一个键下载，拿到的可能不是这一份
    （静默 —— 这正是这一族最贵的那种失败）。
    ✅ 同一天实测：拿 `www.parents.com/featured/premium/…`（host+path）去写，后端
    **新建了**那一行、回读逐字节一致（sha256 `5f68a17f…`）。
    ⚠️ 失败记录里那个键（`fix_site`）**原样用** —— 它本来就是后端给的（见上面那条判据）。
    """
    raw = str(url or "").strip()
    parts = urllib.parse.urlsplit(raw)
    if not parts.netloc:
        return raw                      # 没有主机名（人填的可能就是个键）⇒ 一个字不动
    return (parts.netloc + parts.path).rstrip("/") or parts.netloc


def _artifact_say(values: dict, state: dict) -> str:
    """产物那句话**说给人听的那一份**：没有字节时，**第一行先给「为什么没有 py」**。

    ⚠️ 只在**没有字节**时加那一行 —— 有字节时这一块讲的是「它写到哪了」（另一件事）。
    ⚠️ 两处必须**同一句**（`/live` 的产物那一格 与 `/job/{id}/artifact` 那条 409）：
    `tests/test_service_artifact.py::test_the_live_cell_and_the_endpoint_say_the_very_same_thing`
    钉着它。所以那句话的拼法只有这一处 —— 别再各拼一份。
    """
    if state.get("bytes"):
        return state["say"]
    why = _no_py_say(values)
    return ("%s\n%s" % (why, state["say"])) if why else state["say"]


def _no_py_say(values: dict) -> str:
    """**「为什么这一趟没有 py」** —— 按停因分一句话（★ 2026-09-22，用户原话：
    「那产出不了py你要说下原因啊」）。

    为什么要有它：产物那一格原来只引 `end_note`，而 `end_note` 说的是**发生了什么事**
    （「重探了 2 趟都没在页面上见到成功文案」）—— 读的人得自己把它翻成「所以为什么没有产物、
    我下一步做什么」。这一句就是从停因翻过来的那一句，摆在产物那一块的**第一行**。

    ⚠️ 叫不出名字的停因**不硬塞**：返回空串（只摆原来那句）—— 编一个类别比不说更坏。
    ⚠️ 与 `_no_artifact_say` **不是两套答案**：那个说的是「这一趟是哪种没有」（照抄它自己的话），
    这一句说的是「**所以为什么没有 py、下一步做什么**」（把停因翻成人能照做的一句）。
    两句一起摆在产物那一块里 —— 它们的拼法只有 `_artifact_say` 一处。
    """
    reason = str((values or {}).get("end_reason") or "")
    return {
        END_EXPLORE_UNFINISHED: (
            "**为什么没有 py**：探路**没走完** —— 规矩是**不许拿半份账本写 py**"
            "（那样写出来的稿看着挺像，到了真站上走不通）。下一步看下面那句说的是哪一种："
            "窗口没了就「重开窗口，接着走」；判据没在页面上见到就改「什么算成功」那一格。"),
        END_NO_WINDOW: (
            "**为什么没有 py**：这一趟**没有窗口**（浏览器没开起来）—— 探路没有地方可走。"
            "下一步：**再发起一趟**（窗口是服务自己开的）。"),
        END_PAUSED: (
            "**为什么没有 py**：**人喊停**了（探路被人从浏览器那一侧叫停）—— "
            "停下就是停下，页面与文件保持原样。下一步：要接着做就「重新来一遍」。"),
        END_HUMAN_STOP: (
            "**为什么没有 py**：**人喊停**了（服务记的是「停」）—— 那一步没有做，"
            "页面与文件保持原样。下一步：要接着做就「重新来一遍」（你说过的话会带过去）。"),
        END_DRAFT_FAILED: (
            "**为什么没有 py**：**写这一版 py** 那一步没能产出一份过得了闸的稿 —— "
            "原因写在它自己那句话里。下一步：看那句话，缺什么补什么（判据 / 步骤表 / 证据）。"),
    }.get(reason, "")
#: 复跑用哪个浏览器（`ws://…`）。没配 = 这个部署**跑不了复跑** —— 那是合法状态，
#: 面板照样读得到配置，只是「复跑」那一步会明确说「没量着」。
JSON_WS_URL_ENV = "SITEFORGE_JSON_WS_URL"

#: 量不到时那**三种**各自的 HTTP 码。都不是 200、都不是空列表。
#: · 503 = 这个部署**干不了这件事**（没配 token）—— 换个人来也一样；
#: · 502 = 上游**这次给不出可用答复**（连不上 / 非 JSON / 后端自己回了个错码）。
#:   ⚠️ 后端的 401/404 也落进 502：那是「**它说它给不了**」，不是「它说没有失败」。
FAILURE_STATUS_NO_TOKEN = 503
FAILURE_STATUS_UNMEASURED = 502


def _json_entry_url(config: Any) -> str:
    """JSON 配置要跑的那一页 —— `https://<配置里的 site>`；没有 `site` 就回空串。

    ⚠️ **承重**（2026-09-21 实测）：复跑**不导航**的话，它是在**浏览器自己的控制台页**上跑的
    （那一趟的窗口停在 `https://console.bitbrowser.net/?id=…`），于是执行器记下的每一句
    （`click: element not found` / `deferred unfilled`）**全是假账**，页面事实也量不到 ——
    而屏幕上看起来只是「这份配置跑不起来」。这与 py 那条路今天修的是**同一件事**：
    生产起脚本之前先 `cdp navi <入口网址>`（`ad-task.py:2673`）。

    回空串（没 `site`）时：**不导航**，让那一趟如实报它量到的（而不是编一个网址出来 ——
    编一个就跑错页，比不跑更坏）。
    """
    site = ""
    if isinstance(config, dict):
        site = str(config.get("site") or "").strip()
    if not site:
        return ""
    if site.startswith(("http://", "https://")):
        return site
    return "https://" + site.strip("/") + "/"


def _count(raw: str) -> Optional[int]:
    """`?limit=` 那一格 → 一个数（空 = 不给 = 用默认）。**读不出来就在门口响**（400）。

    为什么不在里面 `int()` 了事：那一格是**外面来的字**，`int("abc")` 是一个 500 ——
    而 500 在页面上只是一条「服务出错了」，看不出是「你那一格写得不对」。
    """
    if raw in (None, ""):
        return None
    try:
        n = int(str(raw).strip())
    except ValueError:
        raise HTTPException(status_code=400,
                            detail="`limit` 那一格要的是一个数（读出来的是 %r）—— "
                                   "这一下**一个请求都没发出去**。" % (raw,))
    if n < 1:
        raise HTTPException(status_code=400,
                            detail="`limit` 那一格要的是**正数**（读出来的是 %d）—— "
                                   "0 条与「没给」在屏幕上分不开。" % n)
    return n


def _failures_say(site: str, since: str, rows: list, limit: int) -> str:
    """这一栏顶上那句人话：**量的是什么窗口、量到几条**（「量到的东西要说清量的是什么」）。"""
    when = since[:16]
    if rows:
        said = "这个站从 %s 起有 %d 条失败的记录（这一屏最多摆 %d 条）。" % (when, len(rows), limit)
        if len(rows) >= limit:
            # ⚠️ 摆满了**要说**：悄悄截断 = 一条静默的路径（更早的那些看着像不存在）。
            said += "**摆满了** —— 更早的可能还有，把时间窗缩小一点或者往后翻。"
        return said
    return ("这个站从 %s 起**没有**失败的记录 —— 这是**量到的**结果（不是「没量着」）。"
            % when)


def _configcheck_say(errors: list, notes: list) -> str:
    """合规闸那一句抬头：**这回量到的是什么**。

    ★ 三种要说得分得开：
      · 有 `error` ⇒ 说清**几处**、并且把后果说出来（执行器**不报错**，它只 warning
        一句就当那一步失败了）—— 光说「有问题」读的人会以为闸太严；
      · 只有 `note` ⇒ **仍然说「没有要改的」**，再把提醒单独讲清楚：
        那一档是「我没量到」，不是「它就是错的」（见 `configcheck` 模块 docstring）；
      · 都空 ⇒ 干净。
    """
    if errors:
        return ("这份配置有 **%d 处**执行器一定处理不了（下面列着）。"
                "⚠️ **别写回、也别指望跑了就知道**：执行器碰到不认的动作**不报错** —— "
                "它只 warning 一句就当那一步失败了、然后接着往下跑，"
                "屏幕上与「这一步没效果」一模一样。" % len(errors))
    if notes:
        return ("这份配置**执行器都认**，没有要改的。另有 **%d 处**只是**提醒** —— "
                "那几个键我在执行器那一支里没量到它读：可能是别处要的元数据，"
                "也可能是打错了字，你扫一眼。" % len(notes))
    return "这份配置**执行器都认**，没有要改的。"


def _jsondiff_say(diff: dict, summary: dict) -> str:
    """复跑**跑完之后**那一句人话。

    ★ 它与「还没复跑」那一句（`Service.jsondiff` 里那段字面量）**必须分得开**：
    两句话在屏幕上都是「没东西可看」，而一件事是「这份配置是好的」，
    另一件是「它还没被跑过」。把后者说成前者，就是本仓最贵的那个形状。

    ⚠️ 这一句里**不许出现「没有差异」** —— 那是「跑过了、量过了、确实没问题」
    才配说的话（用例钉着）。这里说的是「每一格都能在页面上量到」，
    而「量到」与「跑通」仍然是两件事：复跑自己成没成，看 `summary`。
    """
    n_un = len(diff.get("unresolved") or [])
    n_ch = len(diff.get("changes") or [])
    failed = summary.get("failed_step") or 0
    tail = ("复跑自己报的：失败在第 %s 步（%s）。" % (failed, summary.get("error") or "没说原因")
            if failed else "复跑自己报的是跑通了。")
    if not n_un and not n_ch:
        return ("复跑跑完了：配置里**每一格**都能在页面上量到，没有对不上的。%s" % tail)
    return ("复跑跑完了：**%d** 格对不上 —— 其中 **%d** 格提得出建议（值出自页面上量到的），"
            "**%d** 格提不出（页面上量到的东西里没有能顶替的，那一格没动）。%s"
            % (n_un + n_ch, n_ch, n_un, tail))


def _diag_say(task_id: str, rows: list) -> str:
    """④ 原因那一栏顶上那句人话：**量的是哪一个单、量到几条**。

    ⚠️ 「几条」这件事在这儿比别处重要：`failDiag` 回的是**一根裸数组**（不带总数），
    而它一页最多 100 条（`fmr.DIAG_PAGE_SIZE`）⇒ 正好够了 100 条时，
    「还有没有更早的」**这一层答不上来**。答不上来就**照实说答不上来**
    —— 不说的话，100 条这个数看着就像「一共就这些」（「没有静默的路径」）。
    """
    if not rows:
        return "单 %s 现在**一条原因行都没有**。" % (task_id or "（空的）")
    said = "单 %s 有 %d 条原因行（最近一次的现场在最前面）。" % (task_id, len(rows))
    if len(rows) >= fmr.DIAG_PAGE_SIZE:
        said += ("⚠️ **摆满了**（这个接口一页最多 %d 条）—— 更早的可能还有，"
                 "而这个接口**不回总数**，所以这一屏**分不出**是不是到底了。"
                 % fmr.DIAG_PAGE_SIZE)
    return said


# ───────────────── §十五 产物交付（Task 11）─────────────────────────────
# 运营拿到产物的唯一方式，从前是去文件系统里捞（`out_dir` 是服务端的一个路径，
# 页面上一个字都没提）。这一节把那一段补上：**这一趟记下的那个 py，页面上就能拿到**。
#
# ⚠️ 这一节里**只有一个判据**（`Service._servable_py`）：`/live` 的产物那一格与
# `/job/{id}/artifact` **都走它**。两套判据的后果不是「多写几行」——
# 页面会说「能下」而端点回 409，运营拿到的是一个点了没反应的按钮
# （本片病史：同一个事实两个名字）。

#: 产物那一格那个地址。**服务给**（页面不自己拼）：路由换了，页面跟着服务走。
ARTIFACT_URL = "/job/%s/artifact"
#: 有产物（= 这一趟写下的那串字节拿到了）那句话。
ARTIFACT_READY_SAY = "这一趟的 py 写下来了 —— 点文件名下载，它落在盘上的位置写在下面。"
# ── 盘上那一份**现在是什么**：一句**信息**（端出去的是记录里那一串，与它无关）──
#: 盘上那份**不是这一趟写下的那串字节**了。
#: ⚠️ **不许断言因果**（复审实测：没有任何第二趟运行、只把文件换掉，也会走到这儿）——
#: 只列**可能**，不挑一个当结论。
ARTIFACT_DISK_DIFFERS_SAY = ("⚠️ 盘上那个路径现在这一份**不是这一趟写下的那串字节**了"
                             "（可能是后来的运行覆盖了它 —— 同一个站点共用一个文件；"
                             "也可能是有人直接改过、或者换过那个文件）。"
                             "下面这个文件是**这一趟写下的那一份**（从这一趟的记录里取的，"
                             "与盘上那一份不是一回事）。")
#: 盘上那个路径**没有文件**了（挪走 / 删掉）。
#: ⚠️ 尾上那半句是给**同一屏**看的（复审判 A4）：这一档 `delivered` 是 **False** ⇒
#: `/job/{id}` 与顶栏会写「**· 没交付**」，而这一格**能下**。两格按定义都对
#: （一个说**盘上那份现在在不在**、一个说**这一趟写下的那串拿不拿得到**），
#: 但页面上那两个字得有人解释一句，不然就是另一种「两格打架」。
ARTIFACT_DISK_GONE_SAY = ("盘上那个路径现在**没有这个文件**了 —— 下面这个文件是这一趟写下的"
                          "那一份（从记录里取的）。\n"
                          "（上面说「没交付」指的是**盘上那份现在不在了**，"
                          "不是「这一趟没交出去」——两件事。）")
#: 盘上那个文件**读不出来**（权限之类）—— 原因**照实带出来**（不是一句同义复述）。
ARTIFACT_DISK_UNREADABLE_SAY = ("盘上那个路径现在**读不出来**（%s）—— 下面这个文件是这一趟"
                               "写下的那一份（从记录里取的）。")
#: 记录里的路径**不在产物目录里**（§15.3）—— 那个路径服务**不去看**（不读、不 stat 内容）。
ARTIFACT_DISK_OUTSIDE_SAY = ("记录里的路径**不在产物目录里**（%s）—— 那个路径服务**不去看**"
                             "（§15.3）。下面这个文件是这一趟写下的那一份（从记录里取的）。")
#: 记录说它**交付过**，可记录里**没有留下它写下的那串字节**（这一次读不回它的记录，或者这一趟是
#: 更早的版本跑的）—— 这一档**交付不出来**（§15.3 的 409）。
#: ⚠️ 尾上那半句是给**同一屏**看的：`/job/{id}` 的 `delivered` 会说「交付了」，
#: 两句话并排摆着，**一个字都不解释**就是一种自相矛盾（复审 R3 点名）。
ARTIFACT_UNVERIFIABLE_SAY = ("这一趟的结局说它**交付过**（%s），可它的记录里**没有留下它写下的"
                             "那串字节**（这一次读不回它的记录，或者这一趟是更早的版本跑的）——"
                             "所以这一份**交付不出来**。\n"
                             "（上面说「交付了」指的是**那一步做成了**，不是「现在还能下」——"
                             "两件事。）")
#: 「到头了但没有产物」那句话的**头**。原因一律照抄这一趟自己留下的那句话（下面那两格）。
#: ⚠️ **跑挂 ≠ 没交付**（复审 R1）：交付之后服务自己那一步还会炸（`_advance` 里
#: `_capture_pause` 在 `job.status = DONE` **之前**）—— 那种一趟**交付过**，
#: 所以这两句只说**这一趟的记录**（服务真的知道的那件事），
#: 不说「没跑到写下那个文件那一步」（服务不知道，而且它可能是假的）。
NO_ARTIFACT_HEAD_DONE = "这一趟**没有可交付的产物**（它到头了，记录里没有它写下 py 的证据）"
NO_ARTIFACT_HEAD_FAILED = "这一趟**没有可交付的产物**（它跑挂了，记录里没有它写下 py 的证据）"
#: 「还没跑到写 py 那一步」那句（在跑 / 排队 / 停在闸上）。⚠️ 与上面两格**不是一回事**：
#: 一个是「它还没写到那儿」，一个是「它跑完了但没有」—— 混成一个就是编话。
NO_ARTIFACT_YET_SAY = ("这一趟还没有产物（它现在是「%s」）—— 产物要等它走到「写下了 py」"
                       "那一步才有。这条路只看**这一趟自己记下的**那个路径。")
#: 到头了、可它一个字没说 —— 明说「它没说」，不替它编一个原因。
NO_ARTIFACT_UNSAID_SAY = "（它没留下说明为什么的那句话 —— 这本身就不正常。）"
#: 「没这个任务」（404）：`/job/{id}`、`/live`、`/artifact` 三处**同一句**
#: （一件事一处口径 —— 三条路读的是同一份 checkpoint/登记表）。
NO_SUCH_JOB_SAY = ("没这个任务：%s（服务里没有它，checkpoint 里也没有）。"
                   "要么 id 写错了，要么它是在**另一个** saver 上跑的 —— "
                   "状态住在 saver 里，不在这个进程里（R-19）。")


def _fingerprint(blob: bytes) -> dict:
    """一串字节的**指纹**：`size` + `sha256`（判「盘上那一份是不是这一趟写下的」用的就是它）。"""
    return {"size": len(blob), "sha256": hashlib.sha256(blob).hexdigest()}


def _delivered_path(values: dict) -> Optional[str]:
    """这一趟**交付过**的那个路径 —— ★ 这道闸的**唯一**写法：`end_reason` 说交付了才算数。

    ⚠️ 跑挂 / 没跑完的那一趟 state 里可能还留着**上一次**真跑留下的 `py_path` 与 `src`
    （`tests/test_service.py::test_a_job_that_died_mid_flight…` 与
    `tests/test_service_artifact.py::test_a_dead_run_does_not_hand_over…` 钉着这件事）——
    所以「state 里有 py_path」**不等于**「这一趟交付过」。

    `_project`（`/job/{id}` 那一份投影）与产物那一路**都用它**：一处口径。
    """
    values = values or {}
    if str(values.get("end_reason") or "") != END_DELIVERED:
        return None
    raw = values.get("py_path")
    return str(raw) if raw else None


def _recorded_bytes(values: dict) -> Optional[bytes]:
    """**这一趟写下的那串字节** —— 从 checkpoint 里取（`state["src"]`），不是从盘上现读。

    ★ 为什么是它：`graph._deliver` 把这一版写到盘上那一句是
    `path.write_text(src, encoding="utf-8")`，而**同一个 `src` 也进了 state**
    （`out.update({"src": src, …})`，与 `py_path` **同一次 update**）⇒
    「这一趟写下的那串字节」**本来就记着**，而且与「它写到哪了」是同一份记录里的两格。

    这是 §15.2「交付的是 `deliver` 那一步**真正写下的那个文件**」在**同站点**那一格上
    唯一站得住的读法：交付点是 `<out_dir>/<site>.py`（**一个站点一个文件**），
    盘上那一份随时可能被后来的运行盖掉，而**这一趟写下的**只有这一份记录说得清。

    没有就是 `None`（更早的版本跑的 / 记录不全 / 这一次读不回它的记录）—— **不许猜**。
    """
    src = (values or {}).get("src")
    return src.encode("utf-8") if isinstance(src, str) else None


def _disk_fingerprint(path) -> tuple:
    """盘上那个文件此刻的指纹 + **读不出来时的真原因**。

    ⚠️ 原因是**带出来**的，不是吞掉：那句话里那个括号要填的是真原因（`EACCES…`），
    填一句同义复述（「读不出来」）等于没填 —— 那是复审 R3 点名的一处空话。
    也**不许**把失败吞成一个空指纹（那会变成「空 == 空」）。
    """
    try:
        return _fingerprint(pathlib.Path(path).read_bytes()), ""
    except OSError as exc:                      # noqa: PERF203 —— 读不出来是**一等结果**
        return None, "%s: %s" % (type(exc).__name__, exc)


def _download_name(raw: str) -> str:
    """下下来叫什么：**这一趟记下的那个路径**的末一段，只留安全字符。

    ⚠️ 它要进 `Content-Disposition` 头 —— 头字段里一个换行就是**头注入**
    （`site` 是运营在载荷里给的），所以只留 `[A-Za-z0-9._-]`，其余换成 `_`。
    （名字来自**记录里那个路径**，不是来自盘上那个文件：端点现在**不打开**那个文件。）
    """
    name = pathlib.Path(str(raw or "")).name
    return re.sub(r"[^A-Za-z0-9._-]", "_", name)[:64] or "artifact.py"


def _inside(path, root, *, direct: bool = False) -> bool:
    """解析符号链接之后，`path` 还在 `root` 里面吗。

    ⚠️ 用**解析后的路径**判，不是「长得像不像」：一个指向 `/etc/passwd` 的
    `forms/sites/x.py` 在字符串上看一模一样，解析完才看得出来。
    前缀比较带上 `os.sep` —— 否则 `sites-evil/` 会「以 `sites` 开头」而混过去。

    `direct=True` 是更严的一档：**直接躺在那个目录里**（不许再下一层）。
    `/job/{id}/shot/{name}` 用它（那儿的「名字」是外面来的，多一层就多一个可乘之机）；
    产物那一路用宽松那一档（§15.3 的原话是「落在 `out_dir` 之内」——
    而这一趟记下的路径本来就只有服务自己写得出来）。
    """
    real = os.path.realpath(str(path))
    base = os.path.realpath(str(root))
    if direct:
        return os.path.dirname(real) == base
    return real == base or real.startswith(base + os.sep)


# ─────────────────── 给运营的那一屏（Task 7 / 设计注 §8.4）───────────────────
#: 页面文件（`GET /console` 读它）。**放仓库里**的理由（设计注 §8.4）：页面是**可读的资产**
#: （能 diff、能 review），不是塞在 py 里的字符串。每次请求现读 —— 改页面不用重启服务。
CONSOLE_PATH = pathlib.Path(__file__).with_name("console.html")
#: 页面文件读不出来时说的话（**不许**静默给一页空白）。
#: 空白页是这一屏最坏的失败形状：它看起来像「还没有任何运行」，而真相是
#: 「服务找不到它自己的页面文件」—— 两件事的处置完全不一样。
CONSOLE_UNREADABLE_SAY = ("控制台页面读不出来：%s —— 服务在 %s 找它（`GET /console` 每次都是现读"
                          "这个文件）。要么它没跟着镜像一起进去，要么权限不对。"
                          "这一条不该出现：页面是仓库里的一个文件，不是运行产物。")


# ───────────────── 人在回路（Task 8 / 设计注 §四）───────────────────────────
# 三条线：`/say`（说一句）/ `/stop`（停下，我要说一句）/ `/again`（重新来一遍）。
# 这一节里**写死的都是人话**（散着写早晚漂成两套口径）；判据在下面那三个**纯函数**里。
#
# ⚠️ 三条线共用一条**硬规矩**（Global Constraints）：**服务可以替人「停」，绝不替人「走」。**
#    「停」不让任何一步发生（它是**阻止**）；而替人回一句「继续」会让一步在没人看着的
#    情况下跑掉（`c998a72` 那次修复钉住的事故）。所以：排队的插话**只预填、不自动发**；
#    没有任何一条路径会因为超时、因为排队、因为「看起来没人管」而自动继续。

#: 常开输入的三种语义（页面 `console.html:306` 的 `MODES` 就是这三个词）。
#: **服务说了算**（设计注 §8.2 第 3 条：页面不许自己猜它在哪种模式）。
INPUT_GATE = "gate"       #: 这就是**这道闸的回话**（只可能在 `waiting` 那一档）
INPUT_STEER = "steer"     #: 探路里跑 —— 下一轮直达（Task 9 的通道）
INPUT_QUEUE = "queue"     #: 排队：到下一道闸进输入框

#: `/say` 的一句话**送到没有**：直达它的下一轮 / 排在队里等闸。
SAY_DELIVERED = "delivered"
SAY_QUEUED = "queued"

#: 探路那个节点（`NODES` 里那个）—— 只有它跑着的时候才有「下一轮」这回事（设计注 §3.4）。
STEER_STAGE = "explore"

#: 「直达」那条通道（Task 9 的 `steer`）**接上了没有**。**这一版写死 `False`**：
#: 代码接上了（`llm.run_tool_loop(steer=…)` + `_steer_cb` + `/say` 那条直达的路），
#: 但**没在真站上验过**（R1：真站演练与 Task 10 合到同一趟窗口）——
#: 而 Global Constraints 说得很死：「一半的插话（说了没送到）比不做更坏」。
#: ⇒ **今天任何路径都不许回 `delivered`**，`/say` 一律排队（页面文案跟着 `mode` 走，
#: 自动是「排队」——**那是诚实的**：服务确实还没把话送到它手上）。
#:
#: ⚠️ 它是一个开关、**不是一个判据**（R1）：`say_route` / `input_mode` 两个纯函数
#: 早就把两个分支都写好了，`/say` 与 `_explore_for` **都读这一格** ——
#: 翻成 `True` 就是「两处一起开」（而不是只开一半：页面说「直达」而话根本没喂下去，
#: 或者话喂下去了而页面说「排队」——两种都是同一个事实两个名字）。
#: ★ **2026-09-22 翻成 `True`**（用户：「现在他在执行的情况我好像没办法插话」）。
#: 上一版写死 `False` 的理由是「没在真站上验过」—— 现在验（`/say` 的回话 + 探路下一轮看到）
#: 就是开它的条件；验完还没过就翻回去。⚠️ 它仍是**一个开关、不是一个判据**：
#: `say_route` / `input_mode` 两个纯函数各两个分支、`/say` 与 `_explore_for` **都读这一格**。
STEER_WIRED = True

#: 一句话最多留多少字（R4）。为什么是这个数：它进 `hints` → 一路带进「写这一版 py」
#: 的提示里，而那是一句**人的纠正**（「不是那个按钮，是下面那个」）—— 一段话的长度。
#: 400 是仓库里已有的「一句人话」那个量级（`_cannot_reopen_say` 里那句 `[:400]` 同源）。
