class CountryRequest(_Intake):
    """`POST /country` 的载荷（2026-09-22）：**换成这个国家的出口**。

    `url` 只是「按哪个目标站挑链」（那条接口按它选出口）——不给就用上一次那个。
    """
    country: str = Field("", description="两字母国家码，如 US / CA")
    url: str = Field("", description="按哪个目标站挑链（可空）")


# ───────── 执行事实：运营写的期望、服务算的判（契约 §二 / §四 / §六）─────────
#
# 这一节是**换裁判**那件事在代码里的样子。契约 §一：病根不是「字段不够」，是
# **判断和执行是同一方**（`datewhirl.py:175` 把「什么都没看见」判成「做完了」）。
# 所以七格里有两格**永远不归脚本**：
#
#   - `expect`（第 6 格）——**运营**写，从 §四那张菜单里选（本文件只负责**收**：形状不对
#     当场拒，见 `expect_problem`）。⚠️ 它**从载荷进来**，脚本一个字节都碰不到它
#     （`_payload` 不往下发；`events.SCRIPT_MAY_NOT_FILL` 再从词表那一侧挡一道）；
#   - `verdict`（第 7 格）——**收到上面那些的那一方**算，也就是**这里**（`judge_step`）。
#
# ⚠️ 这两件事**必须都在服务侧**。放在脚本里（哪怕只是「顺手算一下」），就是
# `datewhirl` 那个病换了个地方长出来 —— 契约 §四 的原话：「模型提议的期望，仍然是
# **执行的那一方在当裁判**，只是换了个更聪明的裁判」。

#: 契约 §四 那张菜单的**机器那一列**（运营在页面上看到的是左边那句人话）。
#: 菜单是**封闭**的：不在这四个里的形状一律拒收（`expect_problem` 会说清该选哪个）。
EXPECT_MENU = {
    "url_contains": "「网址变成…」→ 填一段网址片段",
    "text_appears": "「页面上出现…」→ 填一段文字",
    "button_clickable": "「写着…的按钮变成可点」→ 填按钮上的字",
    "screen_changed": "「换了一屏」→ 不用填（**弱判据**，判的时候会标出来）",
}


def expect_problem(item) -> str:
    """一条期望**不成形状**就说清该怎么改；空串 = 这一条没问题。

    为什么要在**载荷进来的那一刻**拒（免费的那一道闸，与 `_intake_problems` 同一条规矩）：
    `expect` 是整个契约的**诚实阀门**（§四），而一个「随便什么 JSON 都收」的阀门
    等于没有阀门 —— 复审 2026-09-18 实测过：`{"随便什么": 1}` / `"Thank you"` / `["/wizard"]`
    三种**显然不对**的值与四种对的值**一模一样地收下**，于是「机器怎么判」那一列
    在代码里一行都没有。这一版把它补上：**形状是封闭的**，错的那种当场响。
    """
    if item == events.UNDECLARED:
        return ""                                   # 「这一步我说不好」是**一等值**，能选
    if not isinstance(item, dict):
        return ("期望只有两种写法：`%s`（运营说这一步他说不好），或者从菜单里选一项 "
                "%s —— 拿到的是 %r。**不许**填选择器、也不许留空。"
                % (events.UNDECLARED, "、".join("`%s`" % k for k in EXPECT_MENU), item))
    keys = [k for k in item if k not in ("why",)]
    if len(keys) != 1 or keys[0] not in EXPECT_MENU:
        return ("期望要从菜单里选**一项**：%s —— 拿到的是 %r。"
                "（选一项就够：一步该以什么结束只有一件事说得清，两件凑一起是两条期望。）"
                % ("、".join("`%s`（%s）" % (k, v) for k, v in EXPECT_MENU.items()), item))
    key, value = keys[0], item[keys[0]]
    if key == "screen_changed":
        if not isinstance(value, bool):
            return ("`screen_changed` 要的是 `true`（「这一步该换一屏」）—— 拿到的是 %r。"
                    "它是**弱判据**（正文指纹变了就算），算出来的 `met` 会被标出来。" % (value,))
        return ""
    if not isinstance(value, str) or not value.strip():
        return ("`%s` 要的是一段**人写的文字**（%s），拿到的是 %r —— "
                "**不许填选择器**（那是脚本的事，运营的文字要能直接与页面对上）。"
                % (key, EXPECT_MENU[key], value))
    return ""


def _expect_at(expects: list, step_no) -> tuple:
    """第 `step_no` 步的期望 → `(键在不在, 值)`。

    ⚠️ **三种「不知道」在纸上必须分得开**（契约 §四 + §二②），这一版把它们分成了三格：
      - 运营**没写**到这一步（列表比步数短）→ **键不在**（「这一格没人碰过」）；
      - 运营写了 `未声明` → 值是 `events.UNDECLARED`（「他说不好」）；
      - 运营真声明了 → 值是菜单里那一项。
    合成一个（比如把「没写」也算成 `未声明`）就是在替运营说「他说不好」—— 那句话他没说。
    """
    if not isinstance(step_no, int) or step_no < 1:
        return False, None                          # 步号都不知道，谈不上「第几步的期望」
    if step_no > len(expects):
        return False, None
    return True, expects[step_no - 1]


def _receipt_says_sent(receipt) -> Optional[bool]:
    """**动作发出去没有** —— 从 CDP 回执的原文里读（契约 §一那一层：Action Truth）。

    判据只有一条，而且是**协议自己**给的：`{"isError": true, ...}` = 那次工具调用**没成**
    （`tools.call_tool` 就是拿这个字段分支的，脚本在 `browser_agent` 里**逐字转抄**了它）；
    工具回来了（别的任何形状）= 命令**下发了**。

    ⚠️ 为什么读的是回执而不是脚本那句 `result.ok`：**回执是别人的原话**，`result` 是脚本
    自己写的摘要 —— 契约 §六 那条验收要的正是「脚本说成了、回执说没成，系统看得出不一样」。
    读 `result.ok` 就等于**又把裁判还给了脚本**。

    `None` = **说不准**（回执根本没在手上 / 形状不认识）：那是一等值，不许折算成「发出去过」
    也不许折算成「没发出去」。
    """
    if receipt is None:
        return None
    if isinstance(receipt, dict):
        if "isError" in receipt:
            return not bool(receipt["isError"])
        return True                     # 工具回来了（没有 isError 那一层）⇒ 命令下发了
    return None                         # 认不出的形状：不猜


def _meets(expect, present: bool, sig_before, sig_after, changed, step_no=None) -> tuple:
    """运营那条期望**成立没有** → `(值, 一句为什么)`。契约 §四那张菜单的**机器怎么判**。

    三值：`True` / `False` / **`None`（「这一条没被验到」）**。第三种不是含糊其辞 ——
    「量不到」与「不成立」是两件事，而把它们合成一件正是这份契约要治的病。
    """
    if not present:
        if not isinstance(step_no, int):
            # ⚠️ 不许把「不知道问的是第几步」说成「运营没写」—— 那是两句不同的话，
            # 而前者的下一步是**去把步号补上**，后者才是去问运营。
            return None, ("这一步**没有步号**在手上（旧账 / 别的来源），对不上运营那张表 —— "
                          "有没有写期望**不知道**，不是「没写」。")
        return None, ("这一步运营**没写**期望（那不是「他说不好」—— 那是另一件事："
                      "他没说。）")
    if expect == events.UNDECLARED:
        return None, ("运营说这一步**他说不好**（`%s`）—— Business Truth 就是「不知道」，"
                      "**不拿动作的回执冒充**。" % events.UNDECLARED)
    kind = list(expect)[0] if isinstance(expect, dict) and expect else ""
    if kind == "url_contains":
        if not isinstance(sig_after, dict) or not sig_after.get("url"):
            return None, "这一条要拿**动作之后那一页的地址**比，而那份签没量到。"
        hit = str(expect["url_contains"]) in str(sig_after["url"])
        return hit, ("运营说「网址应该变成含 `%s`」，实际是 `%s`。"
                     % (expect["url_contains"], sig_after["url"]))
    if kind == "text_appears":
        return None, ("这一条要拿**正文**比，而原始签里只有正文的**指纹**（存正文的话"
                      "账本就装不下了）—— 今天判不了，**不猜**。")
    if kind == "button_clickable":
        return None, ("这一条要按文字找到那个按钮、还要问它可不可点，而原始签里只有"
                      "**可见元素计数** —— 今天判不了，**不猜**。")
    if kind == "screen_changed":
        if changed is None:
            return None, "这一条要拿两份签比，而其中一份没量到。"
        return bool(changed), ("**弱判据**（契约 §四自己标的）：判的是正文指纹变没变，"
                               "变了不代表变对了地方。")
    return None, ("这条期望的形状我不认识（%r）—— 载荷那道闸本该在提交那一刻挡住它。"
                  % (expect,))


def judge_step(*, step_no, receipt, sig_before, sig_after, expect, expect_present) -> tuple:
    """**契约 §二第 7 格**：从两份原始签 + 回执算出「变没变、成没成」→ `(verdict, say)`。

    这是**裁判**，所以它只吃**别人写下来的东西**（CDP 的回执、脚本量的签、运营写的期望），
    一个字节都不来自「它自己觉得」：

    - **① Action Truth**（动作发出去没有）← 回执原文；
    - **② State Truth**（页面变没变）← 两份原始签；
    - **③ Business Truth**（运营那条期望成立没有）← 期望 + 上面两样。

    三层**分开报**，`verdict` 里三个值各自独立（`sent` / `changed` / `met`）——
    合并成一个 `success` 正是 `datewhirl` 那个病的形状。

    ⚠️ **这两条要分开报，是因为同一句「页面没变」在两处的意思完全相反**：
    动作**发出去了**而页面没变 = 「这一步没生效」；动作**没发出去**而页面没变 = 「这一步
    压根没发生」。前者要看选择器，后者要看**为什么工具会报错**。把两句合成一句，
    读的人就永远分不出来 —— 契约 §六 那条验收问的正是这个。
    """
    sent = _receipt_says_sent(receipt)
    if sig_before is None or sig_after is None:
        changed = None
    else:
        changed = dict(sig_before) != dict(sig_after)
    met, met_why = _meets(expect, expect_present, sig_before, sig_after, changed,
                          step_no=step_no)

    # ── 人话：三层各说一句，最后给一句结论 ─────────────────────────────
    if sent is True:
        action_say = "回执说动作**已经下发**"
    elif sent is False:
        action_say = "回执说**动作根本没发出去**"
    else:
        action_say = "回执没在手上（看不见），动作发没发**说不准**"
    if changed is True:
        state_say = "页面**变了**"
    elif changed is False:
        state_say = "页面**没变**"
    else:
        state_say = "页面变没变**量不到**"

    if sent is False:
        verdict_say = ("%s —— 这一步**没有发生**：%s 不是它的结果，**别当成功**。"
                       % (action_say, state_say))
        if changed is True:
            verdict_say = ("%s，可%s —— 两句话对不上：那一下**不是这一步干的**，"
                           "查别处（谁改的页面）。" % (action_say, state_say))
    elif sent is True and changed is False:
        verdict_say = "%s，而%s —— 动作真送出去了、页面纹丝不动：这一步**没生效**。" % (
            action_say, state_say)
    elif sent is True and changed is True:
        verdict_say = "%s，而且%s。" % (action_say, state_say)
    else:
        verdict_say = "%s，%s —— 这一步成没成**判不了**（缺的那一层就是缺的那一层）。" % (
            action_say, state_say)

    if met is True:
        verdict_say += "（运营那条期望：对上了。）"
    elif met is False:
        verdict_say += "（运营那条期望：**没对上**。）"
    if met_why:
        verdict_say += "（%s）" % met_why

    where = ("第 %s 步" % step_no) if isinstance(step_no, int) else "这一步"
    return ({"sent": sent, "changed": changed, "met": met},
            "%s：%s" % (where, verdict_say))


# ─────────────────────────────── job ───────────────────────────────


@dataclasses.dataclass
class Job:
    job_id: str
    brief: dict
    status: str = QUEUED
    say: str = ""
    error: Optional[str] = None
    graph: Any = None
    lock: threading.Lock = dataclasses.field(default_factory=threading.Lock)
    created_at: str = ""
    #: **闸拍张数**（= `pause-<n>.png` 里的 n）。Task 6 的配对规则
    #: 「第 n 道闸上拍的那张叫 `pause-<n>`」靠的正是这个数。
    #: ⚠️ 它**不是轮数**（复审 2026-09-18 N5 的同族）：`_capture_pause` 在**每一次**
    #: advance 之后都拍，**跑完 / 跑挂那一次也拍** ⇒ 到头了的那两档它 = **轮数 + 1**。
    #: 轮数的算法只有一处（`agent/rounds.py` 的 `count()`，它按状态去掉最后那张）。
    #: ⚠️ 拍不成的那一轮**也占号**（否则轮号与闸号会错开），差别记在 `shot_notes` 里。
    pauses: int = 0
    #: 每一轮一条：`{"n", "name", "why"}`。拍成了 `name="pause-<n>.png"` 且 `why=""`；
    #: 没拍成 `name=None` 且 `why` 是一句**人话**（拍不成绝不许静默）。
    shot_notes: list = dataclasses.field(default_factory=list)
    #: 时间线（Task 4 / 契约七格，`agent/events.py`）。**唯一的写入口是 `Service.narrate`** ——
    #: 谁都别直接 `timeline.add`（否则人话纪律与「谁填哪一格」会散）。
    #: ⚠️ 它是 **process-local** 的：服务一重启就没了（`/live` 的 `note` 明说这件事）。
    timeline: events.Timeline = dataclasses.field(default_factory=events.Timeline)
    #: 这个 job 是不是**服务重启之后从 checkpoint 捡回来的**（`/live` 的 `note` 靠它明说）。
    recovered: bool = False
    #: 「窗口已经死了」这件事**说过了**没有：每次 `_advance` 返回都去问窗口层，
    #: 但只有「不是没了 → 没了」那一翻要记一条（同一件事记十遍不是信息）。
    window_dead: bool = False
    #: **步拍**报过的 `why`（人话原文）。**同一句只报一次**（Task 5，目录表第 6 行）：
    #: 拍照坏掉通常是**每一步**都坏，每一步刷一条会把时间线灌满 —— 而多条不是信息。
    #: 认的是**那句话**、不是第几步：同一趟探路里两步的图没了往往是同一个原因。
    shots_reported: set = dataclasses.field(default_factory=set)
    #: **播报坏了**这件事报过的原因（Task 5 修复轮 1）。同上：报告会一直躺在 state 里，
    #: 而每次 `_advance` 返回都会去读它一遍 —— 不去重就是同一句话每推一步记一条。
    narration_reported: set = dataclasses.field(default_factory=set)
    #: 人说过、**还没送到它手上**的话（Task 8 的 `/say` 排队那条路）。每一条至少
    #: `{"text", "at", "delivered", "superseded", "promised", "seq"}` —— 送到时**改的是同一条**
    #: （不是追加一条新的），Task 9 就是靠 `delivered` 分辨「喂过它没有」。
    #: ⚠️ 但「没送出去」**不再等于**「该喂」：不再摆给他的那些（`superseded`）要不要喂，
    #: 是 **Task 9 自己**的决定 —— **别默认照喂**。理由也必须用观察语（修复轮 4 / F4）：
    #: 服务**观察到的**是「这一次送下去的是别的」，**不是**「他心里怎么想」——
    #: 这里原先写的是「他刚说过『别再摆给我看了』」 [禁语]，那是**替人编了一句他从没说过的话**
    #: （被标的那条他可能压根没看见过），跟它下面三行当场打架。
    #: `superseded`（修复轮 2 / NEW-1）：这一句**不再往输入框里摆**了 —— 观察到的事实是
    #: 「服务本来要摆给他的就是这一句，而他按下去的是**别的**」（**不是**猜他心里怎么想：
    #: 服务不知道他屏幕上画的是哪一句，修复轮 3 / NEW-R2）。于是它不再进输入框（不再问一次），
    #: 但**还记着**（`/again` 照带）。两格各说一件事，**都用观察语**：
    #: `delivered` = 「到过它手上没有」，`superseded` = 「还摆不摆给他」。
    #: ⚠️ 只活在进程里（与 `timeline` 同一条命）；服务重启后它没了 —— 而它本来就只装
    #: 「说了还没送出去」的话，重启之后那些话的去处由 `timeline` 那句话自己说。
    inbox: list = dataclasses.field(default_factory=list)
    #: 有一个**还没兑现**的停请求（`/stop` 记下的）。它是**探路 `should_pause` 读的那一格**
    #: （设计注 §4.1：停是**安全**的那一半授权 —— 它不让任何一步发生），也是页面禁用
    #: 「停」那个按钮的判据（`console.html:696`）。到闸上/这一趟结束了就**兑现并清掉**
    #: （`_note_stop_landed`，A3）。
    stop_requested: bool = False
    #: 按下去那一刻**那句承诺**（与它的落点）。⚠️ 存下来而不是每次重算：在闸上按的「停」
    #: 是**立刻**兑现的（矩阵第 3 行），而那一刻之后状态还会往前翻（running → done）——
    #: 重算就会把「立刻」说成「跑完这一步才停」（假话）。
    stop_where: str = ""
    stop_say: str = ""
    #: **这一趟的图现在在跑哪个节点**（服务自己在进程里记的一个字符串，A2）。
    #: ⚠️ 为什么不是「要用的时候去读 checkpoint」：`_snapshot` 在读连接那三种形态下
    #: （内存 saver / 调用方给的 saver / `graph_factory`）会**一直等到这一步跑完**（A1）——
    #: 而 `/say` `/stop` `/live` 唯一有用的那一档**正是「跑着」**（真站点上一趟几分钟）。
    #: 它是 `_where_it_stopped` **在安全时刻（一次 invoke 开始之前）采的那一次样**，
    #: **不是第二个真相源**。
    running_step: str = ""
    #: `/say` 收到第几句话（**只增不减**，回归 4 / ★1）。它是条目上 `seq` 那一格的来源 ——
    #: 号**只认这个计数器**，与队列里现在有几条、条目有没有被拿掉**都不相干**。
    say_seq: int = 0
    #: 「**没送到它手上**」这件事**报过**的那几条话（回归 1 / F1b + F2②）。与 `shots_reported` /
    #: `narration_reported` 同一个形状：**同一条话只报一次** —— `reopen` 之后这一趟还会再走到头
    #: 一次，那几条**照样还在队里**（没送到就是没送到），不去重就会把同一句再说一遍。
    #: ⚠️ 收到这儿的是**条目号**（`seq`），**不是文本**（回归 3 / R3）：按文本收的话，
    #: 「同一句话说了两遍」（页面预填 + 人再按一次发送，可达）产生的**第二条承诺**
    #: 每个出口都收不回来 —— 那是残余的静默。
    steer_missed_reported: set = dataclasses.field(default_factory=set)

    def snapshot_for_view(self) -> tuple:
        with self.lock:
            return self.status, self.say, self.error


# ─────────────────────────────── 服务本体 ───────────────────────────────


def _next_say_seq(job: Job) -> int:
    """**这一条话的号**（回归 4 / ★1）：Job 上那个只增不减的计数器往前走一格。

    ⚠️ **持锁里调**（`say()` 的 append 那一块就在 `with job.lock:` 里）—— 两个线程同时
    `/say` 也不会拿到同一个号。⚠️ 它**不是** `len(job.inbox)`：那种写法要靠「条目只增不删」，
    而号一旦与队列长度绑在一起，将来有人删条目就会**撞号**（去重集合会把新承诺当成报过了）。
    """
    job.say_seq += 1
    return job.say_seq


class _SteerLine:
    """交给 `explore(steer=…)` 的那根线（Task 9）。**一趟探路一根**（`_explore_for.run` 每趟新建）。

    它替服务拿着「这一轮刚交出去、还没等到结果」的那几句：

      - `__call__`：队里**还在等**的那些 → 交给这一轮（**先不翻 `delivered`、也不说**
        「交给它了」—— 那一刻只知道「放进了消息」，不知道「发得出去」）；
      - `went_out()`：那一次调用**真的发出去了** ⇒ 这时才翻、才说（F2③）；
      - `missed()`：那一次调用**没发出去** ⇒ 一个字都不翻（它们还排在队里，下一轮照样交给它）。

    ⚠️ **为什么不在这里说「没送到」**（`missed` 只清账、不说话）：那一刻**这一趟还没完** ——
    「没送到」这一句归**结尾那一笔**（`Service._note_steer_missed`，一处说清、连同「这一趟是
    怎么结束的」）。两个出口说同一件事，迟早会有一边漂掉。
    ⚠️ `_inflight` 一份就够：`__call__` 与两个结果方法在**同一条线程的同一个调用栈**上
    （循环问一句 → 调一次 `create` → 回填一次），所以它不需要锁。
    """

    def __init__(self, svc: "Service", job_id: str):
        self._svc = svc
        self._job_id = job_id
        #: 这一轮交出去的：`(话, [条目])`；`None` = 这一轮没有人说话（或还没轮到下一轮）
        self._inflight: Optional[tuple] = None

    def __call__(self) -> Optional[str]:
        job = self._svc._jobs.get(self._job_id)
        if job is None:
            return None
        with job.lock:
            text, sent = Service._steer_plan(job.inbox)
        if not text:
            return None
        self._inflight = (text, sent)
        return text

    def went_out(self) -> None:
        """那一次调用**真的发出去了** ⇒ 翻 + 说（`Service._note_steer_landed`）。"""
        inflight, self._inflight = self._inflight, None
        if inflight is None:
            return
        job = self._svc._jobs.get(self._job_id)
        if job is None:
            return
        self._svc._note_steer_landed(job, inflight[0], inflight[1])

    def missed(self) -> None:
        """那一次调用**没发出去** ⇒ 一个字都不翻（条目还留在队里，下一轮照样交给它）。"""
        self._inflight = None


def _two_readers(*writers) -> Optional[Callable]:
    """把几个 `on_step` 读者串成一个；全是 `None` 就返回 `None`（=不接这条线）。

    为什么要串（2026-09-18）：探路的**一步**从这一天起有**两个**读者 —— 账本
    （落盘，给重放和事后查）与时间线（契约七格，给人读）。两个都是旁路：
    `browser_agent.explore` 的 `emit()` 统一兜异常，坏掉的那个只留一句 note，
    **不许带塌主路**。所以顺序只影响「谁先坏」，不影响主路 —— 账本放前面，
    因为它是**能重放**的那一份。
    """
    live = [w for w in writers if w is not None]
    if not live:
        return None

    def on_step(step: dict) -> None:
        for write in live:
            write(step)

    return on_step


def _tighter(recorded, on_disk) -> dict:
    """两份「这个 job 花了多少」取**更紧的**（逐键 max）。

    为什么不是相加、也不是取其中一份：两份都是**下界**（状态里那份可能因为节点抛异常而
    缺了后面几趟；盘上那份的 `rounds` 对「没量到」的趟记 0）—— 取 max 是**保守**的那一侧
    （预算只会更小、不会凭空变大），与 `graph._round_spends` 那条「不知道的一律按花算」同族。

    ⚠️ **这一格 `rounds` 是「探路的模型轮数」**（`journey.rounds` / `attempts.jsonl`）——
    **不是**「闸拍轮次」（图到过几次闸口）。后者运营看见的那份投影在 `/live.rounds` 与
    `/runs[].rounds`，轮数的算在 `agent/rounds.py` 的 `count()`（⚠️ **不是** `Job.pauses`
    —— 那是**闸拍张数**：跑完/跑挂那一次也拍，到头了那两档 = 轮数+1）。
    **两个事实同名，别互相顶替**：
    这一个「没量到」时会退成 0（`journey.rounds_measured` 才说得清），拿它当轮次数会多算。
    """
    out = {}
    for key in ("steps", "rounds", "attempts"):
        out[key] = max(int((recorded or {}).get(key) or 0), int((on_disk or {}).get(key) or 0))
    return out


class Service:
    """登记表 + 一个工作线程 + 一组投影。

    工作线程是**单飞**的（D6：agent 只有一个窗口，两个 run 并发会在同一个窗口上互相踩）。
    """

    def __init__(self, *, graph_factory: Optional[Callable] = None,
                 window: Any = None, checkpointer=None, checkpointer_url: Optional[str] = None,
                 out_dir: Optional[str] = None, viewport_probe: Optional[Callable] = None,
                 explore_dir: Optional[str] = None,
                 window_probe_seconds: Optional[float] = None,
                 shots_dir: Optional[str] = None, capture: Optional[Callable] = None,
                 shot_timeout: Optional[float] = None, capture_bin: Optional[str] = None,
                 selftest_dir: Optional[str] = None, mcp_bin: Optional[str] = None,
                 failures_reader: Any = None,
                 json_ws_url: Optional[str] = None,
                 json_rerun: Optional[Callable] = None,
                 json_backup_dir: Optional[str] = None,
                 json_ticket_store: Any = None,
                 country_runner: Optional[Callable] = None,
                 country_tool: Optional[str] = None):
        self._jobs: dict[str, Job] = {}
        self._jobs_lock = threading.Lock()
        self._queue: "queue.Queue[tuple]" = queue.Queue()
        self._check = (checkpointer if isinstance(checkpointer, Checkpointer)
                       else Checkpointer(saver=checkpointer, url=checkpointer_url))
        self._window = window
        self._graph_factory = graph_factory
        self._out_dir = out_dir or str(graph.DEFAULT_OUT_DIR)
        # ── 构造时**定死**的那几样（部署配置；之后再也不看环境）──────────────────
        #: 图落哪、账落哪、用哪个 cdp / 哪个 cdp-mcp。⚠️ 为什么不「用的时候再读环境」：
        #: 抓拍 / 窗口探针 / 自测 / 探路会话都跑在**工作线程或子进程**里，
        #: 可能比设那段环境的东西活得久 —— 修复轮 1/2 各实测过一次漏（子进程里环境已经是
        #: 空的，回退链于是落回**仓库里那个真二进制**，而去连的是真地址）。
        #: ⚠️ 次数是**竞态量**：全量套件里**每趟 2–4 次**（取决于哪几条「发了 job 不等它」的
        #: 用例的 worker 活过了它的 fixture）——**别把它当仪器读数**，它是「有这个病」的证据。
        #: **定死了就没有「以后再看一眼环境」这回事。**
        #: `shots_dir` ⇒ `SITEFORGE_SHOTS_DIR` ⇒ 仓库里的 `runtime/shots`；
        #: `capture_bin` ⇒ `SITEFORGE_CDP_BIN` ⇒ `CDP_PATH` ⇒ 仓库里的 `tools/cdp/cdp`。
        self._shots_dir = shots.root_for(shots_dir)
        self._cdp_bin, self._cdp_bin_source = shots.cdp_bin_with_source(capture_bin)
        #: 自测每一遍的 trace 落哪（`<root>/<site>-<时刻>/`）—— 同上，构造时定死。
        #: ⚠️ 以前这里没有：`run_dir` 由 `selftest.run` 在**调用那一刻**解析成
        #: **仓库里**的 `runtime/selftest/…`（修复轮 3 的 F2，实测真被建出来）。
        self._selftest_root = str(selftest_dir
                                  or os.environ.get("SITEFORGE_SELFTEST_DIR")
                                  or selftest.DEFAULT_ROOT)
        #: 探路那条会话（`McpSession.open` → `cdp-mcp`）用哪个可执行文件 ——
        #: **唯一真连浏览器**的通道也在同一条不变量里（`tools.MCP_BIN` 是导入期读的，
        #: 那次读数**不是**这个服务定的；这里把它按服务的意愿定死，测试/运维才换得动）。
        self._mcp_bin = str(mcp_bin or os.environ.get("CDP_MCP_BIN") or tools.MCP_BIN)
        #: 「活着的窗口现在多大」怎么量（默认走 cdp 读页面；测试注入桩）。
        #: ⚠️ 默认那根线是**同类通道里的第二条**（它自己也读环境、自己也起子进程）——
        #: 所以把**定死的那个二进制**绑给它（`live_viewport(cdp_bin=…)`），它不再自己看环境。
        self._viewport_probe = (viewport_probe
                                or functools.partial(live_viewport, cdp_bin=self._cdp_bin))
        self._probe = None
        self._worker: Optional[threading.Thread] = None
        self._worker_lock = threading.Lock()
        # ── 运行产物（计划四 Task 1）：`runtime/explore/<job_id>/` ──────
        #: 账落在哪（`runtime/` 不进 git；与 `runtime/selftest/` 同层不同目录）
        self._explore_root = str(explore_dir or os.environ.get("SITEFORGE_EXPLORE_DIR")
                                 or measure.DEFAULT_ROOT)
        #: 窗口时间线多久探一次。**这个间隔就是 M1 的精度**（要连着它一起读寿命）。
        self._probe_seconds = float(window_probe_seconds
                                    or os.environ.get("SITEFORGE_WINDOW_PROBE_SECONDS")
                                    or 15.0)
        self._window_probe_thread: Optional[threading.Thread] = None
        self._active_job: Optional[str] = None
        # ── 闸拍（设计注 §5.5）：`runtime/shots/<job_id>/pause-<n>.png` ──────────
        #: 真去拍一张的那个函数：`(ws_url, dest, *, timeout) -> (文件名|None, 人话)`。
        #: 不给就用 `shots.capture_via_cli`（闸口上没有 MCP 会话，手上只有 `ws_url`）；
        #: ⚠️ **调用时才取**（不是构造时），测试要换掉它才换得动。
        self._capture = capture
        #: 硬的：超过这么多秒就当这张没拍成（旁路线程，见 `_shoot`）。
        self._shot_timeout = float(SHOT_TIMEOUT_SECONDS if shot_timeout is None
                                   else shot_timeout)
        #: ① 读失败记录的那个客户端（Task 13）。同上：**构造时定死** ——
        #: 不给就按环境拼一个（`FMR_AGENT_TOKEN` / `FMR_BASE_URL` 在这**一刻**读一次）。
        #: ⚠️ 为什么不「用的时候再读环境」：那会让一次请求与另一次请求用的是**两个身份**
        #: （token 轮换的那一刻，同一屏上两条数据来自两个账号），而 `/health` 报的
        #: 「配没配」也会与真正用的那个对不上 —— 「名字说 A、量的是 B」的老病。
        self._fmr = (failures_reader if failures_reader is not None
                     else fmr.FmrClient())
        #: ② 复跑那份 JSON 配置：**用哪个浏览器** + **起子进程那一手**（Task B2/B3）。
        #: `ws_url` 同上：**构造时定死**。不给就按环境拼一个
        #: （`SITEFORGE_JSON_WS_URL` 在**这一刻**读一次）—— 「用的时候再读环境」
        #: 会让同一屏上两条数据取自两个部署，那正是 `/health` 那条老病。
        #: ⚠️ **没配是合法的**：面板照样能读那份配置、照样能摆出来，只是
        #: 「复跑」那一步会明确说「没量着」，**不是**回一份假的空 diff。
        self._json_ws_url = (json_ws_url if json_ws_url is not None
                             else os.environ.get(JSON_WS_URL_ENV) or "").strip()
        self._json_rerun = json_rerun or jsondiag.rerun
        self._json_tickets = json_ticket_store or jsonwrite.TicketStore()
        backup_root = (json_backup_dir or os.environ.get("SITEFORGE_JSON_BACKUP_DIR")
                       or str(pathlib.Path(self._explore_root).parent / "json-backups"))
        self._json_backups = jsonwrite.BackupStore(backup_root)
        #: ★ py 上传那三下的状态（2026-09-22）：一次性票据（纯内存）+ 原件备份（落盘）。
        #: 备份与 JSON 那条**同一个根目录**（文件名前缀不同：`json-` / `py-`，不会撞）。
        self._py_tickets = pywrite.UploadTickets()
        self._py_backups = pywrite.TextBackupStore(backup_root)
        #: ★ 换代理国家那条路（2026-09-22）。与别的那几根线同一条不变量：**构造时定死**
        #: （用哪个脚本、最多等多久），之后不再看环境 —— 「调用时再读环境」会让同一屏上
        #: 两下按的其实是两个部署（`shots` / `selftest` / `viewport` 那几处都吃过这个亏）。
        self._country_tool = str(country_tool or os.environ.get("SITEFORGE_SET_COUNTRY_TOOL")
                                 or SET_COUNTRY_TOOL)
        self._country_runner = (country_runner
                                or functools.partial(_run_country_tool, tool=self._country_tool,
                                                     timeout=SET_COUNTRY_SECONDS))
        #: 运营**按过**的那个国家（`POST /country` 核成功才记）。它只给自测的第 5 遍用：
        #: 没按过 = 空串 = 那根线不接 ⇒ 行为与从前**一个字节不差**。
        #: ⚠️ 它是 process-local 的（服务重启就没了）——**故意的**：它记的是「这一次会话里
        #: 人明确要过哪个国家」，不是「gost 现在恰好是哪国」（后者问 `GET /country`，那是
        #: 实测读数）。按「恰好是哪国」去接这根线，就等于**替人决定**要跑第 5 遍。
        self._country = ""
        #: 换链时用哪个目标站（接口按它挑链）。上一次成功那次用的是什么就还用那个。
        self._country_url = ""

    # ── 外面那三层：图、窗口、检查点 ────────────────────────────────
    def _build_graph(self, brief: dict, job_id: str = ""):
        """给一个 job 拼一张图。**旋钮就在这儿给**（R-31：服务是窗口层的供给方）。

        `graph_factory(brief, deps)` 收到的是**本服务拼好的 `Deps`** —— 于是调用方
        （测试 / 计划三的 Console）可以只换掉贵的那些（探路、自测），而**继承**窗口层那根线。
        生产走 `graph_factory=None` 那条：全是真接线。
        """
        deps = graph.Deps(explore=self._explore_for(brief, job_id),
                          # ★ 修站那条路：出稿之前先跑一遍旧脚本，把「它停在哪儿」给模型。
                          evidence_run=self._evidence_run_cb(brief, job_id),
                          # B 线 ③（乙）：老写法那份 py 的**改稿那双手**（没接上就在 draft 停下点名）。
                          patch_source=self._patch_cb(brief),
                          selftest=self._selftest_cb(job_id),
                          set_viewport=(self._viewport_cb(brief.get("ws_url"))
                                        if brief.get("set_viewport") else None),
                          # ★ 第 5 遍（换代理国家）：只有运营在面板上按过「换成 X 国」才接得上
                          # （`_country_cb` 里那道判）；接上 = 那一遍真跑（换链 + 再跑一遍产物
                          # = 一次提交），没接上 = 照旧跳过（`allow_skips` 的默认值没改）。
                          set_country=self._country_cb(),
                          country=self._country,
                          fresh_session=self._fresh_session_cb(),
                          window_alive=self._window_alive_cb(),
                          # Task 8：「停下，我要说一句」伸进浏览器的那根线（设计注 §4.1 第 1 行）。
                          # 接上它，探路才会**每一步/每一轮之前**问一句「人喊停了吗」。
                          should_pause=self._pause_cb(job_id))
        if self._graph_factory is not None:
            return self._graph_factory(brief, deps)
        return graph.build(checkpointer=self._check.get(), deps=deps)

    def _selftest_cb(self, job_id: str = "") -> Callable:
        """`Deps.selftest`：把**构造时定死的**那两样交给自测（二进制、trace 落哪）。

        为什么（修复轮 2 的第三条通道 + 修复轮 3 的 F2）：

        - **二进制**：`Deps.selftest` 的默认是 `selftest.run`（`graph.Deps`），而它自己会在
          `selftest.py` 里**再读一次环境**（`SITEFORGE_CDP_BIN` → `_default_cdp_bin()`，
          第二候选直接是仓库里那个二进制），读的时刻是**调用的时刻**。
        - **trace 落哪**：`run_dir` 不给就落到 `_default_run_dir(site)` = **仓库里**的
          `runtime/selftest/<site>-<时刻>/`（`_selftest_kwargs` **不给** `run_dir`）——
          名字里带时刻 ⇒ 只能在调用那一刻算 ⇒ 与 `_shots_dir`/`_explore_root` 同一个病：
          **服务路径上「调用时再解析」= 测试与运维都管不住它**（实测：不给 `run_dir`
          调一次，仓库里立刻多一个目录）。所以这里**连目录一起给**（根是构造时定死的）。

        ⚠️ 与 `explore`/`shots`/`viewport_probe` 同一条不变量：
        **构造时定死，之后不再看环境**（同一个进程里出现两个不同的 cdp = 漂）。
        ⚠️ 调用方**显式**给了 `run_dir` 就用它的（`setdefault`）：这是注入点，不是覆盖点。

        第三样（Task 5）：**每一遍跑完当场播一条**（`on_run=_run_teller(job_id)`）。
        为什么不图在 `run_dir`/`cdp_bin` 旁边直接写死：时间线挂在**这个 job** 上，
        没有 `job_id` 就无处可记（空字符串 = 今天那条路，不接这条线）。
        同上用 `setdefault`：显式给了 `on_run` 的调用方（测试 / 计划三的 Console）赢。
        """

        def run_selftest(py_path, ws_url, form_file, site, **kw):
            kw.setdefault("run_dir", str(selftest.default_run_dir(site, root=self._selftest_root)))
            if job_id:
                kw.setdefault("on_run", self._run_teller(job_id))
            return selftest.run(py_path, ws_url, form_file, site, cdp_bin=self._cdp_bin, **kw)

        return run_selftest

    # ── ★ 换代理国家（2026-09-22）────────────────────────────────────────
    def _country_cb(self) -> Optional[Callable]:
        """`Deps.set_country`：**只有运营按过「换成 X 国」才接得上**。

        为什么不是无条件接：`_missing_knobs` 只认「这根线在不在」—— 接上它，第 5 遍
        （换链 + **再跑一遍产物** = 一次提交）就变成**要跑的**。而「换了哪个国家」是人的
        决定，不是服务能替他决定的（R-5：没验到不许说验过了，可**没让人要过的扰动**
        也不该自己跑起来 —— 那会拿真站去换一个没人要的出口 + 多花一次提交）。
        ⚠️ 回调里**没验到就抛**：`selftest` 会把那一遍记成 `skipped` 并把理由原样带上
        （那一遍这次就是**没验到**，报告里看得见 —— 这才是诚实的落点）。
        """
        if not self._country:
            return None

        def set_country(country: str) -> None:
            want = _country_code(country)
            if not want:
                raise ValueError(COUNTRY_BAD_CODE_SAY % country)
            ok, said = self._switch_country(want)
            if not ok:
                raise RuntimeError(COUNTRY_NOT_VERIFIED_SAY % (want, said))
            self._country = want

        return set_country

    def _switch_country(self, want: str, url: str = "") -> tuple:
        """真去换（`(成没成, 它说的话)`）。**判据只有脚本那一个**（见 `_run_country_tool`）。"""
        target = str(url or "").strip() or self._country_url or "https://example.com"
        try:
            ok, said = self._country_runner(country=want, url=target)
        except Exception as exc:               # noqa: BLE001 —— 外部世界，什么都可能抛
            return False, "换链那一下抛了 %s：%s" % (type(exc).__name__, exc)
        if ok:
            self._country_url = target
        return bool(ok), said

    def country_now(self) -> dict:
        """`GET /country`：**现在这个出口是哪国** —— 实测（经 :1081 问一句），不是记忆。"""
        try:
            ok, said = self._country_runner()
        except Exception as exc:               # noqa: BLE001
            raise HTTPException(status_code=503,
                                detail=COUNTRY_UNREADABLE_SAY % ("%s：%s" % (type(exc).__name__, exc)))
        got = _country_code(said.strip().splitlines()[0] if said.strip() else "")
        if not ok or not got:
            raise HTTPException(status_code=503, detail=COUNTRY_UNREADABLE_SAY % (said or "（它什么都没说）"))
        return {"country": got, "say": COUNTRY_SHOW_SAY % got,
                "chosen": self._country}

    def switch_country(self, country: str, url: str = "") -> dict:
        """`POST /country`：**换成这个国家** —— 核到了才算成。

        ⚠️ 两条前置：① 国家码要成形状；② **没有任务在跑** —— 换链要把 gost 重启，
        正在跑的那一趟的连接会被掐断（那是**破坏**一个真运行，不是「影响一点」）。
        这两条都是**拦在动作之前**（不是做完再说一句「哦它其实在跑」）。
        """
        want = _country_code(country)
        if not want:
            raise HTTPException(status_code=400, detail=COUNTRY_BAD_CODE_SAY % country)
        busy = self._busy_job()
        if busy is not None:
            raise HTTPException(status_code=409, detail=COUNTRY_BUSY_SAY % busy)
        ok, said = self._switch_country(want, url)
        if not ok:
            raise HTTPException(status_code=502, detail=COUNTRY_NOT_VERIFIED_SAY % (want, said))
        #: 核到了才记（这是**自测第 5 遍**那根线的开关）。
        self._country = want
        return {"ok": True, "country": want, "say": COUNTRY_DONE_SAY % want, "output": said}

    def _busy_job(self) -> Optional[str]:
        """有任务**正在跑 / 排着队**就返回「它 id（在哪一步的人话）」，没有就 `None`。

        ⚠️ 判据是「跑着/排队」这两档，**不是**「有没有 job 登记」（停在闸上的不算在跑）。
        停留在闸上的那一趟不碰浏览器，换链不会伤到它 —— 所以它不该拦这一下。
        """
        for job_id, job in list(self._jobs.items()):
            with job.lock:
                status = job.status
            if status not in (QUEUED, RUNNING):
                continue
            token = str(getattr(job, "running_step", "") or "")
            return "%s（%s）" % (job_id, STEP_SAY.get(token, token) if token else UNKNOWN_STEP_SAY)
        return None

    #: 改稿那一次调用的 **token 预算**。⚠️ 这个数是**量出来的**，不是拍的：
    #: 2026-09-21 真跑一趟修站（站 `qualify.lastingpowerofattorney.io`，旧脚本 21916 字节 /
    #: 459 行）时，`llm.DEFAULT_MAX_TOKENS`（12000）被**思考 token 吃满** ⇒
    #: `finish_reason="length"`、`content` 空 ⇒ 那一版补丁是空的，钱白花。
    #: 这份活要的是「整份源码进、整份源码出」+ 推理，所以给足。
    PATCH_MAX_TOKENS = 32000

    def _evidence_run_cb(self, brief: dict, job_id: str = "") -> Optional[Callable]:
        """`Deps.evidence_run`（修站那条路）：**跑一遍旧脚本**拿证据。

        ⚠️ 这一下**动真页面 + 一次真实提交**（运营口径「刷太多不太好」）—— 所以它挂在
        `explore` 那道闸**之后**（图那一侧管的），不是顺手就跑。
        ⚠️ 接不上窗口层就没有这一根线（`None`）—— 图会在事实里说清「这一趟没有真证据」。
        """
        if self._window is None:
            return None

        def run_evidence(py, ws_url, form_file, site, entry_url=""):
            return selftest.run_once(py, ws_url, form_file, site, legacy=True,
                                     run_dir=pathlib.Path(self._selftest_root) / ("evidence-%s" % site),
                                     cdp_bin=self._cdp_bin, timeout=selftest.DEFAULT_TIMEOUT,
                                     entry_url=entry_url)

        return run_evidence

    def _materialize_form_data(self, brief: dict) -> dict:
        """`form_data`（人糊的一段 JSON）→ `form_file`（一份文件）。**只在没给文件时做**。

        ⚠️ 空着也给：写一份 `{}` —— 那是「**没给值**」（产物自己的兜底值会生效），
        **不是**替它编数据。不给这一步的后果是自测那一步当场停，而人在面板上没有别的格子。
        """
        if str(brief.get("form_file") or "").strip():
            return brief
        text = str(brief.get("form_data") or "").strip() or "{}"
        try:
            json.loads(text)
        except json.JSONDecodeError as exc:
            raise HTTPException(
                status_code=400,
                detail="「表单数据」那一格不是一段合法的 JSON：%s（第 %s 行第 %s 列）。"
                       "要的是一份 `{...}`（字段名 → 值）；**空着也行** —— 空着就按「没给值」算。"
                       % (exc.msg, exc.lineno, exc.colno))
        path = pathlib.Path(tempfile.mkdtemp(prefix="siteforge-form-")) / "form.json"
        path.write_text(text, encoding="utf-8")
        brief["form_file"] = str(path)
        brief["form_data_given"] = bool(str(brief.get("form_data") or "").strip())
        return brief

    def _patch_cb(self, brief: dict) -> Optional[Callable]:
        """`Deps.patch_source`（B 线 ③ 乙）：**老写法那份 py 的改稿那双手**。

        形状 `(old_src, feedback) -> 模型原话`：图那一侧负责过闸（`fix.check_patch`），
        这里只负责「把提示词拼好、把模型叫醒」。

        ⚠️ **没有模型 key（`OPENAI_API_KEY`）就返回 `None`**（不接这根线）—— 图会在
        `draft` 那一步**停下并点名**（「这个部署没接改稿的手」）。**不编一个假的改稿器**：
        那会让「改不了」看起来像「改过了」。
        ⚠️ 失败证据 / 成功判据 / 违规行 / 人说的话**逐字**交给 `fix.patch_user` 组装 ——
        这一层**不概括**它们（概括一次，模型就再也看不到原文里那些细节）。
        """
        if not os.environ.get("OPENAI_API_KEY"):
            return None
        evidence = str(brief.get("evidence") or "")
        success_text = str(brief.get("success_text") or "")

        def patch(old_src: str, feedback: dict) -> str:
            fb = feedback or {}
            vios = fix.violations_for_prompt(fb.get("violations"))
            page_ev = str(fb.get("fix_evidence") or "")
            diag = fb.get("diagnosis") if isinstance(fb.get("diagnosis"), dict) else {}
            #: 模型不调工具直接答（`tool_specs=[]`）—— 这是**一次问答**，不是工具循环。
            rounds = llm.run_tool_loop(
                fix.PATCH_SYSTEM,
                fix.patch_user(old_src, evidence=evidence, success_text=success_text,
                               diagnosis=str((diag or {}).get("say") or ""),
                               page_evidence=page_ev, violations=vios,
                               hints=list(fb.get("hints") or [])),
                [], lambda name, args: None, max_rounds=1,
                max_tokens=self.PATCH_MAX_TOKENS)
            #: 空回话在这儿**抛**（带那一次的账）—— 图那一侧会把它原样摆到闸上，
            #: 不许只说「补丁是空的」（见 `fix.patch_from_rounds` 的 docstring）。
            return fix.patch_from_rounds(rounds, max_tokens=self.PATCH_MAX_TOKENS)

        return patch

    def _explore_for(self, brief: dict, job_id: str = "") -> Optional[Callable]:
        """探路要朝**载荷里那个窗口**去（服务是知道窗口的那一层）。

        为什么要这一根线：`browser_agent.explore()` 自己不收 `ws_url`（图调它时只给
        url/goal/预算/暂停谓词），窗口是从 `tools.McpSession.open(ws_url=…)` 或环境变量
        `CDP_WS_URL` 进去的。载荷里那个窗口不给它，它就会退回默认的 `127.0.0.1:9222` ——
        也就是**别的**浏览器（本机那个 headless，或者更糟：别的任务的窗口）。

        另外两件（计划四 Task 1，都是**加**）：每一步落 journal（G1：`on_step` 早就有，
        服务没接）、一次探路收场时记一行账（`attempts.jsonl` —— 基线 M2/M3 的输入）。

        第三件（Task 3 修复轮 1）：**步拍那个目录也归这里给**（`shots_dir=<job 级目录>`）。
        不给的话 Task 2 整片步拍在**生产里是死的**（`explore(shots_dir=...)` 只有测试传），
        而页面上那句「关掉逐步的图是为了省钱」就成了空话。目录由 `shots.dir_for` 按需建
        （**写**的那一侧），根与闸拍同一个（服务构造时定死的那个）。
        """
        ws_url = str(brief.get("ws_url") or "").strip()
        if not ws_url:
            return None                       # 没人给窗口 → 用默认（图会在自测那步停下点名）
        #: 步拍落在哪（这一趟探路的 job 级目录）。**算不出来就不接** ——
        #: `job_id` 不像话时 `dir_for` 报错，而这里是图的路径上，不许抛；
        #: 闸拍那条路自己会把这个原因记成一句人话（`_shoot_pause`）。
        #:
        #: ⚠️ **这个目录是「一轮」共用的，而 Task 2 的上限是「一趟」的**（修复轮 3 的判定）：
        #: `MAX_KEPT_SHOTS = 40` 判的是**本趟**盘上属于这一趟的张数（`_StepShots` 每一趟
        #: 新建一个），而一个节点最多重探 `graph.EXPLORE_ATTEMPTS = 3` 趟 ⇒
        #: **一个 job 目录里最多 3×40 = 120 张步拍图**（典型 ~110KB/张 ⇒ ~13MB）
        #: **+ 每轮一张闸拍**（`pause-<n>.png`，**不计入**那个上限 —— 它是服务侧另一条路）。
        #: 这不是 bug，是「上限=每趟」这件事没说出口：设计注 §5.5 的「最坏 ~20MB」本来就
        #: 按 40 张/次 + 闸图算的，量级对得上。**要收紧就收在「每 job」那一层**
        #: （跨趟计数），那是清理/保留策略的事，不在这一片。
        try:
            shots_where = str(shots.dir_for(job_id, root=self._shots_dir)) if job_id else None
        except ValueError:
            shots_where = None
        #: 账本第一个**没记成**的原因。`on_step` 吞掉异常，但要留下它 —— 由 `run()` 写进
        #: `journey.notes`（那一层才有 journey）。见 `_journal_for` 的注释。
        #: ⚠️ **每一趟清空一次**（M-6）：不在 `run()` 开头清的话，上一趟的故障会跟着
        #: 后面那一趟（它自己每步都写成功了）一路记下去 —— 那是**假 note**。
        journal_broken: list = []
        #: 时间线那一本的「第一个没记成的原因」。⚠️ **与账本那本分开**（2026-09-18）：
        #: 两个旁路的坏法不一样，合成一本之后那句 note 会说成「账本缺步」——
        #: 而账本一个字节都没缺。同上，**每一趟清空一次**。
        timeline_broken: list = []

        def run(url, goal, budget=None, should_pause=None, resume_from=None,
                resume_note="", window_alive=None, success_text=""):
            started = measure._now()
            # ⚠️ **每一趟取一次号**（I-1）：`deps.explore` 在一次节点执行里最多被调
            # `graph.EXPLORE_ATTEMPTS`(=3) 趟（重探），而「一趟 = 一个 `attempt-<n>.jsonl`」。
            # 号要是**建图时**算一次，三趟就全挤进同一个文件、也没有任何边界标记 ——
            # 而 `attempts.jsonl` 那边是**一趟一行**，两本账当场对不上（`rows != journey.steps`）。
            journal_broken.clear()
            timeline_broken.clear()
            # 一步有**两个读者**（都是旁路，坏掉都不许带塌主路 —— `explore.emit` 统一兜底）：
            #   ① 账本（`_journal_for`，落盘的那一份，Task 4 就在）；
            #   ② 时间线（`_step_teller`，契约七格 —— 2026-09-18 接上）。
            # ⚠️ 分成两个而不是合成一个：账本是**一步一行**的 JSONL（给重放和事后查），
            #    时间线是**给人读**的事件流（契约那七格）。两者的坏法不一样，
            #    `_journal_for` 自己吞异常并记一句，时间线那条**要响**（形状错 = 编程错误）。
            tell = self._step_teller(brief, job_id, timeline_broken) if job_id else None
            on_step = _two_readers(
                (self._journal_for(job_id, self._next_attempt_no(job_id), journal_broken)
                 if job_id else None), tell)
            # 模型**每一轮**的话（`AI 说：…`）—— 第三根线（Task 5，设计注 §3.3）。
            # ⚠️ 它只有**一个**读者（时间线），所以不走 `_two_readers`；
            # 坏掉那件事与上面两条共用 `timeline_broken` 那一本（同一个落点：时间线）。
            on_note = self._note_teller(job_id, timeline_broken) if job_id else None
            try:
                journey = browser_agent.explore(url, goal, budget=budget,
                                                should_pause=should_pause, ws_url=ws_url,
                                                on_step=on_step,
                                                on_note=on_note,
                                                resume_from=resume_from or None,
                                                resume_note=resume_note or "",
                                                window_alive=window_alive,
                                                # ⚠️ **透传**（Task 15）：这一根线是**生产那条**
                                                # —— `graph._explore` 交给 `Deps.explore` 的
                                                # `success_text` 走到这儿就断了的话，「见到成功
                                                # 文案就收摊」在生产里一次都不会发生（而链路上
                                                # 每一处看起来都接好了）。图的默认 `deps.explore`
                                                # 是 `browser_agent.explore`，这条是服务那一条。
                                                success_text=success_text or "",
                                                shots_dir=shots_where,
                                                binary=self._mcp_bin,
                                                # Task 9：人的话「直达下一轮」那条线
                                                # （开关没打开时它回 `None` = 今天那条路）。
                                                steer=self._steer_cb(job_id),
                                                # ★ 2026-09-22：**人开跑前说的话**（含「步骤表」）
                                                # 也要进探路 —— 新站那条路的稿是「账本 → 模板」
                                                # 算出来的，模型在这条路上只有探路这一处有判断力；
                                                # 不喂这儿，运营写得再细也一个字到不了（真事）。
                                                hints=list(brief.get("hints") or []))
            except BaseException as exc:       # noqa: BLE001 —— `_Stop` 也是 BaseException
                # 探路自己炸了 —— 也得留一行，不然「这一次尝试」凭空消失，
                # 而消失的那一次恰恰是最该被看见的那一次。记完**原样再抛**。
                # ⚠️ 这一条**到不了下面那句 note**（没有 journey）—— 账本没记成这件事
                # 只能落在 `attempts.jsonl` 的「这一趟连账本都没生成」那一行上（I-3）。
                self._note_attempt(job_id, started=started, journey=None, boom=exc)
                raise
            if journal_broken:
                journey.note(
                    "⚠️ 这一步之后的账本没记全：%s —— 探路照常走完（旁路坏掉不许带塌主路），"
                    "但这一趟的 journal 是残的（`attempt-*.jsonl` 里缺步）。" % journal_broken[0])
            if timeline_broken:
                # 时间线那一本**单独说**（两个旁路的坏法不一样，合并会把话说过头）。
                journey.note(
                    "⚠️ 这一步之后的时间线没记全：%s —— 探路照常走完（旁路坏掉不许带塌主路），"
                    "但这一趟的 `/live` 上会缺事件。" % timeline_broken[0])
            self._note_attempt(job_id, started=started, journey=journey)
            return journey

        return run

    # ── 旁路：运行产物（计划四 Task 1）──────────────────────────────
    # ⚠️ 这一整节都是**旁路**：它坏掉不许把主路带塌（同 Console 那片对 shooter 的规矩）。
    #    「记不上账」是可惜，「跑挂了」是另一件事 —— 两件事不能混成同一件。

    def _window_alive_cb(self) -> Optional[Callable]:
        """`Deps.window_alive`：问一句「窗口还活着吗」（§1.8）。零参数、**三态**。

        ⚠️ **问接口，不猜文本**：探路那侧只在「工具连着失败几次」之后调它一次，
        拿回来的 `False` 才是 `window_gone` 的证据（工具那句错误文字不作数）。
        没接窗口层的部署返回 `None` = 这**不是一根线**，探路于是不会编一个停因出来
        （与 `set_viewport` 那条同一条规矩：给不了就说给不了，不许塞一个假回调顶上）。
        """
        window = self._window
        if window is None or not hasattr(window, "alive"):
            return None
        return window.alive

    def _pause_cb(self, job_id: str) -> Callable:
        """`Deps.should_pause`：探路**每一步 / 每一轮之前**问的那一句（设计注 §4.1 第 1 行）。

        ⚠️ 这是「停」那一半授权在代码里的样子：返回 `True` **只是让探路收住**
        （它不让任何一步发生）；而「替人往前走一步」这一版**一条路径都没有**
        （Global Constraints：`c998a72` 那次事故就是替人回了一句「继续」）。
        ⚠️ 读的是**登记表里那一个 job**（不是建图那一刻闭包住的副本）：`reopen` / `_recover`
        都会再拼一次图，而它们要读的必须是同一个标志。登记表里没有它时回 `False`
        （不是抛）—— 那意味着「没有 job 可停」，不是「人没喊停过」之外的事。
        """
        def should_pause() -> bool:
            job = self._jobs.get(job_id)
            return bool(job is not None and job.stop_requested)

        return should_pause

    def _steer_cb(self, job_id: str) -> Optional[Callable]:
        """`Deps.explore(steer=…)`：探路**每一次模型调用之前**问的那一句（Task 9）。

        为什么是这一根线而不是让 `explore` 自己去看 `Job.inbox`：那个登记表是**服务的**，
        探路那一层够不着它（`browser_agent` 不认识 `Job`）—— 形状与 `should_pause` /
        `window_alive` 同一个（**服务手上有、探路要问**的东西都从这里递下去）。

        ⚠️ **开关没打开就回 `None`**（`STEER_WIRED`，今天写死 `False`）：`explore` 于是走它
        默认那条路（`steer=None`，一个字节不变）。这一格与 `/say` 那边读的是**同一个开关**
        —— 半开的通道就是「同一个事实两个名字」：页面说「排队」而话偷偷喂了下去（或者反过来）。

        ⚠️ 回的是 `_SteerLine`（一个带结果的**对象**，不是光秃秃的闭包）：除了「问一句」，
        它还要接住「那一次调用到底发出去了没有」——「已经交给它了」与 `delivered` 都等到
        那一刻才落（回归 1 / F2③）。
        ⚠️ 拿锁：它跑在**工作线程**上（一次 invoke 里面），那条线程**不持** `job.lock`
        （`_advance` 只在改状态那两处短暂拿一下）—— 所以它自己拿
        （`Job.lock` 是普通 `Lock`，**持锁处再调拿锁的函数 = 自己等自己**：判据全走不拿锁的纯核）。
        """
        if not STEER_WIRED or not job_id:
            return None
        return _SteerLine(self, job_id)

    @staticmethod
    def _steer_held(job: Optional[Job]) -> bool:
        """服务**已经知道**这一句话这一趟交不出去（回归 1 / F1a）。

        今天只有一支：**有个还没兑现的「停」** —— 下一轮边界上 `_Gate` 就会把那一轮掐断
        （`should_pause` 读的就是这一格），所以那句话交不出去，`/say` 就不该答应「直达」。

        ⚠️ 它是**已知**那一支的判据，不是「下一轮还会不会来」的兜底：话可能正好说在**最后一轮
        之后**（服务不可能知道，实例 H），也可能交出去之后**那一次调用炸了**（F2）——
        那两种由结尾那一笔（`steer_missed`）说，**不许**拿这一格糊（糊了就是编话）。
        """
        return bool(job is not None and job.stop_requested)

    def _explore_dir(self, job_id: str) -> pathlib.Path:
        """`runtime/explore/<job_id>/`。⚠️ `job_id` 是从 HTTP 进来的字符串 —— 必须挡住 `../`，
        否则一个能爬出去的 id 就等于**任意写**。

        ⚠️ 这道守卫**只写在一处**（`journal.dir_for`）—— 同一份**安全判据**写两遍，
        收紧一处、另一处不动就是一个洞（M-2）。这里只把根换成本服务的。
        """
        return journal.dir_for(self._explore_root, job_id)

    def _next_attempt_no(self, job_id: str) -> int:
        """这是第几次尝试。从**盘上已有的** `attempt-*.jsonl` 数出来 —— 于是服务重启过、
        或者图又进了一次 `explore`，编号都接着走（不会把上一趟的账覆盖掉）。"""
        try:
            done = [int(p.stem.split("-", 1)[1]) for p in self._explore_dir(job_id).glob("attempt-*.jsonl")
                    if p.stem.split("-", 1)[1].isdigit()]
        except (OSError, ValueError):
            return 1
        return (max(done) + 1) if done else 1

    def _journal_for(self, job_id: str, n: int, broken: Optional[list] = None) -> Callable:
        """`on_step`：每一步**发生的那一刻**追加一行（G1：今天一个字节都不落）。

        为什么必须是**当场**而不是跑完再写：窗口就在这一步到下一步之间死掉
        （`operTime`→`closeTime` 那一段）—— 跑完再写的话，死的正是**没写下来的那一段**。

        ⚠️ **旁路坏掉不许带塌主路**（R-19 / 与 Console 那片对 `shooter` 的规矩同一条）：
        账本写不进去**不许**变成「这一步的工具失败了」——那等于把旁路的故障记到产物头上，
        模型还会照着这条假错换一条路走。所以这里**吞掉**异常；但**不许静默**：
        第一个原因记进 `broken` 这个列表，由 `run()` 写进 `journey.notes`
        （这一层够不着 journey，`run()` 那个闭包够得着 —— **两半合起来才成立**）。

        `broken` 由调用方给（**每一趟一份**：`run()` 开头会清空它，见那里的注释）；
        不给就自己造一份（直接调这个方法的人只需要「写下去」这件事）。

        ⚠️ 三种坏法走**同一个出口**（`_remember`）：建路径失败 / 建目录失败 / 写失败 ——
        `ValueError` 那条**也走它**（M-3）：job_id 不像话时返回 no-op 就是**静默**，
        而这个文件自己刚立过「no-op 等于静默」的规矩。生产上那条不可达
        （job_id 是服务端生成的 `job-<12 位 hex>`），但规矩不该有例外。
        """
        broken = broken if broken is not None else []

        def _remember(exc: BaseException) -> None:
            if not broken:
                broken.append("%s: %s" % (type(exc).__name__, exc))

        def _broken(exc: BaseException) -> Callable:
            """每步都记一次「没记成」（只留第一条），而不是当没事发生。"""
            def on_step(step: dict, _exc: BaseException = exc) -> None:
                _remember(_exc)
            return on_step

        try:
            path = journal.attempt_path(self._explore_root, job_id, n)
        except ValueError as exc:
            return _broken(exc)
        except OSError as exc:
            # **连目录都建不出来**（盘满了 / 没权限 / 路径上有个文件）——
            # 返回 no-op 就等于**静默**：这一趟没有账本，而没有任何人看得出来。
            return _broken(exc)

        # ⚠️ **占号**（I-1）：这一趟**跑过**就得留下一个文件 —— 哪怕一步都没走成
        # （空文件），或者整趟都写不进去。理由：`_next_attempt_no` 是**数文件**的
        # （重启/重探都靠它接着编号），不占号的话下一趟会复用同一个号 ⇒
        # 「一趟一个文件」当场失效、两本账（`attempt-*.jsonl` 与 `attempts.jsonl`）对不上。
        try:
            if not path.exists():
                path.touch()
        except OSError as exc:
            return _broken(exc)

        def on_step(step: dict) -> None:
            try:
                journal.append(path, step)
            except Exception as exc:                  # noqa: BLE001
                _remember(exc)
        return on_step

    # ── 闸拍：推进一步之后**把这一轮的眼睛留下**（设计注 §5.5）─────────────
    # ⚠️ 这一节整节是**旁路**（与 journal / 步拍同一条规矩）：拍不成只记一句人话，
    #    **绝不**抛到 `_advance` 上 —— 那会把「一次截图失败」变成「整趟跑挂」。
    #    更要命的是**闸**：抓拍坏掉不许把「停在闸上等人」弄丢
    #    （闸没了 = 人的交互点被吃掉，比没有图坏得多）。

    def _capture_pause(self, job: Job) -> None:
        """跑到闸口（或跑挂了）之后拍一张：`pause-<n>.png`。**不抛**。

        `n` 是**闸拍张数**（`job.pauses`）—— Task 6 的配对规则「第 n 道闸上拍的那张叫
        `pause-<n>`」靠的就是它，所以**拍不成的那一轮也占号**：不占号的话，
        「第 n 轮」与「`pause-<n>`」当场错开，页面会把上一轮的图挂到这一轮上。
        ⚠️ 这一张**跑到头 / 跑挂那一次也拍**（那是「这一趟最后一张图」，不是某一轮的闸
        ⇒ 轮数要比它少一张；算法在 `agent/rounds.py` 的 `count()`）。`%s` 那句人话里
        说的「这一轮」指的是**这一次 advance**，不是某一轮（复审 N5 的同族）。

        ⚠️ **不许在锁里拍**（简报点名）：名字先取（拿一次锁）、拍完再记（再拿一次）。
        攥着 `job.lock` 拍 = 那 0.2 秒里 `GET /job/{id}` 读不动；
        攥着 `self._check.lock` 拍 = 整个单飞的工作线程都在等它。
        """
        with job.lock:
            job.pauses += 1
            n = job.pauses
        name, why = self._shoot_pause(job, n)
        with job.lock:
            job.shot_notes.append({"n": n, "name": name, "why": why})
        if name is None:
            # 目录表第 9 行：这一轮没留下图要**说出来**（why 原文照抄）。
            # 空图框冒充页面是设计注明令禁止的（§3.2 第 6 行）—— 人话里就写着为什么没有。
            self.narrate(job, "shot_missing", SHOT_MISSING_SAY % (why or "没说为什么"),
                         n=n, why=why)

    def _shoot_pause(self, job: Job, n: int) -> tuple[Optional[str], str]:
        """真去拍一张（`_capture_pause` 的下半截）。**不抛** —— 连算落点的 `ValueError` 也收在这儿。"""
        ws_url = str((job.brief or {}).get("ws_url") or "").strip()
        if not ws_url:
            # ⚠️ 这一格比 `capture_via_cli` 里那格更靠前：**压根没有窗口**，
            #    所以一个进程都不该起（那一格管的是「给了串但认不出来」，
            #    它会明说**绝不**退回 127.0.0.1:9222 —— 那是本机的**另一个**浏览器）。
            return None, ("还没开浏览器（这份开场白里没有 ws_url）—— 这一轮没有窗口可拍。"
                          "窗口开出来（`bit.sh open` 那串）之后的轮次才有图。")
        try:
            dest = shots.path_for(job.job_id, root=self._shots_dir) / ("pause-%d.png" % n)
        except ValueError as exc:
            return None, "落点算不出来：%s" % exc
        return self._shoot(ws_url, dest)

    def _shoot(self, ws_url: str, dest) -> tuple[Optional[str], str]:
        """`capture` 跑在**旁路线程**上，`self._shot_timeout` 秒没回来就当它没成（硬超时）。

        为什么要多一层线程（设计注 §5.5 / 计划 §R6）：单飞的工作线程是**唯一**推图的地方
        （D6）—— 拍照那条路（真实现是 `cdp` 子进程）卡住的话，整个服务就停在那儿了。
        超时只丢这一张图：闸照旧在、账照旧记，人话里说清是超时。
        """
        # ⚠️ 二进制**用构造时定下的那个**（`functools.partial` 把它绑死）——
        #    `capture_via_cli` 不给 `cdp_bin` 时会去读环境，而读的时刻是**调用的时刻**：
        #    抓拍在工作线程上，它可能比设那段环境的代码活得久
        #    （全量套件里实测**每趟 2–4 次**漏 —— 竞态量，取决于哪几条「发了 job 不等它」
        #    的用例的 worker 活过了它的 fixture；别把它当仪器读数）。
        capture = (self._capture
                   or functools.partial(shots.capture_via_cli, cdp_bin=self._cdp_bin))
        box: dict = {}

        def work() -> None:
            try:
                box["out"] = capture(ws_url, str(dest), timeout=self._shot_timeout)
            except BaseException as exc:                  # noqa: BLE001 —— 外面世界
                box["boom"] = exc

        worker = threading.Thread(target=work, name="siteforge-shot", daemon=True)
        worker.start()
        worker.join(self._shot_timeout)
        if worker.is_alive():
            return None, ("拍照超过 %.0f 秒还没回来（超时）—— 窗口可能卡住了；"
                          "这张图没留下，闸照旧在" % self._shot_timeout)
        if "boom" in box:
            exc = box["boom"]
            return None, "拍照时它抛了 %s：%s" % (type(exc).__name__, exc)
        out = box.get("out")
        if not (isinstance(out, tuple) and len(out) == 2):
            return None, "拍照没给出（文件名, 人话）这样的结果：%r" % (out,)
        name, why = out
        if not name:
            return None, str(why or "拍不成，而且没说为什么")
        return str(name), ""

    def _shot_note_for(self, job: Optional[Job], name: str) -> Optional[dict]:
        """这一轮**拍过吗**（按文件名反查 `pause-<n>` 那条记录）。没有这个 job 就是 `None`。"""
        if job is None:
            return None
        with job.lock:
            notes = [dict(x) for x in job.shot_notes]
        for note in reversed(notes):
            if name == "pause-%s.png" % note.get("n"):
                return note
        return None

    def shot_file(self, job_id: str, name: str) -> pathlib.Path:
        """`/job/{id}/shot/{name}` 的两个字符串 → 一个**安全**的落点；不像话就 404（人话）。

        三道判据（缺一不可）：
          - `name` 过 `shots.name_ok`（一段、以 `.png` 结尾）—— 这个参数是外面来的；
          - `job_id` 过 `shots.path_for`（**只解析、不建目录**：这是**读**的那一侧，
            用 `dir_for` 就等于「一个 GET 建一个目录」）；
          - 解析完**再确认一次它真的在那个目录里** —— 名字合法不等于路径老实：
            一个指向 `/etc/passwd` 的 `pause-1.png` 也是「一段、以 .png 结尾」。
        """
        if not shots.name_ok(name):
            raise HTTPException(status_code=404, detail=(
                "这个名字不能当图名：%r —— 图名只许是 `pause-3.png` 那样的一段"
                "（字母数字与 . _ -，1–64 字，以 .png 结尾）。这一个参数是外面来的，"
                "带 `/` 或 `..` 的名字能把人带去别的地方读文件。" % (name,)))
        try:
            where = shots.path_for(job_id, root=self._shots_dir)
        except ValueError as exc:
            raise HTTPException(status_code=404, detail="这个任务 id 不能当目录名：%s" % exc)
        path = where / str(name)
        if not _inside(path, where, direct=True):
            raise HTTPException(status_code=404, detail=(
                "这张图不在那个任务的目录里：%s —— 它顺着链接跑到别处去了，不给你读。"
                % name))
        if not path.is_file():
            raise HTTPException(status_code=404, detail=self._no_shot_say(job_id, name))
        return path

    def _no_shot_say(self, job_id: str, name: str) -> str:
        """「没有这张图」的人话。这一轮**拍过、只是没拍成**的话，把那句 `why` 一起带上
        （不然页面上只剩「没有这张图」，而原因明明就在手上 —— 那也是一种静默）。"""
        said = ("没有这张图：%s/%s —— 盘上就没有它。图是**跑到闸口时**才拍的"
                "（一轮一张，`pause-<n>.png`）。" % (job_id, name))
        note = self._shot_note_for(self._jobs.get(job_id), name)
        if note and note.get("why"):
            said += "这一轮拍过，但没拍成：%s" % note["why"]
        return said

    # ── 产物那一格（§十五）：`/job/{id}/artifact` 与 `/live` 的产物那一格 ──
    # ⚠️ 图那一路（`shot_file`）与产物这一路**共用 `_inside` 这一道判定**，但**它挡的东西不一样**
    # （这段注释原来写的是「两个端点都服务一个文件」—— 那已经**不成立**了，产物这一路
    # **一个盘上的字节都不端出去**：端的是 `state["src"]`，取值不碰盘。复审判 A2 点名）：
    #   · 图：挡住「顺着名字/软链把产物目录**外面**的东西**端出去**」（端的就是那个文件）
    #     ⇒ 严一档（`direct=True`：名字是**外面来的**，多一层就多一个可乘之机）；
    #   · 产物：`_inside` 挡的是**读** —— 拿盘上那份来比对（只为决定那句话）之前，
    #     先确认那个路径在产物目录里。少了它，一条被污染的记录（`py_path=/etc/passwd`、
    #     或者指向 `/dev/zero` 那种读不完的东西）会让服务**真去读**那个路径：
    #     任意路径读进内存 / 读爆 / 当存在性-可读性探针用。
    #     ⚠️ 复审判 M9 实测：拿掉它，那一档的话会从「**不去看**」翻成「不是这一趟写下的」
    #     —— 翻的这一下就是「服务真的读了」的证据。
    #   ⇒ 两个理由都要这道闸，**别因为「它不再挡端错字节」就去掉它**。

    def steps(self, job_id: str) -> dict:
        """这一趟**运行**（自测 / 扰动）那本 trace 的**每一步**：三层 + 诊断。**只读**。

        取哪一本：`_selftest_root` 下这个 site **最新**的一本 `*.trace.jsonl`
        （自测会落好几本：baseline / country / delay）。取不到就**照实说** ——
        「这一趟还没跑过」与「跑过但没留下 trace」是两件事，别都回一个空数组
        （那会让人把「没跑」读成「跑了、没问题」）。

        判据**只有一处**（`agent/steps.py`）：页面只搬字，不自己推「这算失败」。
        """
        job = self._jobs.get(job_id)
        if job is None:
            raise KeyError(job_id)
        site = str((job.brief or {}).get("site") or "")
        root = pathlib.Path(self._selftest_root)
        cands = sorted(root.glob("%s-*/*.trace.jsonl" % site),
                       key=lambda p: p.stat().st_mtime, reverse=True) if site else []
        if not cands:
            return {"steps": [], "broken": 0, "trace": "",
                    "say": "这一趟还没跑过（没有可读的运行 trace）"}
        rows, broken = steps.read_trace(cands[0])
        return {"steps": [steps.step_view(r) for r in rows], "broken": broken,
                "trace": str(cands[0].relative_to(root)),
                "say": "这是 %s 那一趟的每一步（%d 步%s）"
                       % (cands[0].name, len(rows),
                          "；另有 %d 行读不动" % broken if broken else "")}

    def artifact_file(self, job_id: str) -> dict:
        """`/job/{id}/artifact` → **这一趟写下的那串字节** + 它下下来叫什么、落在哪；拿不出来就 409。

        ★ **这条路上没有参数可以过**（§15.3）：`job_id` 只是查快照的钥匙。
        一旦有一个参数能影响取哪个文件／哪串字节，它就是**任意文件读取**。
        而端出去的字节来自**这一趟自己的记录**（`state["src"]`，见 `_recorded_bytes`）——
        所以这条路上**一个盘上的字节都不端出去**（盘上那份只用来**比对**，见 `_disk_note`）。

        判据全在 `_artifact_state`（与 `/live` 的产物那一格**同一处**）。
        返回值给路由：`{"bytes", "filename", "path", "say"}` —— **核对过的那串字节就是端出去的
        那串**（同一个 `bytes` 对象，路由不再开一次盘：核对与发送之间不许有第二个动作）。
        """
        view = self._view(job_id)                       # 没这个任务 → KeyError（路由转 404）
        # ⚠️ 跑着 / 排队那两档**不等**（`_snapshot_soon`）：读一次 checkpoint 会排在一次 invoke
        # 后面（A1），而一次点击也不该卡住 —— 那两档的答案本来就是「还没有」。
        soon = str(view.get("status") or "") in (QUEUED, RUNNING)
        snap = self._snapshot_soon(job_id) if soon else self._snapshot(job_id)
        values = dict(getattr(snap, "values", None) or {}) if snap is not None else {}
        state = self._artifact_state(view, values)
        if not state["bytes"]:
            #: ★ 与 `/live` 那一格**同一句**（`_artifact_say`）—— 「为什么没有 py」那行也在。
            raise HTTPException(status_code=409, detail=_artifact_say(values, state))
        return state

    def _artifact_state(self, view: dict, values: Optional[dict] = None) -> dict:
        """这一趟的产物**此刻是什么状态**。★ **唯一一处**判它（端点与页面那格都走它）。

        返回 `{"bytes": bytes|None, "filename": str|None, "path": str|None, "say": <人话>}` ——
        **`bytes` 非空** = 这一趟写下的那串字节拿到了（端点 200、页面那格才有下载）。

        ★ **字节来自记录**（`state["src"]`），不是来自盘上那个文件 ⇒
        A15（§15.5）**无条件成立**：每一趟拿到的是**它自己写下的**那串字节，
        哪怕同一个站点的后一趟已经把 `<out_dir>/<site>.py` 盖掉了。
        盘上那一份**仍然要看一眼**（`_disk_note`），但那是**一条信息**，不是给不给的理由。

        拿不到只有两种情形（都 409 + 一句人话）：① 记录里没有它交付过的证据；
        ② 记录说交付过、可没留下那串字节。
        """
        values = dict(values or {})
        raw = _delivered_path(values)          # ★ 这道闸的唯一写法（与 `_project` 同一句）
        if raw is None:
            return {"bytes": None, "filename": None, "path": None,
                    "say": self._no_artifact_say(view, values)}
        blob = _recorded_bytes(values)
        if blob is None:
            return {"bytes": None, "filename": None, "path": None,
                    "say": ARTIFACT_UNVERIFIABLE_SAY % raw}
        note = self._disk_note(raw, blob, values)
        return {"bytes": blob, "filename": _download_name(raw), "path": raw,
                "say": ARTIFACT_READY_SAY + (("\n" + note) if note else "")}

    def _disk_note(self, raw: str, blob: bytes, values: dict) -> str:
        """盘上那一份**现在是什么**（一句信息；没什么可说的就是 `""`）。

        五种：一样（不说）/ 不是这一趟写下的那串字节 / 没了 / 读不出来 / 路径不在产物目录里（**不去看**）。
        ⚠️ 「不一样」时**不许断言因果**（复审实测：没有第二趟运行、只把文件换掉也会走到那儿）。
        ⚠️ 路径不在产物目录里时**连读都不读**（§15.3）—— 外面那个文件与这一趟的产物无关。
        """
        path = pathlib.Path(raw)
        if not _inside(path, self._products_dir(values)):
            return ARTIFACT_DISK_OUTSIDE_SAY % raw
        if not path.is_file():
            return ARTIFACT_DISK_GONE_SAY
        got, why = _disk_fingerprint(path)
        if got is None:
            return ARTIFACT_DISK_UNREADABLE_SAY % why
        if (got["size"], got["sha256"]) != (len(blob), hashlib.sha256(blob).hexdigest()):
            return ARTIFACT_DISK_DIFFERS_SAY
        return ""

    def _products_dir(self, values: dict) -> pathlib.Path:
        """这一趟的产物目录：**它自己记的那个**（`state["out_dir"]`），没记就按这个部署的算。

        与 `Service.start` 里那句 `brief.setdefault("out_dir", self._out_dir)` 是**同一条规则**
        ——「写到哪」与「算不算在里面」必须是**同一个值**。两套的话会出现一种假拒：
        产物明明写对了、路径也没错，只因为服务配置里的默认值不同就被挡在门外。
        """
        raw = str((values or {}).get("out_dir") or "").strip()
        return pathlib.Path(raw) if raw else pathlib.Path(self._out_dir)

    def _no_artifact_say(self, view: dict, values: Optional[dict] = None) -> str:
        """「这一趟为什么没有可交付的产物」—— **409 的正文与 `/live.artifact.say` 同一句**。

        只覆盖「记录里**没有**它交付过的证据」那一大类；「记录说交付过、可没留下那串字节」
        由 `_artifact_state` 直接给 `ARTIFACT_UNVERIFIABLE_SAY`（本函数不管那一档）。

        ⚠️ **不编原因**：到头了那几档，原因一律**照抄这一趟自己留下的那句话**
        （`end_note` / 跑挂那句 `say`）。撞上限那三种按**时间线上那条事件同一条规则**
        加 `CAP_SAY_PREFIX`（`_note_end`）—— 一处口径，两处显示。
        """
        status = str(view.get("status") or "")
        if status not in (DONE, FAILED):
            return NO_ARTIFACT_YET_SAY % self._status_say(status)
        head = NO_ARTIFACT_HEAD_DONE if status == DONE else NO_ARTIFACT_HEAD_FAILED
        said = str(view.get("say") or "").strip() or NO_ARTIFACT_UNSAID_SAY
        if status == DONE and str((view.get("result") or {}).get("end_reason") or "") in CAP_END_REASONS:
            said = CAP_SAY_PREFIX + said
        return head + "。它自己交代的是：\n" + said

    def _artifact_cell(self, job_id: str, view: dict, values: dict) -> Optional[dict]:
        """`/live.artifact`（§十五 那一格）。**三档**：

        - `None` —— **还没到「写下了 py」那一步**（在跑 / 排队 / 停在闸上）：
          页面上那个位置**不存在**（§15.4：不是灰按钮，是**还没有**）；
        - `{url, filename, path, say}` —— 这一趟**写下的那串字节拿到了**（`bytes` 非空）：
          `url` 非空 = 真的能下；`path` = **它写到哪了**（对账用，§15.2），
          `say` 可能还带一句盘上那份现在是什么（不一样 / 没了 / 读不出来 / 没去看）；
        - `{url: None, filename: None, path: None, say: …}` —— **拿不到**（记录里没有它交付过的
          证据 / 记录里没留下那串字节）：页面摆那句话、**不摆按钮**（§15.2 / A14）。

        ⚠️ 判据是 `_artifact_state`（与端点**同一处**）—— 「能下」这四个字只有一个来源，
        不然就会出现「页面说能下、点下去 409」那种点了没反应的按钮。
        """
        if str(view.get("status") or "") not in (DONE, FAILED):
            return None
        state = self._artifact_state(view, values)
        if not state["bytes"]:
            #: ★ 「为什么没有 py」那一句摆在**第一行**（按停因分类）—— 见 `_no_py_say`。
            return {"url": None, "filename": None, "path": None,
                    "say": _artifact_say(values, state)}
        return {"url": ARTIFACT_URL % job_id, "filename": state["filename"],
                "path": state["path"], "say": state["say"]}

    # ── 两块接线信息（页面不自己编）────────────────────────────────

    def window_public(self, job_id: str = "", status: str = "",
                      values: Optional[dict] = None) -> Optional[dict]:
        """「这个窗口」那一块（设计注 §十）：**只摆事实 + 方法，不编 URL**。

        没接窗口层 → `None`（页面据此**明说**「看不到活窗口」，而不是显示一块空表）。
        `how` / `when` 两句写死在这个文件里（`WINDOW_HOW` / `WINDOW_WHEN`）：页面原样显示。
        身份那三样里缺的（桩窗口、或者别的实现没带）给 `None` —— 不知道就说不知道。

        ⚠️ **给了 `job_id` 才多三格**（Task 12）：`state` / `state_say`（这个 job 的窗口
        现在什么状态，见 `window_state`）+ `can_close`（现在能不能关，**服务说了算**）。
        为什么挂在同一个函数上而不是另起一块：这就是 `/live` 里**同一个 `window` 格**，
        页面也只有那一处渲染它 —— 另造一份口径就是这一片最老的那个病。
        身份那五格是**部署级**的（不随 job 变），状态那三格是**这一趟**的，所以分开取。
        """
        window = self._window
        if window is None:
            return None
        out = {"worker": getattr(window, "worker_ip", None),
               "bit_id": getattr(window, "bit_id", None),
               "api_port": getattr(window, "port", BIT_API_PORT),
               "how": WINDOW_HOW, "when": WINDOW_WHEN}
        if job_id:
            out.update(self.window_state(job_id))
            out["can_close"] = self.window_closable(status)
            #: 「重开窗口，接着走」那个按钮在不在（`reopen` 接不接得住这一趟）。
            #: ⚠️ 判据与端点**同一处**（`_resume_point_from`）—— 页面要是自己拿
            #: `state` / `status` 推一遍，就会出现「按钮在、按下去 409」那种点了没反应的形状。
            #: ⚠️ 用**调用方已经读过的那份 values**（`live()` 手上就有）：在这儿再
            #: `_snapshot` 一次会在「跑着」那一档**排队等写锁**（A1 明令不许）。
            out["can_reopen"] = self._reopenable(values, status)
        return out

    def _reopenable(self, values: Optional[dict], status: str) -> bool:
        """这一趟现在能不能「重开窗口接着走」—— `can_reopen` 那格的判据。

        与 `/reopen` 端点**同一个判据**（`_resume_point_from`），差的只是 values 从哪来：
        端点自己读快照，这里用 `/live` 已经读过的那份。
        """
        return self._resume_point_from(values or {}, {"status": str(status)}) is not None

    def window_state(self, job_id: str) -> dict:
        """这个 job 的窗口**现在什么状态** —— 人话 + 一个机器格（Task 12）。

        ⚠️ **读的是那条已经在跑的时间线**（`runtime/explore/<job>/window.jsonl` 的最近一行，
        由 `_window_probe_loop` 每 `_probe_seconds` 秒记一行），**不是**当场再问一次 Bit：
        `/live` 每 3 秒被点一次，当场问等于把「15 秒一眼」改成「每次轮询都打一个接口」。
        ⇒ **一份读数、一个来源**：这里只把最近那一行翻译成人话 + 说出它是**什么时候**量的
        （一个不带时刻的状态会被人当成「此刻」，而它可能是 14 秒前的）。

        没接过窗口层 / 一行都还没有 / 那一行读不出来 → `unmeasured`（**不知道就说不知道**）。
        """
        row: dict = {}
        try:
            row = dict(self._last_window_row(job_id) or {})
        except Exception:                      # noqa: BLE001 —— 旁路读不动不许带塌这一格
            traceback.print_exc()
            row = {}
        raw = str(row.get("alive") or "")
        if raw not in WINDOW_STATE_SAY:
            return {"state": WINDOW_UNMEASURED,
                    "state_say": WINDOW_UNMEASURED_SAY % int(self._probe_seconds)}
        # ⚠️ 时刻**并进那句话里**，不另给一格：同一件事两个出口 = 两个真相源
        # （页面要是把 `at` 自己排一遍，那句话与那一格哪天就会对不上）。
        return {"state": raw,
                "state_say": WINDOW_STATE_SAY[raw]
                             + self._measured_at_say(str(row.get("at") or ""))}

    @staticmethod
    def _measured_at_say(at: str) -> str:
        """「这是哪一刻量的」那半句（Task 12）。读不出来就明说读不出来 —— 不印一个空括号。"""
        try:
            t = datetime.datetime.fromisoformat(at)
        except (TypeError, ValueError):
            return "（这一格是什么时候量的，读不出来。）"
        return "（这是 %s 问的。）" % t.strftime("%H:%M:%S")

    def window_closable(self, status: str) -> bool:
        """现在能不能关这个窗口 —— **服务说了算**（页面不猜、也不自己算）。

        两条判据：
          ① 这个部署真给得了 `close`（没接窗口层就是没有可关的东西）；
          ② 它**没在跑**（`running` / `queued` 不给关）。
        ⚠️ 第 ② 条是这一格的**全部意义**：agent 正在那个窗口里点、填、滚，把窗口抽走
        就是把一次跑到一半的活弄死（`WINDOW_WHEN` 那句写死的规矩说的就是这件事）。
        ⇒ 闸上（`waiting`）/ 跑完 / 跑挂**都给关** ——「停在闸上是唯一适合人接管的时刻」，
        而「接管完了，现在可以关了」正是人那个时候会做的下一件事。
        """
        if self._window is None or not hasattr(self._window, "close"):
            return False
        return str(status) not in (RUNNING, QUEUED)

    def shots_note(self) -> str:
        """**降级 B** 那句话（设计注 §5.5）：每步抓拍开着 → `""`；关着 → 一句人话。

        ⚠️ 判据走 `shots.step_shots_on()` —— 与 `explore` **同一份读法**。
        这里要是自己再解析一次（哪怕只差一个 `strip`），就会出现
        「图没了、一个字没解释」= 设计注明令禁止的**静默降级**。
        """
        if shots.step_shots_on():
            return ""
        return SHOTS_OFF_SAY % self._shot_price_say()

    @staticmethod
    def _shot_price_say() -> str:
        """「一张图多少钱」那半句。**没给实测数就不吹具体数字**（那是个猜测，写上去就成了事实）。"""
        raw = str(os.environ.get("SITEFORGE_SHOT_SECONDS") or "").strip()
        if not raw:
            return ("每步抓拍被关掉了（`SITEFORGE_STEP_SHOTS=0`）——"
                    "这里没有实测的每张耗时，就不编一个数字。")
        try:
            seconds = float(raw)
        except ValueError:
            return ("每步抓拍被关掉了（`SITEFORGE_STEP_SHOTS=0`）——"
                    "`SITEFORGE_SHOT_SECONDS=%r` 不是一个数，实测耗时读不出来。" % raw)
        return "截图实测 %.1f 秒/张，太贵。" % seconds

    def _note_attempt(self, job_id: str, *, started: str, journey, boom: BaseException = None) -> None:
        """一次尝试收场 → `attempts.jsonl` 一行（墙钟 / 轮数 / 步数 / 停因）。

        ⚠️ **`rounds` 没量到的那些路一律记 `None`，不许记 0**（Task 3 遗留 3）。
        `_Stop`（人喊停 / 预算到顶 / 计划停滞 / **窗口没了**）一穿出 `run_tool_loop`，
        `rounds` 那个局部变量就没了 —— 记 0 会被读成「这一趟没花轮数」，于是 M3 偏低，
        而偏低看起来像好消息（`measure.record_attempt` 的 docstring）。

        ⚠️ 判据走 `browser_agent.rounds_measured(journey)`，**不在这里再比一次
        `stop_reason == "paused"`**：那个写法在本片新增 `window_gone` 之后就已经漏了
        （复审 I-5 点名的正是这条遗留）。两处各写一份 = 早晚分家。
        """
        if not job_id:
            return
        try:
            path = self._explore_dir(job_id) / "attempts.jsonl"
            if journey is None:
                why = "%s: %s" % (type(boom).__name__, boom) if boom is not None else "没有账本"
                measure.record_attempt(path, started_at=started, ended_at=measure._now(),
                                       rounds=None, steps=None, path_shape=None,
                                       stop_reason="failed", notes=["这一趟连账本都没生成：" + why])
                return
            measured = browser_agent.rounds_measured(journey)
            steps = list(getattr(journey, "steps", []) or [])
            measure.record_attempt(
                path, started_at=started, ended_at=measure._now(),
                rounds=int(getattr(journey, "rounds", 0) or 0) if measured else None,
                steps=len(steps),
                stop_reason=str(getattr(journey, "stop_reason", "") or ""),
                # M9 的载体（**一次样本一存**）：分支站的两次跑长度不同，只有存下每趟的形状，
                # M10 的跨度才算得出来（§2.2）。
                path_shape=measure.path_shape(steps),
                #: ★ 2026-09-22（用户问「大概生成一个脚本多少钱」）：**这一趟的 token 账落盘**。
                #: `journey.usage` = `llm.summarize` 的产物（`prompt_tokens` / `completion_tokens`
                #: / `reasoning_tokens` / `rounds` / `tool_calls` / `elapsed_ms`）。
                #: ⚠️ 它原先**只活在内存**（进 checkpoint）⇒ 服务一重启就**再也读不回来**
                #: （真事：那一趟跑完、我重启之后，它的消耗就凑不出来了 ✗）——
                #: **成本必须落盘**，不然「这一趟贵不贵」只能靠记忆。
                usage=dict(getattr(journey, "usage", None) or {}),
                notes=list(getattr(journey, "notes", []) or [])[-6:])
        except Exception:                      # noqa: BLE001
            traceback.print_exc()

    def _last_window_row(self, job_id: str) -> Optional[dict]:
        """上一行时间线（判「PID 换了吗」只能靠它）—— 从盘上读，服务重启也不丢。"""
        try:
            rows = [r for r in measure.read_rows(self._explore_dir(job_id) / "window.jsonl")
                    if "_corrupt" not in r]
        except Exception:                      # noqa: BLE001
            return None
        return rows[-1] if rows else None

    def _window_lifecycle(self) -> dict:
        """`/browser/detail` 的 `operTime` / `closeTime` —— 窗口**开于/关在**哪一刻（§3.1）。

        为什么要它（M6）：探针每 15 秒才看一眼，它给的寿命**带着一个探测间隔的误差**；
        而 `operTime → closeTime` 是**精确的**那一对 —— 判「固定租约 vs 空闲回收」
        看的正是这个差**恒不恒定**（§3.1 的人给的判据）。

        ⚠️ 只在窗口状态**变了**的那一刻读（开/死各一次），不进常规轮询：
        常规探活用 `pids/alive` 就够了，每 15 秒多打一个接口是白花的。
        `closeTime` 没关时是**当天零点**（实测 `2026-09-16 00:00:00`）—— 认它 = 认「还没关」。
        """
        if self._window is None or not hasattr(self._window, "detail"):
            return {}
        try:
            data = dict(self._window.detail() or {})
        except Exception:                      # noqa: BLE001 —— 读不到就是读不到，不许编
            return {}
        out: dict = {}
        oper = str(data.get("operTime") or "").strip()
        if oper and not oper.endswith("00:00:00"):
            out["oper_at"] = oper
        close = str(data.get("closeTime") or "").strip()
        if close and not close.endswith("00:00:00"):
            out["close_at"] = close
        return out

    def _probe_window_row(self, job_id: str, *, at: Optional[str] = None,
                          note: str = "") -> dict:
        """一次探活 → 时间线一行（落 `window.jsonl`）。

        探不出来（没有窗口层 / 接口答非所问）→ 记 `unknown`，**不许记成死**。
        """
        probe = {"alive": None, "pid": None}
        try:
            if self._window is not None:
                probe = (self._window.probe() if hasattr(self._window, "probe")
                         else {"alive": self._window.alive(), "pid": None})
        except Exception:                      # noqa: BLE001
            traceback.print_exc()
            probe = {"alive": None, "pid": None}
        row = measure.window_row(probe, at=at or measure._now(), note=note,
                                 prev=self._last_window_row(job_id))
        if row["new_window"] or row["alive"] == "dead":
            row.update(self._window_lifecycle())   # 开/死各读一次（§3.1 的 operTime/closeTime）
        measure.append_row(self._explore_dir(job_id) / "window.jsonl", row)
        return row

    def _start_window_probe(self) -> None:
        """起一条窗口时间线探针（只在**能给 PID** 的窗口层上起 —— 桩窗口没有 PID，
        那样的时间线只有活/死，判不出「重开了几次」）。"""
        if self._window_probe_thread is not None or self._window is None:
            return
        if not hasattr(self._window, "probe"):
            return
        t = threading.Thread(target=self._window_probe_loop, name="window-timeline", daemon=True)
        self._window_probe_thread = t
        t.start()

    def _window_probe_loop(self) -> None:
        while True:
            time.sleep(self._probe_seconds)
            job_id = self._active_job
            if not job_id:
                continue
            try:
                self._probe_window_row(job_id)
            except Exception:                  # noqa: BLE001 —— 旁路不许把工作线程带死
                traceback.print_exc()

    def _write_baseline(self, job_id: str, *, end: Optional[dict] = None) -> Optional[dict]:
        """把这一趟的账压成 `baseline.json`（M1~M8）。**能算的算，算不出来的给 None + 为什么。**"""
        try:
            d = self._explore_dir(job_id)
            rows = [r for r in measure.read_rows(d / "window.jsonl") if "_corrupt" not in r]
            steps: list = []
            # 按**数字**排（`attempt-10` 排在 `attempt-2` 后面）：字符串序会把两次尝试
            # 的步**接反**，而 M9 的「状态序列」是靠顺序读出来的。
            for p in sorted(d.glob("attempt-*.jsonl"), key=measure.attempt_no):
                steps.extend(r for r in measure.read_rows(p) if "_corrupt" not in r)
            return measure.baseline(
                d / "baseline.json",
                window_lifetimes=measure.window_lifetimes(rows),
                attempts=measure.read_attempts(d / "attempts.jsonl"),
                end=dict(end or {}), window_rows=rows,
                path_steps=steps, probe_seconds=self._probe_seconds)
        except Exception:                      # noqa: BLE001
            traceback.print_exc()
            return None

    def _measure_after(self, job_id: str) -> None:
        """job 停下时：记一行时间线 + 汇总一份 baseline。**全程吞异常**（旁路不许带塌主路）。"""
        try:
            self._probe_window_row(job_id, note="job 停在这一刻")
        except Exception:                      # noqa: BLE001
            traceback.print_exc()
        end: dict = {}
        try:
            values = dict(getattr(self._snapshot(job_id), "values", None) or {})
            end = {"end_reason": values.get("end_reason") or "",
                   "delivered": bool(values.get("delivered"))}
        except Exception:                      # noqa: BLE001
            traceback.print_exc()
        self._write_baseline(job_id, end=end)

    def _clean_window_for_explore(self, brief: dict) -> None:
        """**探路也要在干净会话里跑**（R-F1 的另一半，2026-09-17 裁定）。

        为什么：生产**每一单都是新窗口**（`clearCookiesBeforeLaunch` 只在启动那一刻生效），
        所以生产遇到的第一个东西往往是**cookie 同意弹层**。而探路要是跑在一个
        「同意过 cookie」的会话里，它**学到的是一条没有弹层的路** —— 账本里没有那一步，
        产物到了生产（有弹层）就会点到弹层上。这不是 cookie 一件事，是**系统性的**：
        探索的条件必须与自测/生产一致，否则账本学的路径在生产里不成立。

        做法：这个部署给得了 `fresh_open` 就换一个干净窗口（清 cookie/缓存），
        把新 ws_url 写进 brief（探路与后面所有步骤都用它）。
        ⚠️ 换不了（没接窗口层 / 窗口服务抖了）时**照旧用调用方给的那个**，
        把原因记在日志里 —— 那是「条件更差」，不是「这一单不能跑」。
        ★ 2026-09-22 补的那一半：**调用方一个都没给，而这里又没换成** —— 那就**没有**窗口
        可用（上面那句「条件更差」管辖的是「手上还有一个」的情形）。原因同时记进
        `brief[WINDOW_OPEN_FAILED]`，由 `start()` **在开 job 之前**用 502 挡下来 ——
        不这么办的话，那一趟会**注定死**（探路那格现在会如实停，但人看不到外面那句原话、
        也没有可做的动作）。
        """
        if self._window is None or not hasattr(self._window, "fresh_open"):
            return
        try:
            ws = self._window.fresh_open()
        except Exception as exc:                     # noqa: BLE001 —— 外面世界
            brief[WINDOW_OPEN_FAILED] = str(exc)
            print("[siteforge] 探路前换干净窗口没成（%s）—— 用调用方给的那个窗口接着跑"
                  "（账本学的路径可能带着「弹层已经点过」的前提）" % exc)
            return
        if ws:
            brief["ws_url"] = str(ws)
        else:
            brief[WINDOW_OPEN_FAILED] = "开窗口没给出新的 `ws_url`（空串）"

    def _fresh_session_cb(self) -> Optional[Callable]:
        """R-F1 那根线：自测之前换一个**干净会话**（关旧窗 → 开新窗，返回新的 ws_url）。

        - 这个部署没接窗口层、或窗口层给不了 `fresh_open` → `None`：图**照跑**，
          但在 `selftest` 的 facts 与 `diagnose` 里**说清「这一次不是干净会话」**
          （不是跳过、不是假装干净 —— 判据一个字不改）。
        - 接上了 → 真回调。**换失败要抛**：图接住它，把「不是干净会话」如实记下再照跑 ——
          条件差不是产物不行，但读报告的人必须知道。
        """
        if self._window is None or not hasattr(self._window, "fresh_open"):
            return None

        def cb() -> str:
            ws = self._window.fresh_open()
            if not ws:
                raise RuntimeError("换干净会话没给出新的 ws_url")
            return str(ws)
        return cb

    def _viewport_cb(self, ws_url: Optional[str] = None) -> Optional[Callable]:
        """窗口层那根线（第 4 遍扰动要换窗口大小）。

        - 没人点名要它（载荷里 `set_viewport=false`）→ 返回 `None`：**图会在 `intake`
          就结束这一趟**并点名「缺 `set_viewport`，谁给得了」—— 那是 R-31 要的诚实停止，
          不是缺陷。⚠️ 是**结束**不是「停在闸上等人」：`intake` 2026-09-20 起不设闸
          ⇒ 这条路 `/reply` 与 `/reopen` **都是 409**（见模块 docstring §2）。
        - 要了、但这个部署没接窗口层 → `_intake_problems` 已经在**提交那一刻**拒了。
        - 要了、也接了 → 真回调：**先写配置，再量活窗口**。量出来没变就**抛**
          （`selftest` 会把这一遍记成「没跑」，而「没跑」不算过，R-5）。
          尺寸用自测那一步给的那个（`selftest.run` 按 `DEFAULT_VIEWPORT` 调），服务不替它定。
        """
        if self._window is None or not hasattr(self._window, "set_viewport"):
            return None

        def cb(width, height):
            self._window.set_viewport(width, height)
            got = self._viewport_probe(ws_url) if ws_url else None
            if got is None:
                # **量不出来 ≠ 做成了**：没有 cdp / 连不上 / ws_url 不认识时探针给 None，
                # 而「没量到」被当成「没问题」的话，第 4 遍会被记成**跑过了**，
                # 于是产物带着「折叠/遮挡/坐标假设验过了」出门 —— 而一个数都没量到。
                # 抛出去的后果是**对的**那一头：`selftest.run` 把回调抛错记成
                # 「这一遍没跑」（`selftest.py:475`），不是把整跑杀掉。
                raise RuntimeError(
                    "换窗口大小之后**量不出活窗口现在多大**（没有 cdp 二进制 / 连不上 / "
                    "ws_url 认不出来），所以这一遍扰动没法诚实地说自己做成了。"
                    "把它当成「没验到」：要么修好这根线（`SITEFORGE_CDP_BIN` / 窗口还活着），"
                    "要么明确放弃第 4 遍（把 \"viewport\" 写进 `allow_skips`）。")
            if tuple(got) != (int(width), int(height)):
                raise RuntimeError(
                    "把窗口换成 %sx%s 了，但**活着的那个窗口**量出来还是 %sx%s —— 这一遍扰动"
                    "等于没做。Bit 的窗口尺寸是**启动时**生效的（实测：写配置回 success、"
                    "回读也是新值，活窗口纹丝不动）。所以第 4 遍要真跑，得**关掉重开**："
                    "要么放弃这一遍（写进 allow_skips），要么把「关窗口 → 改尺寸 → 重开 → "
                    "换 ws_url」做成一条流程 —— 那要改自测的接口（现在五遍共用一个窗口）。"
                    % (width, height, got[0], got[1]))
        return cb

    def _probe_graph(self):
        """一个只用来 `get_state()` 的图（不跑节点）—— 服务重启后靠它把 job 读回来。

        ⚠️ 它建在**本服务的** checkpointer 的**读连接**上（不是 `graph_factory` 那个、
        也不是写连接）：一个 job 的图是调用方拼的，而「这个 job 现在什么样」这件事得由一个
        **确定接在同一份状态上**的东西来回答（R-19：状态住在 saver 里 —— 那就得问同一个 saver）；
        而**读**这条线不该排在一次 `invoke` 后面（那个可能跑几分钟）。
        """
        if self._probe is None:
            self._probe = graph.build(checkpointer=self._check.reader(), deps=graph.Deps())
        return self._probe

    def _cfg(self, job_id: str) -> dict:
        return {"configurable": {"thread_id": job_id}}

    def _snapshot(self, job_id: str):
        """读这个 job 的状态。

        - **服务自己拼的图**（生产，`graph_factory is None`）→ 走**读连接**：
          读不跟正在跑的那次 `invoke` 抢写锁（那个可能持几分钟）。
        - **调用方自己拼的图** → 读也问它那张图（它接在哪份 saver 上，它最清楚）。
        """
        job = self._jobs.get(job_id)
        if self._graph_factory is None and self._check.separate_reader:
            with self._check.reader_lock:
                return self._probe_graph().get_state(self._cfg(job_id))
        g = job.graph if (job is not None and job.graph is not None) else self._probe_graph()
        with self._check.lock:
            return g.get_state(self._cfg(job_id))

    def _snapshot_soon(self, job_id: str):
        """**不等**地读一次状态：写锁被占着就立刻回 `None`（**不排队**）。

        Task 8 / A1 的正身：`/live` 在**跑着**那一档**不许读 checkpoint** ——
        而「不许读」要落到机械上，就是这一条：读的东西与 `_snapshot` **一模一样**
        （同一个 saver、同一张图），差的只有「等不等」。别把它读成第二个真相源。

        为什么非这样不可：内存 saver / 调用方给的 saver / `graph_factory` 这三种形态下，
        一次读会**排在那次 invoke 后面**（`_advance` 整段持着写锁），真站点上几分钟 ——
        而页面每 3 秒轮询一次：整屏冻在那里，人按了停也只会转圈。
        （生产的 Postgres 形态有第二条读连接，本来就不排队 —— 这一条是给另外三种形态的，
        而「测试与嵌入式部署」正好就是那三种。）
        """
        job = self._jobs.get(job_id)
        if self._graph_factory is None and self._check.separate_reader:
            with self._check.reader_lock:            # 读连接：从来不与写抢（生产形状）
                return self._probe_graph().get_state(self._cfg(job_id))
        g = job.graph if (job is not None and job.graph is not None) else self._probe_graph()
        if not self._check.lock.acquire(blocking=False):
            return None                              # 有人在写（它正在跑）⇒ 这一次不读
        try:
            return g.get_state(self._cfg(job_id))
        finally:
            self._check.lock.release()

    # ── 时间线：**唯一的写入口**（Task 4；契约 `docs/执行事实契约-2026-09-18.md`）────
    # 目录表那九条触发点各自的调用点见 `_advance` / `start` / `reply` / `reopen` /
    # `_recover` / `_capture_pause`；这里放的是**入口**与几个共用的小工具。
    # ⚠️ 这一节整节是**旁路**（与 journal / 闸拍同一条规矩）：记时间线**绝不许**把
    #    主路带塌 —— 但「读不回状态」那一支是**响的**（记一条 `state_unreadable`），
    #    因为那正是「没有静默的路径」在**读**那一侧的样子。

    def narrate(self, job: Job, kind: str, say: str, *, who: str = "system", **data) -> dict:
        """往这个 job 的时间线上记一条 —— **谁都别直接碰 `job.timeline`**。

        为什么要只有一个口子（计划 §「跨任务接口」1）：人话纪律与七格的形状是靠
        「只有一条路进来」守住的；直接 `add` 的地方一多，「给旧的 `step` 换个名字」就会长回来。

        回调是从**工作线程**里来的（探路的步、抓拍、闸口），所以 `job.lock` 只包**一次**
        append（微秒级）：绝不在这里读快照、起进程、发请求。
        形状不对（`events.Timeline.add` 那几条：空 `say`、第四个 `who`、判断词当字段名…）**抛** ——
        那是编程错误，不是运行时状况（人话写不出来就说明还没想清）。

        ⚠️ **人话里写不出去的字节在这儿换掉，并当场说出来**（2026-09-18，Task 4 收口复审
        点名的那个洞）：`/live` 的返回值最后要过一遍 `.encode("utf-8")`，而**一个孤立代理对
        过得了 `json.dumps`、过不了那一次编码** —— 结果是 `/live` **500、整条时间线一条都
        读不出来**（不是那一条坏掉）。那几句人话里混着**外面来的字**（页面上的 url、
        运营写的期望），所以这条缝正好在这条路上。
        换掉而不是抛：抛掉整条事件 = **这一步的记录没了**，而那正是这份契约要治的病
        （契约 §二②：「看不见」是一等值）。换完在人话尾巴上报个数，读的人知道少了什么。

        ⚠️ 它**只管外壳那一层**（`say`）：`data` 里出现这种值仍然由 `events._facts` 当场拒
        —— 那是写的人的编程错误，不是外面来的东西（外面来的那些在转抄时就已经换过了，
        见 `browser_agent._utf8_safe`）。
        """
        safe_say, replaced = events.safe_value(say)
        if replaced:
            safe_say += ("（这条人话里有 %d 个字节线上写不出来（孤立代理对），"
                         "已按 `�` 记 —— 不是它本来长这样。）" % replaced)
        with job.lock:
            return job.timeline.add(kind, safe_say, who=who, data=data or None)

    def _step_teller(self, brief: dict, job_id: str, broken: Optional[list] = None) -> Callable:
        """`on_step` 的**第二个读者**：探路的一步 → 时间线上**两条**事件。

        为什么是**两条**而不是一条七格齐全的（契约 §二那张表是一行七格）：
        这个 schema 的**每一条事件只有一张嘴**（`who`），而七格是**两方填的** ——
        脚本填前五格、服务填 `verdict`、运营填 `expect`。合成一条，那条事件就得用
        **一个** `who` 说出两方的话，而 `SCRIPT_MAY_NOT_FILL` 那条闸（脚本不许填
        `verdict` / `expect`）正是靠「谁在说」执行的 —— 合成一条要么得关掉那道闸，
        要么得让服务替脚本签名。两种都是「承重的不是有哪几格，是**谁填**」被折掉。

        所以照着**人**来分（契约 §二 的原话）：

        | 事件 | `who` | `say` | `data` |
        |---|---|---|---|
        | 脚本报了这一步 | `agent` | 脚本自己的人话（「点了「下一步」」） | 前五格 |
        | 服务核了这一步 | `system` | **裁判那句话** | `verdict` + `expect` |

        两格口径不同，正是因为它们是**两个人在说话** —— 而那正是契约 §一 要的东西
        （今天病根是「判断和执行是同一方」）。
        """
        expects = list(brief.get("expects") or [])
        #: 「第 i 项换了几个」（门口数好的，见 `EXPECTS_UNWRITABLE`）—— 与 `expects` 一起
        #: 在**建这根线的时候**取一次：判每一步时手上要有的就是这两样。
        expects_unwritable = tuple(brief.get(EXPECTS_UNWRITABLE) or ())
        broken = broken if broken is not None else []

        def tell(step: dict) -> None:
            job = self._jobs.get(job_id)
            if job is None:
                # **不许静默**：探路在报步，可这个 job 不在登记表里 —— 时间线没地方记。
                # 但不抛：`_explore_for(...)` 返回的那个 `run` 是可以**直接调**的
                # （测试与将来的调用方都这么用，它们的 job_id 本来就不在登记表里），
                # 抛出去会把「这一趟探路」整个带塌 —— 而旁路坏掉**不许带塌主路**
                # （与 `_journal_for` 那条一模一样的规矩）。
                # ⚠️ 进的是**时间线自己那一本**账（`timeline_broken`），不是账本那本 ——
                # 两件事各有各的说法：混成一条，读的人会以为是 journal 缺了步。
                if not broken:
                    broken.append("第 %s 步没记上（job %s 不在登记表里）"
                                  % (step.get("step_no"), job_id))
                return
            self._note_step(job, step, expects, expects_unwritable)

        return tell

    def _note_teller(self, job_id: str, broken: Optional[list] = None) -> Callable:
        """`on_note`：模型**每一轮**说的话 → 时间线一条 `agent_said`（Task 5）。

        为什么这一条要单独一根线（设计注 §3.3 原话）：那是**它的推理** ——
        「我能充当他的眼睛或者纠错员」那句话里最需要的那一半，
        而今天它只在跑完之后才看得到（`journey.notes` 里躺着，还要展开）。

        `say` **逐字转抄**（`AI 说：…` 那整句，与 `journey.notes` 里那一行是同一句）：
        转抄不是改写 —— 换一个字，读的人就是在读服务的话而不是它的话，
        而这一片的承重句正是「承重的不是有哪几格，是**谁填**」（契约 §二①）。

        ⚠️ 与 `_step_teller` 一模一样的两条：job 不在登记表里**不抛**（抛会把这一趟
        探路整个带塌），但**不许静默**（原因进 `timeline_broken`，由 `run()` 写进
        `journey.notes`）。
        """
        broken = broken if broken is not None else []

        def tell(said: str) -> None:
            job = self._jobs.get(job_id)
            if job is None:
                if not broken:
                    broken.append("模型这一轮的话没记上（job %s 不在登记表里）" % job_id)
                return
            self.narrate(job, "agent_said", said, who="agent")

        return tell

    def _run_teller(self, job_id: str) -> Callable:
        """`on_run`：自测**每一遍**跑完 → 时间线一条 `selftest_run`（Task 5）。

        `say` = `Run.label` + `Run.note` **原文**（设计注 §3.2 第 3 行的形状）——
        那两句本来就是人话（「第 4 遍：换个窗口大小再跑…」+「这一遍没跑：…」），
        照搬，不重写、不再判断一次。

        ⚠️ **没跑的那几遍也要说**（`skipped` / `not_needed`）：它们正是「哪一类失败这次
        **没验到**」的载体，只在报告里看得见就等于没人看见（R-5 治的就是这个病）。

        ⚠️ 没有 job 可记时**抛**（与 `_note_teller` 不同，理由见那一头）：自测的播报在
        外面**没有** `journey.notes` 那样的落点，能看见它的只有 `selftest.run` 的护栏 ——
        而护栏正是照「回调抛了」来处置的（记进 `Report.narrate_broken`，随报告回到
        叫它的那一层）。**吞掉才是静默**：那样服务和人都不会知道这一趟的时间线少了每一遍。
        """
        def tell(run: Any) -> None:
            job = self._jobs.get(job_id)
            if job is None:
                raise RuntimeError(
                    "自测的那一遍没地方播报（job %s 不在登记表里）—— 时间线挂在这个 job 上，"
                    "没有它就无处可记。" % job_id)
            data = {"run": str(getattr(run, "name", "")),
                    "status": str(getattr(run, "status", ""))}
            step_no = getattr(run, "failed_step", None)
            if isinstance(step_no, int):
                data["failed_step"] = step_no
            self.narrate(job, "selftest_run",
                         "%s\n%s" % (getattr(run, "label", ""), getattr(run, "note", "")),
                         **data)

        return tell

    def _note_step(self, job: Job, step: dict, expects: list,
                   expects_unwritable: tuple) -> None:
        """一条探路的步 → 时间线那两条事件（见 `_step_teller` 的表）。

        `expects_unwritable`：**第 i 项**换了几个字节（门口数的，`EXPECTS_UNWRITABLE`）——
        ⚠️ **不给默认值**：漏了它 = 那一步「换了字节却不说」（静默路径），
        而漏一个参数是**当场炸**、不是悄悄少说一句话（后者正是这条线要治的病）。


        **前五格一个字都不动**（脚本写什么就是什么，这一层只转抄）—— 除了一件事：
        缺席与 `None` 是两件事，而 `Timeline` 要求「写了 `None` 就得配一句 `why`」。
        脚本没解释的那些格，这里如实补一句「**脚本没说为什么**，但这一格确实是
        「看不见」而不是「没变化」」—— 补的是**这件事本身**，不是替它编一个原因。
        """
        step_no = step.get("step_no")
        cells = {"action": {"what": str(step.get("action") or ""),
                            "target": step.get("target")},
                 "receipt": step.get("receipt"),
                 "sig_before": step.get("sig_before"),
                 "sig_after": step.get("sig_after")}
        if isinstance(step_no, int):
            cells["step_no"] = step_no
        why = dict(step.get("why") or {})
        for cell, value in cells.items():
            if value is None and not str(why.get(cell) or "").strip():
                why[cell] = ("脚本把这一格写成了空的，而 `why` 里没有它的解释 —— "
                             "照契约 §二②，空 = 「**看不见**」这个一等值，**不是**「没变化」；"
                             "原因没人说，这里也不替它编。")
        if why:
            cells["why"] = why
        script_say = str(step.get("note") or "").strip() or (
            "第 %s 步（`%s`）：脚本这一步没留下人话。" % (step_no, cells["action"]["what"]))
        self.narrate(job, "step", script_say, who="agent", **cells)

        # ── 第 6、7 格：期望是运营的（从载荷来），判是**这里**算的 ──────────────
        present, expect = _expect_at(expects, step_no)
        verdict, verdict_say = judge_step(
            step_no=step_no, receipt=step.get("receipt"),
            sig_before=step.get("sig_before"), sig_after=step.get("sig_after"),
            expect=expect, expect_present=present)
        judged = {"verdict": verdict}
        if present:
            # 运营写的字也是**外面来的**：门口（`_Intake`）已经换过了 —— 这儿再换一次是
            # **幂等**的（换过的值再换一遍数出来是 0），留着它的用处是：这一格进 `data`，
            # 而 `_facts` 那道闸拒的是**写代码的人**的编程错误，不该由它兜外面来的字。
            judged["expect"] = events.safe_value(expect)[0]
        if isinstance(step_no, int):
            judged["step_no"] = step_no
        # ⚠️ **这条期望里换了几个字节，要说在判这一步的这句话里**（修复轮 1）：
        # 门口换掉之后 `judge_step` 那句人话里已经没有坏字节了 ⇒ `narrate` 的外壳**没得报**；
        # 而 `text_appears` 那一支的裁判话是**固定的一句**（`_meets` 不引期望原文），
        # 从前那道缝换掉时**一声不吭** —— 这条静默路径就是这么来的。
        # 个数是**逐项**带上来的：说的是**这一步**这一条，不是整张表（多报一个是假话）。
        replaced = (expects_unwritable[step_no - 1]
                    if present and isinstance(step_no, int)
                    and 1 <= step_no <= len(expects_unwritable) else 0)
        if replaced:
            verdict_say += "\n" + (UNWRITABLE_BYTES_SAY % replaced)
        self.narrate(job, "step", verdict_say, **judged)

    def _where_it_stopped(self, job_id: str, snap=None) -> tuple:
        """它停/走在**哪一步**：`(节点名, 人话)` —— 「窗口没了」那句话的 `%s` 与 `/live` 的 `stage`。

        三档，**全是从快照里读出来的**（读不出来就写「不知道哪一步」，绝不编）：
          ① 有闸口 → 闸在问哪一步（那正是它这一趟接着要做的事，也是设计注里
             「它停在「写这一版 py」之前」那个例子）；
          ② 没闸口但有 `next` → 图下一步要跑的节点；
          ③ 都没有 → `visits` 里最后落下的那一步。

        `snap` 是**调用方手上已经有的那一份**（Task 8 加的，可选）：一次读在真 saver 上
        就是一次查询，手里已经有了就不该再读一次。不传 = 自己读（与以前一模一样）。
        ⚠️ 它**不会**替你等写锁 —— 要「不等」的那一档用 `_snapshot_soon`（A1）。
        """
        unknown = ("", UNKNOWN_STEP_SAY)
        if snap is None:
            try:
                snap = self._snapshot(job_id)
            except Exception:                  # noqa: BLE001 —— 读不出来就说不知道
                traceback.print_exc()
                return unknown
        values = dict(getattr(snap, "values", None) or {})
        gates = self._interrupts(snap)
        if gates:
            value = gates[0].value if hasattr(gates[0], "value") else gates[0]
            step = str((value or {}).get("step") or "")
            if step:
                return step, STEP_SAY.get(step, step)
        nxt = tuple(getattr(snap, "next", None) or ())
        if nxt:
            node = str(nxt[0])
            return node, STEP_SAY.get(node, node)
        visits = [str(v) for v in (values.get("visits") or [])]
        if visits:
            return visits[-1], STEP_SAY.get(visits[-1], visits[-1])
        return unknown

    def _note_window_died(self, job: Job, values: dict, *, dead: Optional[bool] = None) -> None:
        """目录表第 1 行：窗口**从「不是没了」翻成「没了」**的那一刻记一条。

        ⚠️ 三个判据（少一个就成了另一种毛病）：
        - **只有明确说死了才算**（`_window_is_gone`：问不出来一律当不知道 —— 不许误杀）；
        - **只有那一翻才记**：每次 `_advance` 返回都去问，但同一件事不记第二遍；
        - **重开窗口之后要能再记**（`reopen` 把 `window_dead` 清掉）——
          换的那个窗口也会死，那是一条**新**事实。
        `dead` 是**已经问过了**的那个答案（`reply()` 手上就有）：传进来就不必再问一次
        （每 15 秒多打一个 `/browser/pids/alive` 是白花的 —— 同一个理由）。
        """
        if job.window_dead:
            return
        ws_url = values.get("ws_url") or (job.brief or {}).get("ws_url")
        if not (self._window_is_gone(ws_url) if dead is None else dead):
            return
        token, where = self._where_it_stopped(job.job_id)
        with job.lock:
            job.window_dead = True
        self.narrate(job, "window_died", WINDOW_DEAD_SAY % where,
                     where=token, ws_url=str(ws_url or ""))

    def _note_end(self, job: Job, values: dict) -> None:
        """目录表第 6 行：快照里已经有终局 → `done` / `cap_hit`。

        `done` 说的是「**图走到了 END**」（与 `DONE` 那个状态同一个意思，
        **不是**「成了」—— 成没成看 `end_note` 的原话与 `/live` 的 `delivered`）。
        撞上限（`revision_cap` / `lint_cap` / `selftest_cap`）单独一个 `kind`：
        那是**它自己的一个结论**（再来一次还是同样的地方不过），人话前面加「撞上限了：」。
        """
        reason = str(values.get("end_reason") or "")
        if not reason:
            return                              # 没到头（停在闸上 / 还在跑）—— 没有终局可说
        note = str(values.get("end_note") or "").strip()
        if reason in CAP_END_REASONS:
            say = CAP_SAY_PREFIX + (note or "（快照里没写是撞了哪条上限 —— 这本身就不正常。）")
            self.narrate(job, "cap_hit", say, end_reason=reason, end_note=note)
            self._note_steer_missed(job)      # 到头了 ⇒ 没送到的话也要说（F1b）
            return
        self.narrate(job, "done", note or (END_UNSAID_SAY % reason),
                     end_reason=reason, end_note=note)
        self._note_steer_missed(job)

    def _note_after_advance(self, job: Job, *, ended: bool) -> None:
        """一次 `_advance` 返回之后要记的那几件事（目录表第 1、6 行 + Task 8 的停）。

        ⚠️ 顺序：**先现场，后结论** —— 「窗口还在不在」决定了下一步能不能走，
        「这一趟到头了」是这一跳的结果。
        ⚠️ `ended=False` 是**跑挂**那一支：那儿只记现场，**不许**记 `done`
        （「跑挂 ≠ 跑成」：快照里可能还留着上一次的 `end_reason`，照抄它就成了假话）。
        ⚠️ 「停」的兑现（A3）**两条路都要走**：跑挂也意味着这一步跑完了，那个标志同样要还回去
        （不还的话，`reopen` 之后探路会一上来就自己停住 —— 人根本没再按过）。
        """
        try:
            snap = self._snapshot(job.job_id)
            values = dict(getattr(snap, "values", None) or {})
            # ⚠️ `ended=False`（跑挂那一支）时**不许**说「它停在闸上等着你」：那一刻
            # 快照里可能还留着上一次那道闸（节点里抛时状态没往前走），而这一趟是**跑挂**了，
            # 不是在等人。同一件事已经在上面那条 `failed` 里说过了。
            at_gate = bool(self._interrupts(snap)) if ended else False
        except Exception as exc:               # noqa: BLE001 —— 旁路，但**响**
            traceback.print_exc()
            raw = "%s: %s" % (type(exc).__name__, exc)
            self.narrate(job, "state_unreadable", STATE_UNREADABLE_SAY % raw, error=raw)
            # 读不回来也要把那个按钮还回去（不清 = 它**永久**按不动，A3）——
            # 而「状态读不回来」这件事本身已经记过了（上面那一条）。
            self._note_stop_landed(job, snap=None, at_gate=None, ended=False)
            return
        self._note_stop_landed(job, snap=snap, at_gate=at_gate, ended=ended)
        if at_gate:
            # 出口①：**停在闸上了** —— 答应过直达的话到这儿还没送到，就要说回来（NEW-1 / O2）。
            # ⚠️ 只在真停在闸上时（`at_gate` 是从快照的闸口投影出来的，不是「大概」）。
            self._note_steer_missed(job, at_gate=True)
        self._note_window_died(job, values)
        self._note_shots_missing(job, values)     # 目录表第 6 行的**步拍**那一半
        self._note_narration_broken(job, values)  # 播报那条旁路自己坏了（修复轮 1）
        if ended:
            self._note_end(job, values)

    def _note_stop_landed(self, job: Job, *, snap, at_gate: Optional[bool],
                          ended: bool) -> None:
        """有一个**还没兑现**的停请求，而这一步已经跑完了 —— 「停」这件事**兑现了**（A3）。

        为什么必须清（A3 的代价那栏，一个字不改）：`console.html:696` 是
        `btnStop.disabled = over || stop.requested === true` —— **不清的话那个按钮永久按不动**，
        而人正看着一道**本来就等着他**的闸。到闸上，「停」就兑现了：人就在那儿，闸本来就是停。

        为什么必须**说出来**（「没有静默的路径」）：清掉的是他按过的那一下；
        而且它答得出**落在哪** —— 那正是按下去那一刻那句承诺要的答案（两句话不同：
        落在闸上 / 这一趟停下来了）。

        ⚠️ 三个判据照 `_note_window_died`：真按过才清、**只清一次**（标志位自己就是
        「说过了」的记号）、认的是**事实**（闸还在不在）而不是「跑了几次」。

        ⚠️ **同一份快照只有一套信任口径**（修复轮 1 / M-1；字句在修复轮 3 / NEW-R3 收准）：
        跑挂那一支（`ended=False`）**不信手上这份快照** —— `at_gate`、`end_reason`、
        `interrupts`（节点名）三格一个都不用。跑挂时快照里留着的是**上一趟**的结论
        （上一趟那道闸、上一趟的 `paused`），只信其中一格就会说出一句这一趟不成立的话。
        ⚠️ 节点名那一格改用 `Job.running_step`（**采样时刻**的那次样）—— 采样本身也是一次读
        （A2），所以这**不是**「名字一定新鲜」，而是「同一份数据不在同一个函数里被两套口径对待」。
        """
        with job.lock:
            if not job.stop_requested:
                return
            job.stop_requested = False
            promised = str(job.stop_say or "")
            job.stop_say = job.stop_where = ""
        if at_gate is None:
            say = STOP_LANDED_BLIND_SAY
            token = ""
        elif ended:
            # 兑现落在哪：从**这一步跑完之后的**状态里读（此刻 invoke 已经结束 —— 读是安全的，
            # 而且手上就有那一份快照，不必再读一次）
            token, human = self._where_it_stopped(job.job_id, snap)
            if at_gate:
                say = STOP_LANDED_GATE_SAY % human
            else:
                say = STOP_LANDED_OVER_SAY % human
                if str((getattr(snap, "values", None) or {})
                       .get("end_reason") or "") == END_PAUSED:
                    say += STOP_LANDED_PAUSED_ADD
        else:
            # 跑挂那一支：**不信手上这份快照**（NEW-2）—— `at_gate` / `end_reason` /
            # `interrupts` 一个都不用（节点名正是从 `interrupts` 来的）。改用
            # `Job.running_step`：**采样时刻**的那次样，也正是按「停」的时候告诉过他的
            # 那个词（A2）—— 两处不许打架。
            # ⚠️ **别把这句话读成「那个名字一定不是过期数据」**（修复轮 3 / NEW-R3）：
            # 采样本身也是一次读，它读的就是同一份 checkpoint —— 快照**在采样之前**就已经
            # 过期时，两条路给出同一个名字（复审探针 F-a：出厂代码与「改回读快照」输出逐字相同）。
            # 这一条钉的是**同一份数据不在同一个函数里被两套口径对待**，不是「名字一定新鲜」。
            token = str(job.running_step or "")
            human = STEP_SAY.get(token, token) if token else UNKNOWN_STEP_SAY
            say = STOP_LANDED_OVER_SAY % human
        self.narrate(job, "stop_landed", say, where=token, promised=promised)

    def _sample_running_step(self, job: Job) -> None:
        """把「这一步在跑哪个节点」记进 `Job.running_step`（A2）—— 在**写锁还没拿**的时刻采。

        为什么要有这一格：`/say` `/stop` `/live` 唯一有用的那一档正是「跑着」，
        而**那一刻读一次 checkpoint 会一直等到这一步跑完**（A1 的三种形态；真站点上几分钟）
        —— 人按了停，浏览器转圈转到这一步跑完，那个按钮就等于没有。

        ⚠️ **不是第二个真相源**：同一个 `_where_it_stopped` 在安全时刻采的那一次样。
        `_enter()` 在每个节点开工**之前**都 `interrupt()` ⇒ 从一次 resume 到下一道闸之间
        恰好只有一个节点体在跑 ⇒ 这一格在整个 `running` 窗口里都是准的。
        """
        token, _ = self._where_it_stopped(job.job_id)
        with job.lock:
            job.running_step = token

    def _note_shots_missing(self, job: Job, values: dict) -> None:
        """目录表第 6 行的**步拍**那一半：图没拍成 → 时间线上一条（Task 5）。

        为什么要有这一条：第 6 行原先只有**闸拍**那一半（`_capture_pause` 的
        `shot_missing`），而探路里每一步自己也在拍（`shots_dir` 那条线）——
        那些拍不成的时候，原因今天只落在 `journey` 上（`step["shots_why"]` /
        `journey.shots_why`），**时间线上一个字都没有**：一张空白的步拍图框
        与「这一步没有图是因为窗口连不上」在页面上长得一模一样，而设计注
        §3.2 第 6 行明令不许让空图框冒充页面。

        两种来源都认（都是「图没留下」这件事的载体）—— 而**每一支的句子都不一样**
        （修复轮 1 的 Important-2：一致不该靠抹平两个事实来达成）：
          - `step["shots_why"]`：**那一步**的图没成（`.get` 读 —— 没这个字段的
            journey 一个字节都不受影响）→「这一步没留下图」；
          - `journey.shot_failures`：步拍**当场**记的那本只增的账（修复轮 2/3）——
            带 `when` 的 = 某一步的（同上那句）；不带 `when` 的（`_safe`，步拍自己的
            代码抛了）= 够不着哪一步 ⇒ 只说这一路，**不编「哪一步」**；
            `capped` 的 = 撞上 `MAX_KEPT_SHOTS`、**从这一步起不再拍**
            （修复轮 3：那不是「拍不成」，是**知道的**）⇒ 单独一句，话说清「不是漏了」。

        ⚠️ **四支一支都不能省**（修复轮 3 的正身）：`capped` 那一支原先只有
        `journey.notes` 一句话，而 `notes` **不上时间线** —— 于是上限一生效，
        从那一步起**既没有图、也没有账、也没有事件**，页面上就是一个没人解释的空图框。
        那正是设计注 §3.2 第 6 行（本片的行）要治的形状。

        ⚠️ **为什么扫的是那本只增的账，而不是 `journey.shots_why`**（修复轮 2 的正身）：
        那一格状态说的是「这条**路现在**坏着吗」（拍成了就清，Minor-5 要的就是它），
        而**残留状态天生会漏掉「发生又消失」的事实** —— 一张没成、下一张成了，
        于是时间线上一条都没有，读的人以为一切顺利，可那一刻确实出过事。
        这不是假设：修复轮 1 那行清空就是这么把一条真事件抹掉的（复审判的洞）。
        **那一刻的事只有当场记下来才留得住**，所以出口是只增的账、不是残留状态。

        ⚠️ **射程：只有最后一趟**（修复轮 1 的 Minor-4）。重探时**前几趟**的 Journey
        不进 state（`graph.explore` 只把最后一次的 `out["journey"] = journey` 留下），
        所以前几趟的步拍失败**这一条线看不见** —— 那是简报设计本身带来的形状，
        不是这里漏了。要让前几趟也说出来，得让图把每一趟的账都留下（不在这一片）。

        ⚠️ **同一句只报一次**（`job.shots_reported`）：拍照坏掉通常每一步都坏，
        而且这本账**只增** —— 不按「那句话」去重就会每推一步把同一句再报一遍。
        ⚠️ 读 journey 的那几行是**防御性**的（属性可能缺、步理论上可能不是字典），
        但 `self.narrate(...)` **不吞异常** —— 那与 `_note_window_died` / `_note_end`
        **一模一样**：`narrate` 抛是**编程错误**（形状写歪了），吞掉它就等于把
        「时间线上少一条」变成静默（说得准比说得好听重要）。
        """
        journey = values.get("journey")
        if journey is None:
            return
        whys = []                                 # [(why, step_no|None, 哪一支)]
        for step in list(getattr(journey, "steps", None) or []):
            try:
                why = str(step.get("shots_why") or "").strip()
            except AttributeError:                # 不是字典的步（不该有）—— 跳过它，不抛
                continue
            if why:
                whys.append((why, step.get("step_no"), "step"))
        for row in list(getattr(journey, "shot_failures", None) or []):
            try:
                why = str(row.get("why") or "").strip()
                # 哪一支（修复轮 3 起有三种）：知道是哪一步的 / 撞上上限不再拍的 /
                # 够不着哪一步的（`_safe`）。
                which = ("capped" if row.get("capped")
                         else ("step" if row.get("when") else "channel"))
            except AttributeError:                # 同上：不是字典的记录，跳过
                continue
            if why:
                whys.append((why, None, which))
        for why, step_no, which in whys:
            with job.lock:
                if why in job.shots_reported:
                    continue
                job.shots_reported.add(why)
            data = {"why": why}
            if isinstance(step_no, int):
                data["step_no"] = step_no
            # **四句话四个事实**（修复轮 1 的 Important-2 + 修复轮 3）：**这一步**没了 /
            # 探路里**整条步拍路**坏了（说不出哪一步）/ **到顶了不再拍**（知道的）/
            # 闸上**那一轮**那张没了（最后那一句在 `_capture_pause` 里）。
            # 四句必须读得出来是哪一件 —— 而**每一件都要说出来**（一句都不许省）。
            say = {"step": STEP_SHOT_MISSING_SAY,
                   "channel": STEP_SHOT_CHANNEL_SAY,
                   "capped": STEP_SHOT_CAPPED_SAY}[which] % why
            self.narrate(job, "shot_missing", say, **data)

    def _note_narration_broken(self, job: Job, values: dict) -> None:
        """**播报那条旁路自己坏了** → 时间线上一条（Task 5 修复轮 1，Important-1）。

        为什么要有它：`selftest.run` 的护栏把「回调抛了」记进 `Report.narrate_broken`
        —— 那是「**旁路坏掉不许带塌自测**」那一半；另一半「**没有静默的路径**」在那一刻
        还没兑现：自测那一层够不着时间线，报告要等到这里（`_advance` 返回、`report`
        已经在 state 里）才有人读得到。

        不加这一条会怎样：那个 `except` 就是**一条只有报告知道、页面上一个字都没有的
        异常** —— 而它**不属于**「时间线自己坏了所以记不上」那一类（时间线好得很，
        是回调自己抛了，比如 job 不在登记表里那种编程错误）。全局约束的字面是
        「**任何一个 `except`** 都要有一条对应的时间线事件」。

        去重：同一个原因只报一次（`job.narration_reported`）—— 报告会一直躺在 state 里，
        而每次 `_advance` 返回都会来读一遍。
        """
        report = values.get("report")
        for reason in list(getattr(report, "narrate_broken", None) or ()):
            why = str(reason or "").strip()
            if not why:
                continue
            with job.lock:
                if why in job.narration_reported:
                    continue
                job.narration_reported.add(why)
            self.narrate(job, "narration_broken", NARRATION_BROKEN_SAY % why, why=why)

    def _note_human_said(self, job: Job, job_id: str, body: ReplyRequest,
                         *, superseded: str = "") -> None:
        """目录表第 8 行：人的原话 + **这句话去哪了**。

        ⚠️ 没有 note 的那次「继续」**也要有一条**（那是最常见的一次交互）：
        不记的话「人按了什么」在时间线上是空白。只是它不能说「这句话带进去了」（没有话）。
        ⚠️ 这句话的 `who` 是 `"you"` —— 页面靠它决定气泡长相。
        `superseded`（修复轮 2 / NEW-1）：这一次**服务本来要摆给他的那一句没摆**
        （他送下去的是**别的**）—— **同一件事的两半**（他按下去的那一句 + 服务本来要摆给他的
        那一句），所以并进**同一条**气泡里，而不是另起一条（分开写会让这件事看起来像两件事）。
        ⚠️ 这一段原来用的是**意图语**（**替他编了一个他没做过的动作** —— 服务不知道他屏幕上
        画的是哪一句）：修复轮 4 / F3 改掉了，规矩与词表见 `HUMAN_SAID_SUPERSEDED_SAY` 上面那段。
        """
        note = str(body.note or "").strip()
        token, where = self._where_it_stopped(job_id)
        if note:
            say = "%s\n%s" % (note, HUMAN_SAID_THROUGH_SAY)
        else:
            say = HUMAN_SAID_PLAIN_SAY % where
        if superseded:
            say += "\n" + (HUMAN_SAID_SUPERSEDED_SAY % superseded)
        # ⚠️ 他打的字里要是混着**线上写不出来**的字节（`/reply` 的 `note` 是外面来的），
        # 消毒在载荷进来的那一刻做过（`_Intake`）—— 那一句并在这儿（Task 8 补丁 A）。
        say += body.unwritable_say()
        self.narrate(job, "human_said", say, who="you",
                     reply=str(body.action or ""), note=note, step=token)

    def _something_is_ahead(self) -> bool:
        """交上去的这一刻，**前面还有没有别的 run**（目录表第 3 行那一半）。

        两样事实：队列里压着活、或者正有一个 job 在跑（单飞：一次只有一个在窗口上）。
        ⚠️ 这是**快照**，不是保证 —— 判完队列还可能变。所以只在**真说得出「前面有东西」**
        时才说「排队等窗口」：漏说一句只是少一句话，说反了就是编话。
        """
        if not self._queue.empty():
            return True
        with self._jobs_lock:
            return any(j.status == RUNNING for j in self._jobs.values())

    # ── 排队与跑 ──────────────────────────────────────────────────
    def _ensure_worker(self):
        with self._worker_lock:
            if self._worker is None or not self._worker.is_alive():
                self._worker = threading.Thread(target=self._work, name="siteforge-worker",
                                                daemon=True)
                self._worker.start()

    def _submit(self, job: Job, payload) -> None:
        self._ensure_worker()
        self._queue.put((job, payload))

    def _work(self):
        while True:
            job, payload = self._queue.get()
            try:
                self._advance(job, payload)
            except BaseException as exc:             # noqa: BLE001 —— 工作线程**不许**死
                traceback.print_exc()
                self._note_escaped(job, exc)
            finally:
                self._queue.task_done()

    def _note_escaped(self, job: Job, exc: BaseException) -> None:
        """`_advance` 里**逃出来**的东西（最后一层网）—— 不许静默，更不许报「在跑」。

        今天能走到这儿的只有「`narrate` 自己抛了」（形状判据是设计成编程错误的），
        而那正好是**时间线坏掉**的那一刻 —— 所以这一层**不许**依赖 narrate 成功。
        两件事的次序就是照这个排的：

          ① **先把状态改对**：`/live` 再也不许说「在跑」。一句会一直说下去的假话
             （job 永远不会再动，因为没人推它了）比一条记不上的事件坏得多；
          ② 再试一次 narrate（记不上也已经在日志里了 —— 时间线此刻本来就是坏的）。

        ⚠️ 图要是已经到头（`DONE`）或者已经挂过（`FAILED`），这一层**不动它**
        —— 状态本来就是诚实的，没有谎要收；那种情况下少的是**时间线里的一条**，
        而时间线坏了的时候，任何一条事件都记不上（那条路只剩日志）。
        （登记表里只有 `queued` / `running` / `done` / `failed` 四种；「在等人」是从
        checkpoint 投影出来的，从来不写进登记表 —— 所以这里不必考虑它。）
        """
        raw = "%s: %s" % (type(exc).__name__, exc)
        with job.lock:
            if job.status not in (QUEUED, RUNNING):
                return                               # 状态是诚实的，别覆盖它
            job.status = FAILED
            job.error = raw
            # ⚠️ **跑挂 ≠ 没交付**（复审 R1 / R1′）：图可能**已经交付**了，是这一步之后
            #    炸的（抓拍、落账、saver 抖一下都算）—— 所以这句话在**两个出口**里
            #    用的是**同一个常量**（`STEP_FAILED_SAY`）。各写一遍就会出现
            #    「一个改准了、另一个还是假话」（复审判实测过：`_advance` 那道 except
            #    里那句说真说假**全量 0 红**）。
            job.say = STEP_FAILED_SAY % exc
            said = job.say
        try:
            self.narrate(job, "failed", said, error=raw)
        except Exception:                            # noqa: BLE001 —— 网里的网：这一层不能再抛
            traceback.print_exc()

    def _advance(self, job: Job, payload) -> None:
        """把图往前推一步 —— **这是唯一一个 job 会动的地方**（单飞）。

        抛出来的东西一律变成 `failed`：一个跑挂的 job **绝不许**被读成跑成了
        （它 `result` 为 `None`，状态是 `failed`，人话里留着原始错误）。
        ⚠️ 「一律」的边界：`try` **只包**「说一句在跑 + 推图」那两句。except 里那条 narrate
        自己再抛、或者 `_capture_pause` / `_note_after_advance` 抛，会从 `_advance` 里
        **逃出去** —— 那一路归 `_work` 的最后一层网（`_note_escaped`），它先改状态再试一次记。
        """
        # ⚠️ **最上面这一句**（A2）：此刻上一次 invoke 已经结束、这一次还没开始，
        #    而 `_work` 只有一个工作线程 ⇒ 写锁没人拿 ⇒ 读快照是安全的。
        #    跑起来之后再想读它，就是「等这一步跑完」（A1）—— 那是这一片最贵的那个坑。
        self._sample_running_step(job)
        with job.lock:
            job.status = RUNNING
            job.say = RUNNING_SAY
        try:
            # 目录表第 4 行：拿到 job 就说「在跑」（与 `/job/{id}` 上那句**同一句**）。
            # ⚠️ 这一条必须在 `try` **里面**（复审 2026-09-18 实测）：写在 try 外面的话，
            #    它一抛就绕过下面那个 except —— 时间线一个字节没变、`job.status` 停在
            #    `running`、`/live` 一直报「在跑」，而全部后果只是 `_work` 的一行 print。
            #    「没有静默的路径」在这儿的正身就是：**记不下这一条，也要说它失败了**。
            self.narrate(job, "running", RUNNING_SAY)
            with self._check.lock:                   # 一个 saver 连接不被两个线程同时用
                out = job.graph.invoke(payload, self._cfg(job.job_id))
        except BaseException as exc:                 # noqa: BLE001 —— 包括 _Stop 之类的 BaseException
            with job.lock:
                job.status = FAILED
                job.error = "%s: %s" % (type(exc).__name__, exc)
                job.say = STEP_FAILED_SAY % exc
                said, raw = job.say, job.error
            self._measure_after(job.job_id)          # 旁路：跑挂了也要留账（吞异常）
            # 目录表第 5 行：跑挂了**也要说**（原始错误进 `data`，人话不把它盖掉）。
            # ⚠️ 放在抓拍**之前**：抓拍最坏要等 20 秒，而「它挂了」人该立刻看见。
            self.narrate(job, "failed", said, error=raw)
            # 跑挂了那一屏更该看得见 —— 同一个出口、同一条纪律（旁路，不抛）。
            # ⚠️ 这条路上 `FAILED` **先**落（人该立刻看见它挂了），图随后才到 ——
            #    所以这一刻的快照里可能还没有这一轮的 note，下一次读就有。
            self._capture_pause(job)
            self._note_after_advance(job, ended=False)   # 只记现场（跑挂 ≠ 跑成）
            # 跑挂是**到头了**的一种（这一趟不会再有下一轮）⇒ 没送到的话要在这儿说（F2②）。
            self._note_steer_missed(job)
            return
        self._measure_after(job.job_id)              # 旁路：记一行时间线 + 汇总 baseline
        # ⚠️ 闸拍放在**这里**：`invoke` 之外（写锁已经放开）、`job.lock` 也没拿着 ——
        #    拍照那 0.2 秒（最坏 20 秒）里不该按着整个服务（简报点名的第一条）。
        self._capture_pause(job)
        with job.lock:
            # 登记表只补「正在跑 / 跑挂了」这两件 checkpoint 答不了的事。
            # 「停在等人」还是「跑到头了」、以及**为什么停**，一律**从 checkpoint 投影**
            # （状态的唯一真源在 saver 里，R-19）—— 所以这里不再存一份 `say`。
            job.status = DONE
            job.say = ""
        self._note_after_advance(job, ended=True)    # 目录表第 1、6 行

    # ── 服务重启之后：从 checkpoint 把 job 捡回来（R-19）───────────────
    def _recover(self, job_id: str) -> Optional[Job]:
        """登记表里没有这个 job，但 checkpoint 里有 → 就地从状态里把它捡回来。

        这是 R-19 在服务侧的正身：**状态住在 saver 里，不在进程里的对象里**。
        没有它，「中断之后恢复不了」只是从图那一层挪到了服务这一层 ——
        服务一重启，人就没法让那次运行接着走了。

        ⚠️ 有一件东西 checkpoint 里**没有**：调用方在开场白里说的那个 `set_viewport`
        （那是服务这一层的开关，不是图的状态）。所以捡回来的 job 用的是
        「**这个部署有没有窗口层**」—— 这是安全的：给上那根线只会让第 4 遍扰动**真跑**，
        永远不可能变成「静默跳过」（R-5 禁止的是跳过，不是执行）。
        """
        snap = self._snapshot(job_id)
        values = dict(getattr(snap, "values", None) or {})
        if not values:
            return None
        keep = ("url", "goal", "mode", "success_text", "evidence", "site", "ws_url",
                "form_file", "env", "platform", "out_dir", "allow_skips", "entry_url")
        brief = {k: values[k] for k in keep if values.get(k) is not None}
        brief["set_viewport"] = bool(self._window is not None
                                     and hasattr(self._window, "set_viewport"))
        job = Job(job_id=job_id, brief=brief, status=DONE, say=RECOVERED_SAY, recovered=True,
                  created_at=datetime.datetime.now().astimezone().isoformat(timespec="seconds"))
        job.graph = self._build_graph(brief, job_id)
        with self._jobs_lock:
            self._jobs.setdefault(job_id, job)
            landed = self._jobs[job_id]
        if landed is job:
            # 目录表第 7 行：捡回来的 job 要**说** —— `job.say` 下一次 `_advance` 就把它冲掉了
            # （P9），而「这个任务是捡回来的」是**系统已经知道**的一件事。
            # ⚠️ 只记在**真的落进登记表**那一个上（两个线程同时捡的时候，另一个那份时间线
            #    没人看得到 —— 记在它上面等于没记）。
            self.narrate(landed, "recovered", RECOVERED_SAY)
        return landed

    # ── 投影：把 checkpoint 变成给人看的那个东西 ─────────────────────
    def _view(self, job_id: str) -> dict:
        job = self._jobs.get(job_id)
        if job is not None:
            status, say, error = job.snapshot_for_view()
            if status == FAILED:
                return {"job_id": job_id, "status": FAILED, "delivered": False,
                        "say": say or "这一步没跑成，停下了。", "error": error,
                        "result": None, "gate": None, "site": job.brief.get("site")}
            if status in (QUEUED, RUNNING):
                return {"job_id": job_id, "status": status, "delivered": False,
                        "say": say or ("排队等窗口（前面还有别的 run 在用）" if status == QUEUED
                                       else "在跑。"),
                        "error": None, "result": None, "gate": None,
                        "site": job.brief.get("site")}
        snap = self._snapshot(job_id)
        values = dict(getattr(snap, "values", None) or {})
        if not values and job is None:
            raise KeyError(job_id)          # 登记表没有、checkpoint 也没有 = 没这个任务
        return self._project(job_id, snap)

    def _project(self, job_id: str, snap) -> dict:
        values = dict(getattr(snap, "values", None) or {})
        gates = [g for g in self._interrupts(snap)]
        base = {"job_id": job_id, "delivered": False, "error": None,
                "site": values.get("site"), "gate": None, "result": None}

        if gates:
            value = gates[0].value if hasattr(gates[0], "value") else gates[0]
            value = dict(value or {})
            step = str(value.get("step") or "")
            return {**base, "status": WAITING,
                    "say": str(value.get("say") or "停下来了，在等你一句话。"),
                    "gate": {"step": step, "step_say": STEP_SAY.get(step, step),
                             "ask": value.get("say"), "facts": value.get("facts") or {},
                             "can": value.get("can") or []}}

        end_reason = str(values.get("end_reason") or "")
        #: ★ 这道闸只有一处写法（`_delivered_path`）—— 产物那一路读的是**同一句**：
        #: 两处各写一遍「交付过没有」，迟早会漂成两个答案（本片病史：同一个事实两个名字）。
        py_path = _delivered_path(values)
        delivered = bool(py_path and pathlib.Path(py_path).is_file())
        report = values.get("report")
        note = str(values.get("end_note") or "").strip()
        return {**base, "status": DONE, "delivered": delivered,
                "say": note or ("这一趟跑完了，但没说清是怎么结束的（state 里没有 end_reason）—— "
                                "这本身就不正常，别把它当成功。"),
                "result": {"end_reason": end_reason, "delivered": delivered,
                           "py_path": str(py_path) if py_path else None,
                           "site": values.get("site"),
                           "visits": list(values.get("visits") or []),
                           "say": note,
                           "selftest": self._report_brief(report)}}

    @staticmethod
    def _interrupts(snap) -> list:
        """中断可能挂在 `snapshot.interrupts` 上，也可能在 `tasks[*].interrupts` 里。

        两处都看 —— langgraph 的版本间这块换过位置，只认一处会在升级时**静默**变成
        「没有中断」（那会把「在等人」读成「跑完了」）。
        """
        out = list(getattr(snap, "interrupts", None) or ())
        if out:
            return out
        for task in (getattr(snap, "tasks", None) or ()):
            out.extend(list(getattr(task, "interrupts", None) or ()))
        return out

    @staticmethod
    def _report_brief(report) -> Optional[dict]:
        if report is None:
            return None
        runs = [r.as_dict() if hasattr(r, "as_dict") else dict(r)
                for r in (getattr(report, "runs", None) or ())]
        return {"passed": bool(getattr(report, "passed", False)),
                "say": report.summary() if hasattr(report, "summary") else "",
                "runs": runs}

    # ── `/live`：页面的**唯一**数据源（Task 4 先出骨架）────────────────
    def live(self, job_id: str) -> dict:
        """`GET /job/{id}/live` 的正文（设计注 §8.2；这一版是**骨架**）。

        为什么合成一份一次给完（§8.3 第 1 条）：页面只有一个 `job_id` + 一个定时器，
        取一份 JSON 就画完。分成几个端点会让「时间线说在跑、卡片还显示在等人」这种
        **自相矛盾**的画面变得可能。
        **字节不进 JSON**：图走 `/job/{id}/shot/{name}`（文件名带轮号、内容永不变）。

        状态与人话**只有一份口径**：`status`/`say`/`delivered` 直接取 `_view`（不编话）。
        时间线**不持久**（§3.5）：不在登记表里（重启过）或者是捡回来的 → `note` 明说。

        **轮次与闸**（Task 6）：`rounds` / `gate` / `stage` 走 `rounds.project` 那一跳
        （`agent/rounds.py`，纯函数 —— checkpoint + 闸拍清单 + 接线信息 → 一屏卡片）。
        这一层只做三件事：把输入凑齐、把投影回来的那几格填上、把该说的话并进 `note`。
        ⚠️ **闸只在 `waiting` 时非 null**（跑着/排队/到头了都没有闸）：那一格是
        页面「还能不能按」的判据，露着头就是一个按钮（`rounds.project` 里再兜一次底）。

        ⚠️ **状态读不回来**时的两条口径（**不一样**，因为读发生的地方不一样）：
          - 跑着 / 排队 / 跑挂那三档：`_view` 不读 state ⇒ `_live_facts` 兜得住 ⇒
            **200 + 一句人话**（`LIVE_STATE_UNREADABLE_SAY` 进 `note`）；
          - **停在闸上 / 到头了**那两档：`_view` 自己就要读 state（在 `_live_facts` **之前**）
            ⇒ 兜不住 ⇒ **503 + 一句人话**（`LIVE_STATE_UNREADABLE_503`，不是裸 500）。
            「没这个 job」那条路照旧 `KeyError` → 404。
        """
        try:
            view = self._view(job_id)             # 没这个 job 就 KeyError → 路由转 404
        except KeyError:
            raise
        except Exception as exc:                  # noqa: BLE001 —— 读不回状态：响，但说人话
            traceback.print_exc()
            raw = "%s: %s" % (type(exc).__name__, exc)
            raise HTTPException(status_code=503, detail=LIVE_STATE_UNREADABLE_503 % raw)
        job = self._jobs.get(job_id)
        timeline = job.timeline if job is not None else None
        shown = timeline.all() if timeline is not None else []
        note = RESTART_NOTE if (timeline is None or job.recovered) else ""
        truncated = bool(timeline is not None
                         and (timeline.dropped() or len(timeline) > len(shown)))
        events_note = self._truncated_say(timeline, len(shown)) if truncated else ""
        # ⚠️ **跑着那两档不许读 checkpoint**（A1/A2）：`stage` 取自进程里那一格采样。
        token, where = self._stage_now(job, job_id, view["status"])

        # 轮到闸拍清单与 state（读不回来也要说清 —— 见 `_live_facts`）。
        # `status=`：跑着/排队那两档**不等**（A1），而「不读」那句话按 status 分两句（I-1）。
        pauses, values, facts_note = self._live_facts(job, job_id, status=view["status"])
        proj = rounds.project(
            values, view.get("gate"), job_id=job_id, status=view["status"],
            say=str(view.get("say") or ""), delivered=bool(view.get("delivered")),
            pauses=pauses, window=self.window_public(job_id, view["status"], values),
            shots_note=self.shots_note(),
            stage=token)
        note = "\n".join(x for x in (note, events_note, proj["rounds_note"], facts_note) if x)
        return {
            "job_id": job_id,
            "status": view["status"],
            "say": str(view.get("say") or ""),
            "delivered": bool(view.get("delivered")),
            #: 产物那一格（§十五）：`None` = 还没到「写下了 py」那一步（那个位置**不存在**）；
            #: 否则 `{url, filename, path, say}` —— `url` 非空才是真的能下。
            #: ⚠️ 判据与 `/job/{id}/artifact` **同一处**（`_servable_py`）。
            "artifact": self._artifact_cell(job_id, view, values),
            #: 它现在/正要做的那个节点：`stage` 是节点名（页面按它对按钮/文案），
            #: `stage_say` 是它的**人话**（D16：给运营看的字段是人话；与 `/job/{id}`
            #: 那道闸的 `step` / `step_say` 同一个形状）。
            "stage": token,
            "stage_say": where,
            #: ★ **页面现场**（2026-09-21）：跑证据那一趟**跑完现读那一页**拿回来的原始读数
            #: （`selftest._dom_view`）：脚本自己收到了什么 + **页面上有、它却没收到**什么。
            #: 运营最需要看的就是后半块 —— 它直接指出「该点哪个」（今天实测：那一页的 CTA 是
            #: 个 `<a href>`，脚本的选择器里没有 `a` ⇒ `buttons: 0`）。
            #: ⚠️ 里面每个 `None` 都是**「读不到」**（窗格没接 / 那一趟没跑）—— 页面不许画成
            #: 「页面上一个都没有」；`None` 这一格本身 = 这一趟还没有读数。
            "page_view": (values or {}).get("fix_page_view"),
            "note": note,
            "events": shown,                      # 旧 → 新；最多最近 500 条（`Timeline.all` 的默认）
            #: 闸口投影（**只在 `waiting` 时非 null**）。原话照抄 `_view` 算好的那道闸，
            #: 另加 `revisable`（`lint`/`selftest`/`deliver` 三道闸上「打回」才有那个意思）。
            "gate": proj["gate"],
            #: 常开输入的语义（Task 8 定、Task 9 扩展）：`gate`（闸上的回话）/ `steer`
            #: （探路里，下一轮直达）/ `queue`（排队）—— **服务说了算**，页面不猜。
            #: `draft_note` = 最近一条**还没送出去**的话（页面拿它预填，**不自动发**）；
            #: `queued` = 那些话本身（`Job.inbox` 里还没送出去的那些）。
            "input": self._input_now(job, view["status"], token),
            #: 「停」这条路这一版**接上了**（Task 8）：`requested` = 有一个还没兑现的停请求；
            #: `will_stop_at` = **按下去那一刻**服务承诺的落点（页面把它摆在按钮底下）。
            "stop": self._stop_now(job),
            "shots_note": proj["shots_note"],
            "window": proj["window"],
            #: 轮次卡片（Task 6 从 checkpoint 投影）：**旧 → 新**，`rounds[n-1]` 就是第 n 轮。
            "rounds": proj["rounds"],
            "truncated": bool(truncated or proj["truncated"]),
        }

    def _stage_now(self, job: Optional[Job], job_id: str, status: str) -> tuple:
        """`/live` 的 `stage` / `stage_say`：**跑着（含排队）那两档读进程里那一格**。

        为什么（A1/A2）：那两档正在推进（或者前面正有别的 run 在推进同一个 saver），
        读一次 checkpoint 会**排在一次 invoke 后面**；而 `/live` 每 3 秒被点一次 ——
        卡一次整屏就冻一次。剩下三档（在等人 / 到头了 / 跑挂）没有并发的那次 invoke 在写，
        而且那几档的答案本来就只在 checkpoint 里（闸口点名的那一步 / 最后落下的那一步）。
        """
        if job is not None and status in (QUEUED, RUNNING):
            token = str(job.running_step or "")
            return token, (STEP_SAY.get(token, token) if token else UNKNOWN_STEP_SAY)
        return self._where_it_stopped(job_id)

    def _input_now(self, job: Optional[Job], status: str, stage: str) -> dict:
        """`/live.input`：这一行输入**现在是什么语义** + 排着的那几句话（`/say` 排的）。

        `draft_note` = **最近一条还没送出去的话**（页面拿它预填输入框 —— **不自动发**，
        这是 Global Constraints 点名的那个不对称授权：服务可以替人「停」，绝不替人「走」）。
        """
        # ⚠️ 别再套一层 `with job.lock:`（`job.lock` 是**普通 Lock**，不是 RLock ——
        # 套一层就是自己等自己，整个服务停摆；2026-09-19 实测过一次）
        # ⚠️ **上线的那几格是白名单**（回归 3 / R1）—— 条目上还有两格是**内部的**
        # （`promised`：答应过直达没有；`seq`：这个 job 的第几句话），它们**不上线**：
        # 整条 `dict(x)` 拷出去过一次，于是 `/live` 的负载上多了一格（复审量到，
        # 而报告当时写的是「没有进 `/live`」—— 假话）。加一格内部状态时，
        # **这里不写它就不会漏**（`test_the_live_input_entries_go_out_with_exactly_the_documented_keys`
        # 是这道形状的机器守）。
        pending = [{k: x.get(k) for k in LIVE_QUEUED_KEYS}
                   for x in self._still_waiting(job)] if job is not None else []
        return {"mode": input_mode(status, stage, steer=STEER_WIRED,
                                   held=self._steer_held(job)),
                "draft_note": str(pending[-1].get("text") or "") if pending else "",
                "queued": pending}

    @staticmethod
    def _stop_now(job: Optional[Job]) -> dict:
        """`/live.stop`：**按过的那个「停」**（还没兑现的那一次）—— 页面据此禁用按钮、显示落点。

        ⚠️ 报的是**按下去那一刻**那句承诺（`Job.stop_say`），不是现在重算一句：在闸上按的
        「停」是**立刻**兑现的（矩阵第 3 行），而那一刻之后状态还会往前翻（running → done）
        —— 重算就会把「立刻」说成「跑完这一步才停」（那是假话）。
        ⚠️ 没请求过时那几格是**空的**，不是「预览一下按下去会怎样」：矩阵那三句写的是
        **结果**（「停下了」「现在停不下来」），把它们摆在还没按的按钮底下就是编话。
        ⚠️ **三格，没有 `say`**（修复轮 1 / N-2）：响应那一侧那格 `say` 说的是「这一下按到了」
        —— 那是**响应**才有的事实；快照这边 `requested` + `will_stop_at` 已经把话说完了，
        再加一格一字不差的别名就是同一个事实两个名字。
        """
        empty = {"requested": False, "where": "", "will_stop_at": ""}
        if job is None:
            return dict(empty)
        with job.lock:
            if not job.stop_requested:
                return dict(empty)
            return {"requested": True, "where": str(job.stop_where or ""),
                    "will_stop_at": str(job.stop_say or "")}

    def _live_facts(self, job: Optional[Job], job_id: str, *, status: str = "") -> tuple:
        """`/live` 要的两样输入 + 一句人话：闸拍清单、checkpoint 的 values。

        闸拍清单**只从登记表来**（`Job.shot_notes`，一轮一条）—— 不在登记表里的 job
        就没有它的轮次（那是 R12：轮号是 process-local 的，`note` 里明说）。

        ⚠️ 状态读不回来时**在这一层不抛**（`/live` 是 GET，抛出去就是整页 500），也**不静默**：
        原因随响应回到页面上（`LIVE_STATE_UNREADABLE_SAY`）+ 日志里一份 traceback。
        **GET 不许写时间线**（「读不许写」），所以这件事的落点是那句话，不是一条事件。

        ⚠️ **这一层的射程只有三档**（跑着 / 排队 / 跑挂）：那三档 `_view` 不读 state，
        所以读失败到得了这里。**停在闸上 / 到头了**那两档 `_view` 自己先读、先抛 ——
        那一支由 `Service.live` 兜（503 + 一句人话）。别把这条读成「`/live` 永远不抛」。

        `status`（跑着/排队那两档传进来）：**那两档不等**（`_snapshot_soon`）—— 有人在写就
        这一次不读，并**说出来**。⚠️ 那句话**按 status 分两句**（修复轮 1 / I-1）：
        `queued` 的 job 不在跑，说「正在跑」就是**同一屏两格打架**（`status` 那格说的是排队）。
        它**不是**「读不回」（那是另一件事）：一句话盖两件事就是编话。
        """
        soon = status in (QUEUED, RUNNING)
        pauses: list = []
        if job is not None:
            with job.lock:
                pauses = [dict(x) for x in job.shot_notes]
        try:
            snap = self._snapshot_soon(job_id) if soon else self._snapshot(job_id)
        except Exception as exc:                 # noqa: BLE001 —— 读不回来就说读不回来
            traceback.print_exc()
            raw = "%s: %s" % (type(exc).__name__, exc)
            return pauses, {}, LIVE_STATE_UNREADABLE_SAY % raw
        if snap is None:                         # 「不等」那一条：有人在写 ⇒ 这一次不读
            return pauses, {}, (LIVE_BUSY_QUEUED_SAY if status == QUEUED
                                else LIVE_BUSY_RUNNING_SAY)
        return pauses, dict(getattr(snap, "values", None) or {}), ""

    def runs(self) -> dict:
        """`GET /runs` 的正文（设计注 §8.1）：**能挑运行的最小列表**。

        一行 = 一个 job：`{job_id, site, status, say, created_at, rounds, delivered}`。
        `rounds` 是**到过几道闸**（`rounds.count(job.shot_notes, status)`）—— 与 `/live`
        里卡片的张数**同源**（同一份清单、同一个算法）。⚠️ **跑到头了的 job 不算最后那张图**
        （`_capture_pause` 在跑完/跑挂那一次也拍 —— 那一张不是某一轮的闸拍），
        所以「6 道闸」的 job 这里就是 **6**，不是 7。
        ⚠️ 别把它读成探路的模型轮数（`journey.rounds`）：**那是另一个事实**
        （`agent/rounds.py` 的模块 docstring 里那张表）。

        顺序：**最近的在前**（页面左边那一栏据此长）。
        `note`：空列表时那句话说清「这个列表是 process-local 的」—— 不说的话，
        人会把「空」读成「什么都没提交过」（§3.5 同一条纪律）。
        """
        with self._jobs_lock:
            jobs = list(self._jobs.values())
        jobs.sort(key=lambda j: j.created_at, reverse=True)
        rows = []
        for job in jobs:
            view = self._view(job.job_id)         # 登记表里的 job 读得回来（读不回来是 500，不是少一行）
            rows.append({
                "job_id": job.job_id,
                "site": (job.brief or {}).get("site"),
                "status": view["status"],
                "say": str(view.get("say") or ""),
                "created_at": job.created_at,
                #: 「到过几道闸」—— 轮数**只有这一个算法**（`rounds.count`）；
                #: 到头了的那两档要把「最后那张图」去掉（它不是一轮）
                "rounds": rounds.count(job.shot_notes, view["status"]),
                "delivered": bool(view.get("delivered")),
            })
        return {"note": "" if rows else NO_RUNS_SAY, "runs": rows}

    # ── ① 从 FMR 读失败（Task 13）────────────────────────────────────
    @staticmethod
    def _unmeasured_to_http(exc: "fmr.FmrUnmeasured") -> HTTPException:
        """「量不到」→ **非 2xx + 一句人话**。

        ⚠️ 这一处的判断是这一节的**要害**：`FmrUnmeasured` 一律变成**错误响应**，
        **永远不变**成一个 `200 {"failures": []}`。后者在屏幕上与「这个站很健康」
        长得一模一样 —— 那就是「把量不出来读成量出来了」。
        `FmrNoToken`（这个部署干不了）单列 503；其余（连不上 / 非 JSON / 后端回码）都是 502。
        """
        code = (FAILURE_STATUS_NO_TOKEN if isinstance(exc, fmr.FmrNoToken)
                else FAILURE_STATUS_UNMEASURED)
        return HTTPException(status_code=code, detail=exc.say)

    def failures(self, site: str, since: Any = None, limit: Any = None) -> dict:
        """`GET /failures` 的正文（Task 13）：**这个站最近失败的那几趟**，一行一句人话。

        ⚠️ 端出去的**不是** FMR 那份 JSON：每一行只留 `task_id`（机器要用它去取证据）
        与 `say`（人话）。码（`site_specific` / `US` / `failed`）在 `agent/fmr.py`
        那几张表里就已经换成人话了 —— 这一层**不再转发**任何原样的格子。

        ⚠️ 三种「量不到」在这儿的形状：**非 2xx**（见 `_unmeasured_to_http`）。
        **只有真量过、真没有** 才有 `200` + `failures: []`。
        """
        key = str(site or "").strip()
        if not key:
            # 免费的那道闸（与 `_intake_problems` 同一个做法）：缺什么**在门口**说，
            # 而不是先发一个注定要失败的请求、再把后端的 400 翻译一遍。
            raise HTTPException(
                status_code=400,
                detail="还没说**是哪个站**：这一栏要的是 FMR 那个站的名字"
                       "（形如 `主机名/路径`，比如 `www.gowizard.com/auto-warranty/`）。"
                       "缺它的这一下**一个请求都没发出去**。")
        try:
            since_txt = fmr.since_text(since)
        except fmr.FmrUnmeasured as exc:
            # 免费的那道闸（与下面「缺 site」同一档）：读不出来的时间窗**在门口**就响 ——
            # 悄悄改用默认窗口的坏处是「你以为查的是昨天，看到的是今天那份」。
            raise HTTPException(status_code=400, detail=exc.say)
        try:
            rows = self._fmr.fetch_failures(key, since=since, limit=limit)
        except fmr.FmrUnmeasured as exc:
            raise self._unmeasured_to_http(exc)
        n = fmr.DEFAULT_LIMIT if limit in (None, "") else int(limit)
        return {
            "site": key,
            "since": since_txt,
            "limit": n,
            "say": _failures_say(key, since_txt, rows, n),
            "failures": [{"task_id": str(r.get("task_id") or ""), "say": fmr.failure_say(r)}
                         for r in rows],
        }

    def failure_evidence(self, task_id: str, *, site: str,
                         since: Any = None) -> dict:
        """`GET /failures/{单号}/evidence` 的正文（Task 13）：**一段人话** + 该填的那串网址。

        ⚠️ 都**从后端读**（`fmr.FmrClient.evidence_for`）：调用方（页面）一个字都不许塞
        —— 证据里的每一个字都得是后端说的。页面拿这几样去填「开一趟」那张表（Task 12 那张），
        **它自己不拼** evidence。

        ★ 第 ① 件事（2026-09-21）：多端一格 `site` —— **后端自己存的那个站键**
        （失败记录行里那一格），外加 `fill_site`（服务说这一格用不用，页面不自己推）。
        它治的是：服务原先拿「站点网址」那一格（人填的入口网址）去问 `formScript`，
        而那个读口要的是「**存的 site 必须是请求值的 host+path 前缀**」——
        入口网址比存的键**浅**时就回 404，明明有这个站。
        ⚠️ 它是**另一件事**，不是 `url` 的别名：`url` 是「这一趟真从哪儿进去的」。
        """
        key = str(site or "").strip()
        if not key:
            raise HTTPException(
                status_code=400,
                detail="还没说**是哪个站**：那一条证据要从这个站的失败列表里找出来。"
                       "缺它的这一下**一个请求都没发出去**。")
        try:
            got = self._fmr.evidence_for(task_id, site=key, since=since)
        except fmr.FmrUnmeasured as exc:
            raise self._unmeasured_to_http(exc)
        except KeyError:                     # 桩/换实现时缺格子 —— 一样**不许**静默
            raise HTTPException(
                status_code=FAILURE_STATUS_UNMEASURED,
                detail=("读不了这一段证据：读回来的东西里少了几格（这一层要的是"
                        "`task_id`/`row_say`/`url`/`evidence`）。%s。" % fmr.UNMEASURED_SAY))
        # ⚠️ **这一层做投影**（不是把客户端那份端出去）：留下的四格全是给页面用的 ——
        #    人话、单号、该填的网址、那段证据。`row` / `steps` 里的**码**
        #    （`site_specific` / `US` / `failed`）**不进这一份正文**（与 `/failures` 同一条纪律）。
        return {
            "task_id": str(got.get("task_id") or ""),
            "row_say": str(got.get("row_say") or ""),
            "url": str(got.get("url") or ""),
            "evidence": str(got.get("evidence") or ""),
            #: 页面照着这一格决定「站点网址」那一格填不填：**服务说填什么**，页面不自己推。
            "fill_url": bool(str(got.get("url") or "").strip()),
            #: ★ 第 ① 件事：后端自己那个站键（行里那一格）。页面把它跟着那一趟发回去，
            #: `_stage_fix_source` 拿它去读脚本 —— 见那一格自己的注释。
            #: ⚠️ 行里没有就是**空串 + False**，**不拿问的那个键顶替**（那是另一件事：
            #: 顶替出来的东西看起来一模一样，可它不是后端说的那一格）。
            "site": str(got.get("site") or ""),
            "fill_site": bool(str(got.get("site") or "").strip()),
        }

    # ── ③ 榜单（哪个站坏了）+ ④ 原因（为什么）（Task 4）──────────────
    def rank(self, date: Any = None, limit: Any = None) -> dict:
        """`GET /rank` 的正文（Task 4 ③）：**这一天哪些站在失败**，一行一句人话。

        ⚠️ 端出去的**不是** FMR 那份 JSON：每一行只留
        `site`（页面拿它去查失败单 —— 那是 `formLog` 认的那个键）、
        `say`（人话）、以及 `fail_count`（**数字**）。`config_id` / `config_status` /
        `has_script` 那些码在 `agent/fmr.py` 的表里就换成人话了 —— 与 `/failures` 同一条纪律。

        ★ `fail_count` 不是装饰：页面拿它跟「按这个键查回来几条」**对账**
        （`agent/console.html` 的 `rankWant`）。⚠️ 它**漏过一次**：最初这里只留 `site`/`say`，
        于是页面那个 `at(row, "fail", null)` **恒为 null** ⇒ 那条对账**永不触发**
        （Task 4 复审 F2：0 条用例、变异体全绿、真数据 8/8 走不到）。
        两个数**不一样是常态**（复审量：8 个真键里多数 `n > want`）——
        榜单按 **站点键** 数、`formLog` 按 **配置** 捞（`QuestDiagnosisController.php`
        的 `formLogRank` 用 `normalize($key)` 分桶、`formLog` 用 `resolveConfig` 比 `config_id`），
        一份配置底下可以有好几个键 ⇒ **这里必须给数，页面才说得清那两个数为什么不同**。

        ⚠️ 那句 `say` 里带着**三个数**（一共失败多少次 / 其中多少次归不到站 / 摆出来几个站）——
        它们**对不上是正常的**（`limit` 只截断 `rank`），而 `say` 会把差额说出来。
        页面**照抄**那一句，不自己拿数字算一遍（两处各算一次迟早漂）。

        ⚠️ 三种「量不到」在这儿的形状与 `/failures` **一模一样**：**非 2xx**。
        """
        try:
            data = self._fmr.fetch_rank(date=date, limit=limit)
        except fmr.FmrUnmeasured as exc:
            raise self._unmeasured_to_http(exc)
        n = fmr.DEFAULT_RANK_LIMIT if limit in (None, "") else int(limit)
        rows = [r for r in (data.get("rank") or []) if isinstance(r, dict)]
        return {
            "date": str(data.get("date") or ""),
            "limit": n,
            "say": fmr.rank_say(data, n),
            "rank": [{
                "site": str(r.get("site") or ""),
                "say": fmr.rank_row_say(r),
                #: ★ 给页面**对账**用的那个数（见 docstring）：后端那一格是 `fail`，
                #: 读不出来就给 `None` —— **不给 0**（0 是一个合法读数，
                #: 拿它顶替「没给」就是把「对不了账」写成「对上了」）。
                "fail_count": fmr.int_or_none(r.get("fail")),
            } for r in rows],
        }

    def diag(self, task_id: Any) -> dict:
        """`GET /diag/{单号}` 的正文（Task 4 ④）：**这一单为什么失败**。

        ★ 走**单号**（brief §2 R1）：榜单那个站点键不保证干净，拿它当 join 键会
        **查到 0 行而且不报错**；单号是精确的。

        ⚠️ **`note` 那一格是这一屏的一半**：单号在 `failDiag` 里**还没有原因行**是很常见的
        （新功能 / 老单 / 那台机器没发上来 —— 三种在数据上长得一样，分不出）。
        那**不是**错误（`200` + 空数组 = 量到了、没有），但**也不许留白**：
        `note` 由 `fmr.NO_DIAG_SAY` 给（与 `/runs` 空列表放 `note` 同一个做法）。

        ⚠️ `lines` 是**原样**的（那几行日志就是这条链要给人看的东西）——
        这一层不加工它、不截断它（后端那侧已经截到 64KB 了）；页面负责转义后摆出来。
        """
        key = str(task_id or "").strip()
        if not key:
            # 免费的那道闸（与 `/failures` 缺 site、`/diag` 缺单号同一档）。
            raise HTTPException(
                status_code=400,
                detail="还没说**是哪个单**：这一栏要的是 FMR 那边的**单号**"
                       "（形如 `26034602`）。缺它的这一下**一个请求都没发出去**。")
        try:
            rows = self._fmr.fetch_diag(key)
        except fmr.FmrUnmeasured as exc:
            raise self._unmeasured_to_http(exc)
        return {
            "task_id": key,
            "say": _diag_say(key, rows),
            #: 页面拿 `say` 当抬头（人话）、`lines` 当正文（原样摆）。
            #: ★ `shot` = 后端那格 `fail_img`（失败截图的 OSS 地址）—— **面板上那张图就是它**。
            #: ⚠️ 后端没给 ⇒ **空串**（页面于是**什么都不摆**）：不许编一个地址，
            #: 也不许摆一个空框（空框会被读成「这一趟没截图」，而真相是「后端没给这一格」）。
            #: 名字叫 `shot` 不叫 `fail_img`：页面画的是**图**，不是一份后端的字段转储
            #:（`_no_code` 那一族的规矩 —— 后端的字段名不许上屏）。
            "diag": [{"say": fmr.diag_head_say(r), "lines": str(r.get("lines") or ""),
                      "shot": str(r.get("fail_img") or "")}
                     for r in rows],
            #: 空 = 没有话要说；非空 = 这一单还没有原因行（**不是**错误，但必须说出来）。
            "note": "" if rows else fmr.NO_DIAG_SAY,
        }

    def configcheck(self, site: Any) -> dict:
        """`GET /configcheck?site=<站点键>` 的正文（合规闸，用户 2026-09-21 定）。

        ```
        读那份配置（B1 的 form_config）
              ↓ 逐格对照「执行器认不认」（`agent/configcheck`，判据**现量**）
        端给页面：逐条人话 + 量的是哪一版执行器
        ```

        ## ★ 这一条路上最贵的那一格

        **读不回来 ⇒ 非 2xx**。一个 `200 {"errors": []}` 在屏幕上与「这份配置没问题」
        **一模一样**，而它真正的意思是「我根本没读到」—— 与「无效 key 被标成
        没有失败 ✓」是同一个形状的下一站。

        ⚠️ 反过来：**「不合规」是 `200`**（读回来了、也逐格看过了）。
        把它做成非 2xx 的话，屏幕上与「读不回来」分不开，而两件事的处置完全不同
        （一个去改配置，一个去查后端/网络）。

        ⚠️ 判据**不在这一层**：`configcheck.load_rules()` 每次**从执行器源码现量**
        （那个目录别人在改）。这一层**不许**自己抄一份动作表。
        """
        key = str(site or "").strip()
        if not key:
            # ★ 400（与 `failures()` / `jsondiff()` 门口同一道免费的闸）：没给站点键是
            # **调用方自己的毛病**，一个请求都没发出去 —— 写成 502 的话运维会去查后端。
            raise HTTPException(
                status_code=400,
                detail="看不了这份配置合不合规：没说是**哪个站** —— 这是免费的检查"
                       "（一个请求都没发出去）。")
        try:
            config = self._fmr.form_config(key)
        except fmr.FmrUnmeasured as exc:
            raise self._unmeasured_to_http(exc)
        rules = configcheck.load_rules()
        problems = configcheck.check_config(config, rules)
        errors = [p for p in problems if p["level"] == "error"]
        notes = [p for p in problems if p["level"] == "note"]
        return {
            "site": key,
            "say": _configcheck_say(errors, notes),
            "errors": errors,
            "notes": notes,
            #: ★ 判据是现量的 ⇒ 得说清**量的是哪一版**（那个执行器别人在改）。
            #: 少了这一格，闸就会在无声中拿旧规矩卡新执行器。
            "rules": {"path": rules["path"], "sha256": rules["sha256"],
                      "mtime": rules["mtime"]},
        }

    def jsondiff(self, site: Any) -> dict:
        """`GET /jsondiff?site=<站点键>` 的正文（Task B2/B3）：**这份配置差在哪一格**。

        ```
        读那份配置（B1 的 form_config）
              ↓ 复跑（B2 的 rerun）—— 真页面 + 生产那个执行器，★ 一次模型都不调
              ↓ 逐格对照（B2 的 diff_config，纯函数）
        端给页面：配置 + 复跑自己的结论 + diff
        ```
        ⚠️ **这一版没有写回**（控制者 2026-09-21 按下）：写接口的语义没验过
        （「按 site 更新已有那条」还是「每次都插一条新的」），猜错会在生产库里
        堆重复配置。所以这里**只读不写**。

        ★★ **四种「空」必须分得开**（见 `tests/test_service_jsondiff.py`）：

        | 情形 | 给什么 |
        |---|---|
        | 配置读回来了、**还没复跑** | `200` + `diff: None` + 一句说清是**还没跑** |
        | 复跑了、哪一格都对得上 | `200` + 空的两条清单 + 另一句 |
        | 复跑了、有对不上的 | `200` + 那两条清单 |
        | **配置读不回来** / **复跑没量着** | **非 2xx**（走 `_unmeasured_to_http`） |

        ⚠️ 头两行**在数据上都是「没有 changes」** —— 分开它们的**只有那句 `say`**。
        把「还没跑」说成「没有差异」，就是在告诉运营「这份配置是好的」，
        而它**只是还没被跑过**。这是本仓最贵的那个形状（无效 key 被显示成「没有失败 ✓」）。

        ⚠️ 复跑**没量着**（窗口没了 / 执行器 import 失败 / 超时）走**非 2xx**，
        不许退化回「还没复跑」那一格：两者在屏幕上都是「没东西可看」，
        而处置完全不同（一个去开窗口，一个去点按钮）。
        """
        key = str(site or "").strip()
        if not key:
            # ★ **400，不是 502**：没给站点键是**调用方自己的毛病**（一个请求都没发出去），
            # 与「量不到」是两件事。写成 502 的话运维会去查后端与网络，
            # 而他真正该做的是**把那一格填上**。与 `failures()` 门口那道闸同一个码。
            raise HTTPException(
                status_code=400,
                detail="看不了这份 JSON 配置：没说是**哪个站** —— 这是免费的检查"
                       "（一个请求都没发出去）。")

        try:
            config = self._fmr.form_config(key)
        except fmr.FmrUnmeasured as exc:
            # 读不回来（这个站没有配置 / 后端连不上）⇒ **非 2xx**。
            # ⚠️ 不许退化成「没东西可看」：那会被读成「这个站的配置没问题」。
            raise self._unmeasured_to_http(exc)
        base = {"site": key, "config": config,
                "can_rerun": bool(self._json_ws_url)}

        if not self._json_ws_url:
            # ★ 这一格**不是错误**（没配窗口照样能看配置），但**必须说清是「还没跑」**。
            return dict(base, diff=None, summary=None,
                        say="这份配置读回来了，**还没复跑** —— 这个部署没配"
                            "复跑用的浏览器地址（`%s`），所以「差在哪一格」还是未知。"
                            "⚠️ 这一格**不是**「配置是好的」那个结论：它只是**还没跑**。"
                            % JSON_WS_URL_ENV)

        try:
            #: ⚠️ **必须先把那一页打开**（2026-09-21 实测）：不给 `entry_url`，复跑就是在
            #: **浏览器自己的控制台页**上跑（实测那一趟：窗口停在
            #: `https://console.bitbrowser.net/?id=…`，执行器记下的全是 `deferred unfilled`、
            #: 页面事实也量不到）—— 与 py 那条路今天修的是**同一件事**
            #: （`selftest._navigate`：生产起脚本之前先 `cdp navi`）。
            got = self._json_rerun(config, ws_url=self._json_ws_url,
                                   entry_url=_json_entry_url(config))
        except jsondiag.RerunUnmeasured as exc:
            # 「没量着」—— 与「还没跑」是两件事，所以**非 2xx**。
            # ⚠️ 它**不是** `fmr.FmrUnmeasured`（没有 `.say`），所以不能借
            # `_unmeasured_to_http` —— 借了会 AttributeError、最后变成 500，
            # 而那会把「复跑挂了」显示成「服务坏了」。
            raise HTTPException(status_code=FAILURE_STATUS_UNMEASURED, detail=str(exc))

        came_back = jsondiag.diff_config(config, got.get("facts") or {})
        summary = got.get("summary") or {}
        return dict(
            base, summary=summary,
            diff={"changes": came_back["changes"],
                  "unresolved": came_back["unresolved"],
                  "suggested": came_back["suggested"]},
            say=_jsondiff_say(came_back, summary),
        )

    def jsonwrite_prepare(self, site: Any, proposed: Any, operator: Any) -> dict:
        """只做预检并发一次性票据；这一阶段绝不调用写口。"""
        key = str(site or "").strip()
        who = str(operator or "").strip()
        if not key or not who:
            raise HTTPException(status_code=400,
                                detail="写回前必须填写站点键和 operator（谁确认的）。")
        if not isinstance(proposed, dict) or not proposed:
            raise HTTPException(status_code=400, detail="待写内容必须是一份非空 JSON 对象。")
        cfg_site = str(proposed.get("site") or "").strip()
        if cfg_site and cfg_site != key:
            raise HTTPException(status_code=400,
                                detail="配置里的 site 与要写回的站点键不一致。")
        try:
            original = self._fmr.form_config(key)
        except fmr.FmrUnmeasured as exc:
            # 当前只允许更新已存在记录；未实测的 create/upsert 不开放。
            raise self._unmeasured_to_http(exc)
        rules = configcheck.load_rules()
        problems = configcheck.check_config(proposed, rules)
        errors = [p for p in problems if p.get("level") == "error"]
        if errors:
            raise HTTPException(status_code=409, detail={
                "say": "配置不合规，写口没有被调用。", "errors": errors})
        if not self._json_ws_url:
            raise HTTPException(status_code=409,
                                detail="没有复跑浏览器地址，不能证明这份配置能跑，未写回。")
        try:
            got = self._json_rerun(proposed, ws_url=self._json_ws_url,
                                   entry_url=_json_entry_url(proposed))
        except jsondiag.RerunUnmeasured as exc:
            raise HTTPException(status_code=FAILURE_STATUS_UNMEASURED, detail=str(exc))
        summary = got.get("summary") or {}
        if not jsonwrite.rerun_passed(summary):
            raise HTTPException(status_code=409, detail={
                "say": "复跑没有明确判成 success，写口没有被调用。", "summary": summary})
        item = self._json_tickets.issue(
            site=key, original=original, proposed=proposed, summary=summary,
            rules={"path": rules["path"], "sha256": rules["sha256"],
                   "mtime": rules["mtime"], "operator": who})
        return {
            "ready": True, "ticket": item.token, "site": key,
            "original_sha256": item.original_sha256,
            "proposed_sha256": item.proposed_sha256,
            "expires_at": item.expires_at.isoformat(), "summary": summary,
            "say": "预检通过：执行器合规检查与真页面复跑都通过。再次确认才会写回。",
        }

    def jsonwrite_commit(self, token: Any) -> dict:
        """消费票据，写前防并发覆盖，写后回读；不一致则立刻回滚并复核。"""
        item, reason = self._json_tickets.take(str(token or ""))
        if item is None:
            word = "已过期" if reason == "expired" else "不存在或已经用过"
            raise HTTPException(status_code=409, detail="写回确认票据%s，请重新预检。" % word)
        try:
            current = self._fmr.form_config(item.site)
        except fmr.FmrUnmeasured as exc:
            raise self._unmeasured_to_http(exc)
        if jsonwrite.fingerprint(current) != item.original_sha256:
            raise HTTPException(status_code=409,
                                detail="后端配置在预检后被别人改过；未写回，请重新读取。")
        backup_id = self._json_backups.save(
            site=item.site, original=current, replacement=item.proposed)
        operator = str(item.rules.get("operator") or "")
        result = self._fmr.update_form_config(item.site, item.proposed, operator=operator)
        try:
            after = self._fmr.form_config(item.site)
        except fmr.FmrUnmeasured as exc:
            raise HTTPException(status_code=502, detail={
                "say": result.say + " 写后回读失败，不能宣称完成；备份已保留。",
                "backup_id": backup_id, "cause": exc.say})
        after_sha = jsonwrite.fingerprint(after)
        if after_sha == item.proposed_sha256:
            return {"ok": True, "site": item.site, "backup_id": backup_id,
                    "sha256": item.proposed_sha256,
                    "say": "写回并回读核对完成；原配置已保存，可用备份编号回滚。"}
        if after_sha == item.original_sha256 and not result.ok:
            # 明确拒绝/鉴权失败，或回执未知但回读证明仍是原件：没有需要回滚的变化。
            raise HTTPException(status_code=409, detail={
                "say": result.say + " 回读确认后端仍是写前原配置。",
                "backup_id": backup_id, "write": result.as_dict()})
        # 后端说成功但回读不一致，或回执未知且实际不是目标值：恢复原件。
        rollback = self._fmr.update_form_config(item.site, item.original,
                                                operator=operator + "（自动回滚）")
        try:
            restored = self._fmr.form_config(item.site)
            restored_ok = jsonwrite.fingerprint(restored) == item.original_sha256
        except fmr.FmrUnmeasured:
            restored_ok = False
        raise HTTPException(status_code=502, detail={
            "say": "写后回读与目标不一致；已尝试自动回滚。",
            "backup_id": backup_id, "write": result.as_dict(),
            "rollback": rollback.as_dict(), "restored": restored_ok})

    def jsonwrite_rollback(self, backup_id: Any, operator: Any) -> dict:
        who = str(operator or "").strip()
        if not who:
            raise HTTPException(status_code=400, detail="回滚必须填写 operator（谁确认的）。")
        try:
            saved = self._json_backups.load(str(backup_id or ""))
        except (OSError, ValueError, json.JSONDecodeError) as exc:
            raise HTTPException(status_code=404, detail="读不到这份备份：%s" % exc)
        site = str(saved.get("site") or "")
        try:
            current = self._fmr.form_config(site)
        except fmr.FmrUnmeasured as exc:
            raise self._unmeasured_to_http(exc)
        if jsonwrite.fingerprint(current) != saved.get("replacement_sha256"):
            raise HTTPException(status_code=409,
                                detail="当前配置已不是这份备份对应的替换版本；拒绝覆盖更新。")
        result = self._fmr.update_form_config(site, saved["original"],
                                              operator=who + "（人工回滚）")
        try:
            after = self._fmr.form_config(site)
        except fmr.FmrUnmeasured as exc:
            raise self._unmeasured_to_http(exc)
        ok = result.ok and jsonwrite.fingerprint(after) == saved.get("original_sha256")
        if not ok:
            raise HTTPException(status_code=502, detail={
                "say": "回滚没有通过回读核对。", "write": result.as_dict()})
        return {"ok": True, "site": site, "sha256": saved["original_sha256"],
                "say": "已回滚到写前原配置，并通过回读核对。"}

    # ── py 上传（2026-09-22）：把**这一趟落盘的那份脚本**传到后台 ─────────────

    def _what_to_upload(self, job_id: str) -> dict:
        """这一趟「要传什么」：那份源码 + 后端那个键。**免费**（只看本地状态）。

        ⚠️ 走 `_artifact_state` —— 仓里**唯一**判「这一趟的产物」的那一处，而且它给的正是
        我们要的东西：**这一趟自己写下的那串字节**（`state["src"]`），不是盘上现在那份
        （同站点的后一趟把文件盖掉了，也不影响这一趟该传什么）。
        ⚠️ 因此这里**不许**从 `view`/`result` 上读 `delivered`：那是 `inbox` 判据的**同名不同物**，
        `tests/test_service_input.py::test_the_inbox_criteria_live_in_exactly_one_place` 当场逮过我一次。
        """
        view = self._view(job_id)
        soon = str(view.get("status") or "") in (QUEUED, RUNNING)
        snap = None if soon else self._snapshot(job_id)
        values = dict(getattr(snap, "values", None) or {}) if snap is not None else {}
        art = self._artifact_state(view, values)
        blob = art.get("bytes")
        if not blob:
            raise HTTPException(status_code=409,
                                detail=art.get("say") or "这一趟还没有产物。")
        try:
            source = bytes(blob).decode("utf-8")
        except UnicodeDecodeError as exc:
            raise HTTPException(status_code=400,
                                detail="产物不是 UTF-8 的文本（%s）—— 传上去就是一份坏脚本，"
                                       "没上传。" % exc)
        path = pathlib.Path(str(art.get("path") or ""))
        if not source.strip():
            raise HTTPException(status_code=400,
                                detail="产物是**空文件** —— 传上去等于把那个站弄死。没上传。")
        try:
            ast.parse(source)
        except SyntaxError as exc:
            raise HTTPException(
                status_code=400,
                detail="产物过不了 `ast.parse`（第 %s 行：%s）—— 这一版落盘，生产里那个站"
                       "就是跑 0 次。没上传。" % (exc.lineno, exc.msg))
        job = self._jobs.get(str(job_id))
        brief = dict(getattr(job, "brief", {}) or {})
        key = _backend_key(brief.get("url"), brief.get("fix_site"), brief.get("fix_site_url"))
        if not key:
            raise HTTPException(status_code=400,
                                detail="这一趟**没说是哪个站**（brief 里没有 url/fix_site）"
                                       "—— 不知道往哪儿传。没上传。")
        return {"path": str(path), "source": source, "key": key}

    def _backend_script(self, key: str) -> tuple:
        """`(后端那份源码, 这个键后端不认识吗)` —— 404 当「**还没有这一份**」，别的错照样抛。

        ★ 2026-09-22 真事（用户：「**能下载 py 了但是好像不能直接上传**」）：新站第一次传时，
        那个读口回 404（后端没有这一行）—— 原来预检/确认都会把它当失败 ⇒ 面板上就是
        「不能上传」。⇒ 404 = **「还没有这一份」**：现值按**空**算，票照发，写那一下
        走 `created: true` 那条路**新建**（实测：带 `status: 1` 写一个不存在的键，
        后端建了一行、回读 sha 逐字节一致 ✓）。
        ⚠️ 404 也可能是「那一行两列都是空的」—— 两种在后端长得一样，这一层**不分**
        （对「要不要传」这件事，两种的处置本来就同一个：没有可保护的东西 ⇒ 直接写）。
        ⚠️ **空串也是一种现值**：预检与确认各读一次，两次都「不认识」⇒ 前后一致 ⇒
        「写前防覆盖」那道闸照旧成立 ✓（它比的是两次读的 sha，不是「有没有那一行」）。
        """
        try:
            return str(self._fmr.form_script(key, allow_disabled=True).get("source") or ""), False
        except fmr.FmrRefused as exc:
            if int(getattr(exc, "status", 0) or 0) == 404:
                return "", True
            raise self._unmeasured_to_http(exc)
        except fmr.FmrUnmeasured as exc:
            raise self._unmeasured_to_http(exc)

    def py_upload_prepare(self, job_id: str, operator: Any) -> dict:
        """预检：把「要传什么 / 后端现在是什么」摆出来，发一张一次性票据。**这一阶段绝不写。**"""
        what = self._what_to_upload(job_id)
        who = str(operator or "").strip()
        if not who:
            raise HTTPException(
                status_code=400,
                detail="没说**谁确认的**（`operator`）—— 那是后端实测的必填审计字段，"
                       "一个请求都不会发出去。")
        if not self._fmr.write_token:
            raise HTTPException(
                status_code=503,
                detail="**一个字都没写**：这个部署**没配写用的 token**（`%s`，没配就退回 `%s`）"
                       "—— 请求一个都没发出去。" % (fmr.WRITE_TOKEN_ENV, fmr.TOKEN_ENV))
        original, fresh = self._backend_script(what["key"])
        same = pywrite.sha256_text(original) == pywrite.sha256_text(what["source"])
        if same:
            raise HTTPException(
                status_code=409,
                detail="后端那份**已经是**这一份了（指纹一样：`%s…`）—— 不用传。"
                       % pywrite.sha256_text(original)[:16])
        item = self._py_tickets.issue(key=what["key"], path=what["path"],
                                      source=what["source"], original=original, operator=who)
        n_bytes = len(item.source.encode("utf-8"))
        #: ⚠️ 两句**必须分开**：新键说成「后端现在那份 sha …」是假话（它压根没有那一行）；
        #: 反过来，已有的那一份说成「新建」也是假话（那是**换掉**它）。
        if fresh:
            said = ("预检过了：本地那份 **%d 字节 / sha `%s`**；后端**还不认识这个键**"
                    "（或那一行是空的）—— 确认之后是**新建/写满**一份（实测过：带 `status: 1` "
                    "写一个新键，后端建了一行、回读 sha 逐字节一致 ✓）。**再确认一次才会上传**；"
                    "⚠️ 传上去它会真跑（`status: 1`）。" % (n_bytes, item.source_sha256[:16]))
        else:
            said = ("预检过了：本地那份 **%d 字节 / sha `%s`**；后端现在那份 sha `%s`。"
                    "**再确认一次才会上传**（上传会换掉后台那份，生产按接口下载就变成新这一份）。"
                    "⚠️ 这一下**也带着启用**（`status: 1`）—— 传上去它就会真跑；"
                    "⚠️ 那一行若是**被人停用**的，会被**重新启用**。后端回执不回显这一格，"
                    "要确认就再读一次（正常读、不加 debug）✓。"
                    % (n_bytes, item.source_sha256[:16], item.original_sha256[:16]))
        return {"ticket": item.ticket, "site": item.key, "path": item.path,
                "bytes": n_bytes, "local_sha256": item.source_sha256,
                "backend_sha256": item.original_sha256, "say": said}

    def py_upload_commit(self, job_id: str, ticket: Any) -> dict:
        """消费票据 → 写前防覆盖 → 上传 → **回读校验**；不一致就传回原来那份。"""
        item, reason = self._py_tickets.take(str(ticket or ""))
        if item is None:
            word = "已过期" if reason == "expired" else "不存在或已经用过"
            raise HTTPException(status_code=409, detail="上传确认票据%s，请重新预检。" % word)
        current, _missing = self._backend_script(item.key)
        if pywrite.sha256_text(current) != item.original_sha256:
            raise HTTPException(
                status_code=409,
                detail="**后端那份在预检之后被改过过**（现在 sha `%s`，预检时 `%s`）—— "
                       "没上传，请重新预检。" % (pywrite.sha256_text(current)[:16],
                                                item.original_sha256[:16]))
        backup_id = self._py_backups.save(key=item.key, original=item.original,
                                          replacement_sha256=item.source_sha256)
        result = self._fmr.update_form_script(item.key, item.source, operator=item.operator)
        if not result.ok:
            raise HTTPException(status_code=502, detail={"say": result.say,
                                                         "backup_id": backup_id,
                                                         "verdict": result.verdict})
        try:
            after, _missing = self._backend_script(item.key)
        except fmr.FmrUnmeasured as exc:
            raise HTTPException(status_code=502, detail={
                "say": result.say + " 但**写后回读失败** —— 不能宣称传成功了。"
                       "备案：`%s`。" % backup_id,
                "backup_id": backup_id, "cause": exc.say})
        if pywrite.sha256_text(after) != item.source_sha256:
            back = self._fmr.update_form_script(item.key, item.original,
                                               operator=item.operator + "（自动回滚）")
            try:
                restored = str(self._fmr.form_script(
                    item.key, allow_disabled=True).get("source") or "")
            except fmr.FmrUnmeasured:
                restored = ""
            raise HTTPException(status_code=502, detail={
                "say": "**写后回读对不上**（后端那份的 sha 不是我们要传的那个）—— 已经把它"
                       "**传回原来那份**（%s）。备案：`%s`。"
                       % ("回读核对通过 ✓" if pywrite.sha256_text(restored) == item.original_sha256
                          else "⚠️ 回滚也没核对上，**去后端看一眼**", backup_id),
                "backup_id": backup_id, "rollback": back.as_dict()})
        return {"ok": True, "site": item.key, "sha256": item.source_sha256,
                "bytes": len(item.source.encode("utf-8")), "backup_id": backup_id,
                "say": ("**上传好了，而且回读核对过**：后端那份现在 sha `%s`，与本地那份"
                        "逐字节一致。写前那份备份在 `%s`（要回滚就按「回滚」。）"
                        % (item.source_sha256[:16], backup_id))}

    def py_upload_rollback(self, job_id: str, backup_id: Any, operator: Any) -> dict:
        """人工回滚：把**上传前那份**传回去（先核对「后端现在是不是我们传上去的那一份」）。"""
        who = str(operator or "").strip()
        if not who:
            raise HTTPException(status_code=400,
                                detail="没说**谁确认的**（`operator`）—— 一个请求都不会发出去。")
        try:
            original, saved = self._py_backups.load(str(backup_id or ""))
        except (OSError, ValueError) as exc:
            raise HTTPException(status_code=400, detail="这份备份读不出来：%s" % exc)
        key = str(saved.get("site") or "")
        try:
            current = str(self._fmr.form_script(key, allow_disabled=True).get("source") or "")
        except fmr.FmrUnmeasured as exc:
            raise self._unmeasured_to_http(exc)
        if pywrite.sha256_text(current) != str(saved.get("replacement_sha256") or ""):
            raise HTTPException(
                status_code=409,
                detail="后端那份**已经不是**这份备份对应的替换版本了（别人又改过？）"
                       "—— 拒绝覆盖，没回滚。")
        result = self._fmr.update_form_script(key, original, operator=who + "（人工回滚）")
        try:
            after = str(self._fmr.form_script(key, allow_disabled=True).get("source") or "")
        except fmr.FmrUnmeasured as exc:
            raise HTTPException(status_code=502, detail={
                "say": result.say + " 但**回滚后回读失败** —— 不能宣称回滚成功，"
                       "去后端看一眼那份现在是什么。",
                "cause": exc.say})
        if not (result.ok and pywrite.sha256_text(after) == str(saved.get("original_sha256") or "")):
            raise HTTPException(status_code=502,
                                detail={"say": "回滚没有通过回读核对。", "write": result.as_dict()})
        return {"ok": True, "site": key, "sha256": saved.get("original_sha256"),
                "say": "已回滚到上传前那份，并通过回读核对。"}

    @staticmethod
    def _truncated_say(timeline, shown: int) -> str:
        """`truncated` 为真时**说清**丢了什么/回了多少（设计注 §8.2：「并说明」）。"""
        parts = []
        dropped = timeline.dropped()
        if dropped:
            parts.append("最早那 %d 条已经丢掉了（时间线上限 %d 条）。"
                         % (dropped, events.MAX_EVENTS))
        rest = len(timeline) - shown
        if rest > 0:
            parts.append("这一次只回最近 %d 条（前面还有 %d 条没回）。" % (shown, rest))
        return "时间线太长：" + "".join(parts)

    # ── 输入检查（**免费的那些**：在烧掉一次探路之前）────────────────────
    def _intake_problems(self, body: RunRequest) -> list:
        problems = []
        if not (body.url or "").strip():
            problems.append("还没说**是哪个站点**：`url`。")
        if not (body.goal or body.evidence or "").strip():
            problems.append("还没说**这次要做什么**：`goal`（或者 fix 模式下的失败证据 `evidence`）。")
        if (not (body.success_text or "").strip()
                and str(getattr(body, "mode", "") or "") != MODE_FIX):
            problems.append("还没说**什么算成功**：`success_text` —— 走通之后页面上会出现哪段文字。"
                            "这一条只有人知道，猜不得（猜出来的成功判据会让产物「跑到底再报成功」）。")
            #: ★ 2026-09-24（用户点名：「失败的日志和取原配不是已经有成功条件了吗？为何还要再填……
            #: 没说成功啥的就按之前那个脚本来」）：**修站那条路上这一格改成选填** —— 人没说时按
            #: **底稿自己那一条**来（`_stage_fix_source` 手上就有那份源码）。所以这儿只拦 **build**。
            #: ⚠️ 底稿里也读不出来时**照旧拦**，只是那句话挪到了拿到底稿之后 —— 那条路
            #: **一个 job 都不开、一个字节都不落盘**，所以「不碰浏览器、不跑模型、不花钱」没变。
        if body.allow_skips is not None:
            if not body.allow_skips:
                problems.append("`allow_skips` 是空的（`[]`）—— 空列表没有意义：它和「没给」在图的边界"
                                "**分不开**，于是你以为「什么也不许跳」，实际会用默认（只允许跳 country）。"
                                "要么别给这个字段（用默认），要么把要跳的那几遍列出来：%s。"
                                % "、".join(selftest.RUN_NAMES))
            else:
                unknown = [n for n in body.allow_skips if n not in selftest.RUN_NAMES]
                if unknown:
                    problems.append("`allow_skips` 里有不认识的遍：%s。认的是这五个：%s。"
                                    "（写错的名字如果拖到自测那一步才炸，会先白烧掉一次探路 —— "
                                    "真窗口 + 一次模型跑。）"
                                    % ("、".join(unknown), "、".join(selftest.RUN_NAMES)))
        if body.expects is not None:
            # 契约 §四：`expect` 由运营写、**形状是封闭的**。免费的那一道闸 —— 形状错了
            # 在这儿响，而不是等到某一步判不出来时才发现「那格当初填的是什么鬼」。
            for i, item in enumerate(body.expects):
                bad = expect_problem(item)
                if bad:
                    problems.append("`expects` 第 %d 项不合形状：%s" % (i + 1, bad))
        if body.set_viewport:
            can_do = (self._window is not None and hasattr(self._window, "set_viewport"))
            allowed = list(body.allow_skips or ())
            if not can_do and "viewport" not in allowed:
                problems.append("载荷里要了 `set_viewport`（第 4 遍换窗口大小），但这个部署**没有接窗口层** —— "
                                "换不了。两条路，都摆在明面上：① 把窗口层接上（`BIT_WORKER_IP`/`BIT_ID`），"
                                "那这一遍就真跑；② 明确放弃它：把 `\"viewport\"` 写进 `allow_skips` —— "
                                "交出来的产物会带着「这一类失败这次**没验到**」。"
                                "服务不会替你默认放过它（R-5）。")
        return problems

    # ── 三个动作 ──────────────────────────────────────────────────
    def _stage_fix_source(self, body: "RunRequest", brief: dict) -> Optional[str]:
        """修站那条路的**底稿**：把后端那份 py 落成一个文件，返回它的路径。

        `mode != fix` ⇒ `None`（**build 那条路一个字都不动**）。

        ★ 底稿从**后端**来（用户 2026-09-21 点破的）：`GET /api/quest/formScript`
        就能拿到那个站的脚本源码，而**后端那份才是生产在跑的那一份**。
        所以这里**不**读本地 `forms/sites/<短名>.py` —— 那是本地的另一份，
        可能早就不是线上那份了（修错版本比不修更坏：改半天改的是别人手上的旧稿）。

        ★★ **拿哪个键去问**（第 ① 件事，2026-09-21）：那个读口的匹配规则是
        「**存的 site 必须是请求值的 host+path 前缀**」——
        存的键比请求值**深**时它就是 404（明明有这个站）。而人填的那一格
        （`body.url` = 失败证据里那条**入口网址**）常常比存的键**浅**
        （【我量的·2026-09-21】裸 `compareinsulation.io` 404，而
        `compareinsulation.io/article-1-c` 在）。所以**失败记录里那个键优先**
        （`body.fix_site`，面板从 `/failures/{单号}/evidence` 带下来的那一格）——
        那个键是**后端自己存的**，它自己是自己的前缀，从根上绕开那条规则。
        没给就照旧拿 `url` 去问（老那一趟一个字不变）。

        ⚠️ **键归键、路径归路径**：那个键是 `主机/路径` 的形状（**带斜杠**），
        所以它**只**用来问后端 —— 落盘的路径照旧走 `site` / `url` 推出来的短名，
        拿键去拼路径会得到一个没建过的子目录。

        ★★ 三种「拿不到底稿」都**在门口抛**（非 2xx + 人话）：

        | 情形 | 放它过去的后果 |
        |---|---|
        | 后端说这是 `type: json` | 拿一份空脚本去修一个好好的 json 站 |
        | 后端没有这个站（404） | 同上：「查不到」被读成「没有可修的」 |
        | 后端读不到（超时/非 JSON） | 「没量着」被读成「跑一趟试试」 |

        **三者的共同后果是同一个**：`fix_py` 空着 ⇒ `graph._intake` 不设 `fix_states`
        ⇒ `_explore` 走**非修站**那一支 ⇒ **悄悄退化成从头重新探索**
        （开真窗口、跑模型、把已有的证据丢掉重买一次）—— 而它在日志上与修站**长得一样**。
        这正是这个仓库最贵的那类形状，所以挡在门口、挡在**一个 job 都没开**的时候。
        """
        if str(getattr(body, "mode", "") or "") != MODE_FIX:
            return None
        #: ★ 失败记录里那个键优先（后端自己存的），没给才拿人填的入口网址去问。
        #: ⚠️ 它只在**还跟着它来的时候那一串网址**时才算数：人把「站点网址」那一格改了，
        #: 这趟活要修的**就不是那条失败记录那个站**了 —— 键继续用会**静默修错站**
        #: （面板上开的是 B 站，服务拿 A 站的键去读配置、去修，中间没有一处会响）。
        #: 判在**服务这一层**（不是页面）：页面只是把两格原样发上来，见 `runPayload`。
        ask_with = _backend_key(getattr(body, "url", ""), getattr(body, "fix_site", ""),
                                getattr(body, "fix_site_url", ""))
        try:
            #: ★ 停用的站要不要照修，**运营说了算**（2026-09-21）：勾了才把 debug 那一份
            #: 当底稿（见 `fmr._disabled_py_source`）。默认 False ⇒ 门口那句人话一个字不变。
            script = self._fmr.form_script(ask_with,
                                           allow_disabled=bool(getattr(body, "allow_disabled", False)))
        except fmr.FmrUnmeasured as exc:
            # 读不到 / 没这个站 / 没给 url —— 全走既有的「量不到」那张表（非 2xx + 原话）。
            raise self._unmeasured_to_http(exc)
        if str(script.get("type") or "") != "py":
            raise HTTPException(
                status_code=400,
                detail="修不了这个站：后端说它跑的是 **JSON 配置**，不是脚本"
                       "（`type: json`）。⚠️ 拿一份空脚本去修一个 json 站，"
                       "下游看起来与「这个站该补一份脚本」**一模一样** —— "
                       "所以在这儿停。这一类该走配置那条路。")

        #: ★ 2026-09-24（用户点名）：「什么算成功」**选填** —— 人没说就按**底稿自己那一条**。
        #: ⚠️ **只搬恰好一串**那一种：两串以上时「挑哪一串」是**人的意图**（它决定什么算成了），
        #: 服务不替人挑；一串都读不出来（判据写在函数里 / 它只判网址）时**照旧拦**，
        #: 并把「这一份底稿靠什么判成功」说清楚。
        #: ⚠️ 排在这儿（**写盘之前**、开 job 之前）：所以下面那句话里敢写「没有写任何文件」。
        if not str(getattr(body, "success_text", "") or "").strip():
            source = str(script.get("source") or "")
            texts = fix.success_texts_from_source(source)
            if len(texts) == 1:
                brief["success_text"] = texts[0]
                brief[SUCCESS_TAKEN] = texts[0]
            else:
                raise HTTPException(
                    status_code=400,
                    detail=self._fix_success_say(
                        texts, fix.success_clue_from_source(source)))
        site = str(getattr(body, "site", "") or "").strip() or graph.site_name(getattr(body, "url", "") or "")
        out_dir = pathlib.Path(str(brief.get("out_dir") or self._out_dir))
        out_dir.mkdir(parents=True, exist_ok=True)
        staged = out_dir / ("%s.before.py" % site)
        #: ⚠️ **逐字节**写下去：后端原话「首尾换行是源码的一部分」，
        #: 写口又拿 sha256 当指纹 —— 在这儿 strip 一下，后面写回去的就是另一份文件了。
        #: ★ **这一版的底稿是哪一份**（2026-09-21）：走 debug 那条路时它是**停用**那份 ——
        #: 必须一路带出去（闸上、报告里都要看得见）。不带的话，「拿停用那份改出来的补丁」
        #: 与「拿线上启用那份改出来的」在屏幕上**一模一样**，而它们是两件不同的事。
        brief["fix_base"] = (
            "**停用那一份**（`type=debug` 读回来的，后端 `status: 0`，sha256 %s —— "
            "⚠️ 这一份**可能不是生产在跑的那一份**）" % str(script.get("sha256") or "?")[:12]
            if script.get("debug_read") else
            "线上**启用**的那一份（sha256 %s）" % str(script.get("sha256") or "?")[:12])
        staged.write_text(str(script.get("source") or ""), encoding="utf-8")
        return str(staged)

    @staticmethod
    def _fix_success_say(taken: list, clue: str) -> str:
        """「修不了这一趟：没给判据、底稿里也读不出来」那句人话（门口那句之一）。

        两种不搬的情形**分成两句话**（处置不同：一种是**你挑一串**，一种是**你补一句话**）——
        合成一句的话，读的人不知道自己是缺一串字还是缺一条完全不同的判据。
        """
        if len(taken) > 1:
            why = ("底稿里**有**这一格，可是它写着**不止一串**：%s —— "
                   "产物那一格一次只认**一串**，而「挑哪一串」是**你的意图**"
                   "（它决定什么算成了），服务不替人挑。"
                   % "、".join("`%s`" % t for t in taken))
        else:
            why = str(clue or "").strip() or (
                "这一份底稿里**没有**可读的成功文案（判据可能写在函数里，或者它压根不判这一格）。")
        return ("修不了这一趟：**没给成功判据**（走通之后页面上会出现哪段文字），"
                "而**底稿里也读不出来** —— 服务不猜一个（猜出来的判据会让产物「跑到底再报成功」）。\n"
                + why +
                "\n补一句再发起：那一格就是「什么算成功」。"
                "⚠️ 这一趟**没有**开浏览器、没有跑模型、也没有写任何文件（只读了后端那份底稿）。")

    def start(self, body: RunRequest) -> dict:
        problems = self._intake_problems(body)
        if problems:
            raise HTTPException(status_code=400, detail=self._problems_say(problems))

        brief = body.model_dump(exclude_none=True)
        brief = self._materialize_form_data(brief)
        #: 人在开工前说的那句 → `hints`（`note` 这一格**不留在载荷里**：图那份 schema 里
        #: 没有 `note`，留着会被 langgraph **静默丢掉** —— 与 `fix_py` 当年那个坑同一族）。
        said = str(brief.pop("note", "") or "").strip()
        if said:
            brief["hints"] = [said]
        brief.setdefault("out_dir", self._out_dir)
        brief["success_text"] = body.success_text
        # ⚠️ `expects` 也在门口换了（修复轮 1），所以「第几项换了几个」要**跟着这条载荷走**：
        # 判那一步的是 `_note_step`（在图上跑），门口换掉之后它手上只剩换好的值
        # —— 不把个数带过去，那条静默路径就又回来了。
        brief[EXPECTS_UNWRITABLE] = list(body.unwritable_items("expects"))
        # ★ B 线 py 支：修站那条路的底稿从**后端**读、落成一份文件再喂给图。
        # ⚠️ 排在这儿是为了「拿不到底稿」**在开 job 之前**就红掉 —— 见那个方法。
        staged = self._stage_fix_source(body, brief)
        if staged:
            brief["fix_py"] = staged
        #: ★ 2026-09-24：这一格 = 「判据是**服务从底稿搬来的那一串**」（空 = 人自己填的 / 没这回事）。
        #: ⚠️ 必须摆出来（没有静默的路径）：不说的话，运营以为判据是**自己**填的那条。
        took_success = str(brief.get(SUCCESS_TAKEN) or "")
        self._clean_window_for_explore(brief)     # R-F1 的另一半：**探路也要干净会话**
        #: ★ 2026-09-22：窗口是**服务自己**开的（面板没有挑窗口那一栏）⇒ 开不出来时这一趟
        #: **必死**。按「拿不到底稿就不开 job」同一条规矩（`_stage_fix_source`）：门口红掉，
        #: 并把外面那句原话摆出来（调用方**给了** `ws_url` 的照旧往下跑 —— 见那个方法的 docstring）。
        opened_badly = str(brief.get(WINDOW_OPEN_FAILED) or "")
        if opened_badly and not str(brief.get("ws_url") or "").strip():
            raise HTTPException(status_code=502, detail=RUN_OPEN_FAILED_SAY % opened_badly)
        job_id = "job-%s" % uuid.uuid4().hex[:12]
        job = Job(job_id=job_id, brief=brief, status=QUEUED, say=SUBMITTED_SAY,
                  created_at=datetime.datetime.now().astimezone().isoformat(timespec="seconds"))
        with self._jobs_lock:
            self._jobs[job_id] = job
        try:
            job.graph = self._build_graph(brief, job_id)
        except BaseException as exc:                 # 拼不起来（saver 连不上之类）
            with job.lock:
                job.status = FAILED
                job.error = "%s: %s" % (type(exc).__name__, exc)
                job.say = ("起不来：%s\n（这一趟**没有**开浏览器、也没有写任何产物。）" % exc)
                said, raw = job.say, job.error
            # 目录表第 5 行说的是 `_advance` 的 except；**这一条**（图都拼不起来）
            # 同样是「跑挂」，同样不许静默 —— 时间线上得有一条，否则它像没存在过。
            self.narrate(job, "failed", said, error=raw)
            return self._view(job_id)
        # 窗口时间线探针：从这一刻起盯住「窗口是哪个进程」（Task 1 / G3）。
        # **只在能给 PID 的窗口层上起** —— 桩窗口没有 PID，那样的线判不出「重开了几次」。
        self._active_job = job_id
        self._start_window_probe()
        # ★ Task 12：**刚交上去就量一眼那个窗口**，让面板上「现在什么状态」那一格有话说。
        # 不量的话，头 `_probe_seconds` 秒里那一格只能说「服务还没问过」（探针第一眼要等
        # 一个间隔才响）—— 而人刚刚按的正是「开一趟」，那一刻他最想知道的就是「窗口开出来了吗」。
        # ⚠️ 这一行**不是新的口径**：它就是那条时间线的第一行（`_probe_window_row`）。
        # 没接窗口层就不量：那种部署本来就没有窗口可言（`window_public` 整个给 `None`）。
        if self._window is not None:
            try:
                self._probe_window_row(job_id, note="刚交上去，量一眼这个窗口")
            except Exception:                  # noqa: BLE001 —— 旁路不许把这一趟带塌
                traceback.print_exc()
        # 目录表第 3 行：先记「收到」，再（前面有东西时）记「排队等窗口」。
        # ⚠️ **先说后交**是有意的：交给队列之后工作线程可能立刻喊「在跑」，顺序就反了。
        # ⚠️ 载荷里换掉的字节要说出来（Task 8 补丁 A）：`/run` 收的**全是外面来的字**
        # （url / goal / success_text / 窗口那一串…），而它们一路会进 state、再回 `/live`
        # 与 `/job/{id}`。这一句人话落在时间线上（那正是运营读的那一屏）——
        # `/job/{id}` 的**既有形状**一个字都不动（那儿不加格）。
        self.narrate(job, "submitted",
                     self._submitted_say(body) + body.unwritable_say()
                     + self._took_success_say(took_success))
        if self._something_is_ahead():
            self.narrate(job, "queued", QUEUED_SAY)
        self._submit(job, self._payload(brief))
        return self._view(job_id)

    @staticmethod
    def _submitted_say(body: RunRequest) -> str:
        """交上去的那一刻那句话（目录表第 3 行）。

        ⚠️ `/again` 起的那一趟要说清**它是重来**：不说的那一屏，第一句与一趟全新的跑
        长得一模一样 —— 而「你说的话我记着」正是那个按钮唯一的承诺（计划 Task 8）。
        """
        if body.again_from:
            return AGAIN_SUBMITTED_SAY % (body.again_from, len(body.hints or []))
        return SUBMITTED_SAY

    @staticmethod
    def _took_success_say(taken: str) -> str:
        """「这一格你没填，服务按底稿自己那一条走」那句（空串 = 没有这回事）。

        ★ 2026-09-24（用户点名「没说就按之前那个脚本来」）：搬了就得**说出来** ——
        不说的话，运营以为判据是**自己**填的那条，而它其实是**老脚本**那条；
        两条不一样时，屏幕上**没有任何地方**看得出来。
        """
        if not taken:
            return ""
        return ("\n「什么算成功」这一趟**你没填** —— 服务按**这一趟的底稿**（后端那份 py）里"
                "老脚本自己那一条走：「%s」。⚠️ 要换成别的，就在下一次发起之前填上那一格；"
                "这一趟已经按这一条在判了。" % taken)

    @staticmethod
    def _payload(brief: dict) -> dict:
        """开场白 → 图认得的那几个键（服务这一层的开关，比如 `set_viewport`，不往里塞）。

        ⚠️ `hints` 进得来、`again_from` 不进：前者是**图的状态**（`state.hints`，一路带进
        draft），后者是**服务自己的一句话**（「这是从哪一趟重来的」）—— 图不需要知道它的上一世。
        """
        keep = ("url", "goal", "mode", "success_text", "evidence", "site", "ws_url",
                "form_file", "env", "platform", "out_dir", "allow_skips", "entry_url",
                "hints",
                #: ★ B 线 py 支（2026-09-21）：修站那条路的**底稿路径**。
                #: ⚠️ 少了它，服务算出来、也落了盘，却**发不到图里** ——
                #: `graph.py:346` 那个 `if fix_py:` 恒为假，那条路「接上了但不响」
                #: （`state.py:176` 记的正是上一次这么栽的）。
                "fix_py",
                #: ★ **这一版的底稿是哪一份**（2026-09-21）：线上启用那份 / 停用那份。
                #: ⚠️【同一天实测】加 `fix_base` 那一次**又栽在同一个地方** —— 服务把它算出来了、
                #: 状态里也声明了，可它不在这张白名单里 ⇒ 发不进图 ⇒ 闸上印的是「（没说）」。
                #: 所以这一格与 `fix_py` 是**一件事的两半**：谁改了其中一个，另一个一起改。
                "fix_base")
        return {k: brief[k] for k in keep if k in brief}

    def reply(self, job_id: str, body: ReplyRequest) -> dict:
        job = self._jobs.get(job_id) or self._recover(job_id)   # 重启过就从 checkpoint 捡回来
        if job is None:
            raise KeyError(job_id)
        view = self._view(job_id)
        if view["status"] != WAITING:
            raise HTTPException(status_code=409, detail=
                                "这个任务没在等人（它现在是「%s」）—— 没有要你回的话。"
                                "跑到头了就另起一个任务；要它接着走，先看 `say` 里说了什么。"
                                % self._status_say(view["status"]))

        # P6：窗口只活几分钟，而人可能过了十分钟才回话。先问一句窗口还在不在 ——
        # 不先问的后果是自测拿着一个死窗口跑，报告把「连不上」记成**产物的问题**。
        values = dict((self._snapshot(job_id).values or {}))
        dead = self._window_is_gone(values.get("ws_url"))
        if dead:
            # 目录表第 1 行的另一处落点：这件事是**在这儿**被发现的（人回了话，服务才去查），
            # 那就得**在这儿**说 —— 否则「窗口没了」只有那个 409 知道，
            # 而坐在页面前面的人只看到「回话被拒」：时间线上一片安静（那正是这一片要治的）。
            self._note_window_died(job, values, dead=True)
            raise HTTPException(status_code=409, detail=WINDOW_GONE_REPLY_SAY % job_id)
        # ⚠️ 先把 job 从「停住」挪开，**再**交下去。
        # 不挪的话：`_view` 会从 checkpoint 投影（那个中断还在）→ 响应说「在等人」+
        # 旧那道闸 → 调用方再回一次话 → 那一句 resume 落到**下一道闸**上 →
        # **一步在没人看着的情况下跑掉了**（§6.2/D16 的核心承诺）。
        with job.lock:
            job.status = RUNNING
            job.say = "收到你的话，接着跑（下一个要你拿主意的地方会再停下来）。"
        # 送这一句会怎么改变队里那些话（**先算、不改**）：送出去的 + 不再摆给他的。
        # 算在这一步，是因为下面那条时间线要把「那一句不再摆给他了」一起说出来
        # （同一件事的两半，并进他**这一条**气泡里）。
        sent, superseded = self._inbox_plan(job, str(body.note or ""))
        # 目录表第 8 行：人的原话与它去哪了（**交下去之前**记，否则工作线程先喊「在跑」）。
        self._note_human_said(job, job_id, body,
                              superseded=(str(superseded[0].get("text") or "")
                                          if superseded else ""))
        self._submit(job, Command(resume={"action": body.action, "note": body.note}))
        # 真的交下去了，队里那几条才跟着走（修复轮 1 / I-2；位置见修复轮 2 的那条用例）。
        # ⚠️ 位置在 `_submit` **之后**：上一步（narrate）抛的话，这句话并没有送出去，
        # 那就一个字都不许翻（翻了 = 把没送到的话记成送到了）——
        # `test_the_queue_only_flips_after_the_sentence_really_went_out` 钉着它。
        self._apply_inbox_plan(job, sent, superseded)
        return self._view(job_id)

    # ── Task 8：人在回路（`/say` `/stop` `/again`）──────────────────────────
    # ⚠️ 这三个都**不替人往前走一步**（Global Constraints 的原话：「服务可以替人「停」，
    #    绝不替人「走」」）。`/say` 只**记下来**（到下一道闸进输入框，人按按钮才发）；
    #    `/stop` 是**阻止**那一半授权；`/again` 起的是**新的一趟**（不是替人回答什么问题）。

    def say(self, job_id: str, body: SayRequest) -> dict:
        """`POST /job/{id}/say` —— 人说了一句（设计注 §4.2）。

        它**永远不替人往前走一步**：这一句只是记进 `Job.inbox`，到下一道闸进输入框，
        **人按按钮才发**。为什么不在闸上直接当 note 送下去（那本来是 §4.2 第一行说的）：
        那正是「替人走一步」—— 送下去 = 图被 resume = 一步在没人看着的情况下跑掉了。
        要送，人按闸上那个按钮（页面在闸上走的是 `/reply`，那是他**自己**按的）。

        `202`：这句话被**收下**了，但它还没送到它手上（送到了才叫 delivered）。
        ⚠️ `queued` / `delivered` 那两格由 `say_route` 那个纯函数定（R1）。

        ⚠️ **两支走的是同一条路**（Task 9）：都只进 `Job.inbox`，谁都没在这儿把话送出去 ——
        差的是**它会怎么到它手上**（`route`）：

          - `queued`：到下一道闸进输入框，人按按钮才发；
          - `delivered`：探路**下一次问模型之前**由 `_steer_cb` 交给它（那才是真正送出去的那一刻，
            时间线上那条 `steer_landed` 说的就是它）。

        ⇒ 「直达」**不等于**「它已经看到了」：这一句此刻只是排在队里等着下一轮交出去
        （`input.queued` 里看得见它，`delivered` 那一格还是 `False`）。页面那句提示也是这么
        承诺的：**送到之后**时间线上才会出现一条「交给它了」。
        """
        job = self._jobs.get(job_id) or self._recover(job_id)
        if job is None:
            raise KeyError(job_id)
        text = str(body.text or "").strip()
        if not text:
            raise HTTPException(status_code=400, detail=SAY_EMPTY_SAY)
        kept, cut = _cut_say(text)
        view = self._view(job_id)
        status = view["status"]
        if status in (DONE, FAILED):
            raise HTTPException(status_code=409, detail=SAY_OVER_SAY % self._status_say(status))
        stage = self._stage_now(job, job_id, status)[0]
        route = say_route(status, stage, steer=STEER_WIRED, held=self._steer_held(job))
        with job.lock:
            job.inbox.append({"text": kept,
                              "at": datetime.datetime.now().astimezone()
                                    .isoformat(timespec="seconds"),
                              "delivered": False, "superseded": False,
                              # ⚠️ **服务答应的那一格**（回归 2 / NEW-1）：只有走直达那条路
                              # 收下的话才盖它 —— 兑现不了时的更正（`steer_missed`）
                              # **以这一格为准**（不是「队里还有没有话」）。
                              "promised": route == SAY_DELIVERED,
                              # ⚠️ **这一条话的号**（回归 3 / R3）：更正**按条目**去重就靠它 ——
                              # 按**文本**去重的话，「同一句话说了两遍」产生的**第二条承诺**
                              # 每个出口都收不回来（复审判出来的那条残余静默）。
                              # ⚠️ 号来自 **Job 上只增不减的计数器**（回归 4 / ★1），**不是**
                              # `len(inbox)`：后者要靠「条目只增不删」—— 而将来有人加一句
                              # 「送出去就从队里拿掉」，号就会**撞上老条目**，那条新承诺
                              # 此后每个出口都被去重滤掉（不可自愈的静默，复审搭形状量过）。
                              # 计数器不靠任何别的东西，所以这件事**没有前提**。
                              "seq": _next_say_seq(job)})
        # `n` 与 `/live.input.queued` **同一个口径**（修复轮 3 / NEW-R1）—— 同一处判据
        n = len(self._still_waiting(job))
        # ⚠️ 两句话说的是两条路（R2 的「同一件事不许两个名字」反过来：
        # 两件事不许共用一个名字）——「排队等闸、按一下才送」摆在直达那条路上就是假话。
        # `_queued_say` 的尾巴那句「队列里现在排着 N 句 —— **只预填、不自动发**」同理不带上：
        # 直达那几秒里它们**都会**进下一轮，说「只预填」是反的（`n` 那一格照报，它是事实）。
        say = (SAY_DELIVERED_SAY if route == SAY_DELIVERED
               else self._queued_say(view, stage, n))
        # ⚠️ **换掉的字节要说出来**（Task 8 补丁 A）：消毒在**载荷进服务那一刻**做过
        # （`_Intake`），个数记在那条载荷身上 —— 那一句人话由这里并进响应（并随它进时间线）。
        # 位置与「截断」那一条**并列**：两件都是「你写的字没有原样留下」的**有损**，
        # 有损就得报个数（Global Constraints：没有静默的路径）。
        say += body.unwritable_say()
        if cut:
            say += "\n" + (SAY_CUT_SAY % (len(text), len(kept)))
        # 时间线上记的是**人自己那句话**（逐字转抄，只有超长那一截不带 —— 而且说了）
        self.narrate(job, "human_said", "%s\n%s" % (kept, say), who="you",
                     text=kept, route=route, n=n, cut=cut)
        return {SAY_QUEUED: route == SAY_QUEUED, SAY_DELIVERED: route == SAY_DELIVERED,
                "n": n, "say": say}

    @staticmethod
    def _inbox_plan(job: Job, note: str) -> tuple:
        """这一句按下去会怎么改变队里那些话：`(要翻成已送出的, 要标成不再摆给他的)`。**只算不改。**

        - **送出去的按文字认**（`delivered`）：`note` 与哪几条的 `text` 一样，那几条都算送到了
          —— 送下去的话就一句（同文说两遍、按一次 = 那两遍都送到了；只翻一条的话，
          剩下那条下一道闸**又被预填**，那正是 I-2/NEW-1 要治的形状）。
        - **不再摆给他的那一条，按「服务本来要摆的是哪一句」认**（`superseded`）：他按下去的是
          **别的**（`note` 非空、且与还在等的那最后一条不同）⇒ 那条标上。
          ⚠️ 这是**观察到的事实**，不是猜他的意图：服务**本来要摆给他的就是这一句**
          （那一刻 `draft_note` 会给的就是它），而他送下去的是**别的**。
          ⚠️ 这里原先写的是「这一句**摆在他面前过**」 [禁语]—— 那是**假话**（预填不覆盖正在打字的
          框，他可能压根没看见过；见 `HUMAN_SAID_SUPERSEDED_SAY` 上面那段）。修复轮 4 / F3。
        - `note` 空（按的是「继续」、框里没话）⇒ **什么都不改**：他没送这句，也没说别的。
        ⚠️ 判据不在这儿（修复轮 4 / F1）：这一条**全程持着 `job.lock`**，而 `_still_waiting`
          自己也会拿锁 ⇒ 在这儿调它**会死锁**。所以判据放在**不拿锁的纯核**里
          （`_waiting_entries` / `_delivered_by`），这里只是**持着锁直接用**。
        """
        text = str(note or "").strip()
        if not text:
            return [], []
        with job.lock:
            sent = Service._delivered_by(job.inbox, text)
            waiting = Service._waiting_entries(job.inbox)
            front = waiting[-1] if waiting else None
            superseded = ([front] if (front is not None
                                      and str(front.get("text") or "") != text) else [])
        return sent, superseded

    @staticmethod
    def _apply_inbox_plan(job: Job, sent: list, superseded: list) -> None:
        """把上面算出来的那两件事写回那几条**自己**（不追加新的 —— 这一格是那条话自己的状态）。"""
        with job.lock:
            for entry in sent:
                entry["delivered"] = True
            for entry in superseded:
                entry["superseded"] = True

    def _queued_say(self, view: dict, stage: str, n: int) -> str:
        """「这句话排着了」那句人话（**两种处境两句不同的话**，不许拿一句盖两件事）。"""
        if view["status"] == WAITING:
            step = str((view.get("gate") or {}).get("step") or "")
            say = SAY_QUEUED_AT_GATE_SAY % STEP_SAY.get(step, step or UNKNOWN_STEP_SAY)
        else:
            say = SAY_QUEUED_SAY % self._where_it_is_say(view["status"], stage)
        if n > 1:
            say += "\n" + (SAY_QUEUE_LENGTH_SAY % n)
        return say

    def _where_it_is_say(self, status: str, stage: str) -> str:
        """它**现在在哪儿**（一句人话）—— 给上面那两句当宾语。说不准就说不准，不编。"""
        if status == QUEUED:
            return "还在排队等窗口"
        if status == RUNNING:
            if stage:
                return "在跑（%s）" % STEP_SAY.get(stage, stage)
            return "正在跑（这一刻说不准是哪一个节点）"
        return self._status_say(status)

    def stop(self, job_id: str) -> dict:
        """`POST /job/{id}/stop` —— 「停下，我要说一句」（设计注 §四.1 + R2）。

        矩阵四行，落在四个地方（每一条都**说出来**，而且**都不推进任何一步**）：
          ① 已经在闸上 → **立刻**：把 `{"action": "stop"}` 交下去（这一步**不做**）；
          ② 探路里跑 → **几秒内**：`stop_requested` 就是探路 `should_pause` 读的那一格；
          ③ 别的节点里跑 → **跑完这一步**，停在下一个闸口（那个闸口本来就在等人）；
          ④ 还没轮到窗口（`queued`）→ 它一动就会先停在第一道闸上（R2：**不编节点名**）。
        ⚠️ 只有 ① 会推图，而推下去的是**「停」**（不是「继续」）—— 那是这一片唯一的让步。
        """
        job = self._jobs.get(job_id) or self._recover(job_id)
        if job is None:
            raise KeyError(job_id)
        view = self._view(job_id)
        status = view["status"]
        if status in (DONE, FAILED):
            raise HTTPException(status_code=409, detail=STOP_OVER_SAY % self._status_say(status))
        held = self._has_queued_words(job)
        if status == WAITING:
            # 矩阵第 3 行：**立刻**（== `reply {"action":"stop"}`）—— 「停」是阻止，不是推进，
            # 所以这一条**不替人往前走**：它让这一步**不发生**。
            step = str((view.get("gate") or {}).get("step") or "")
            plan = stop_plan(status, step, held_words=held)
            with job.lock:
                job.stop_requested = True
                job.stop_where = plan["where"]
                job.stop_say = plan["will_stop_at"]
                job.status = RUNNING
                job.say = STOP_AT_GATE_SAY
            self._note_human_stop(job, plan)
            self._submit(job, Command(resume={"action": "stop", "note": ""}))
            return {"stop": {"requested": True, "where": plan["where"],
                             "will_stop_at": plan["will_stop_at"],
                             "say": STOP_RECORDED_SAY % plan["will_stop_at"]}}
        stage = self._stage_now(job, job_id, status)[0]
        plan = stop_plan(status, stage, held_words=held)
        with job.lock:
            job.stop_requested = True
            job.stop_where = plan["where"]
            job.stop_say = plan["will_stop_at"]
        self._note_human_stop(job, plan)
        return {"stop": {"requested": True, "where": plan["where"],
                         "will_stop_at": plan["will_stop_at"],
                         "say": STOP_RECORDED_SAY % plan["will_stop_at"]}}

    # ── 队里那些话的**判据**（Task 8 修复轮 4；Task 9 回归 2 加了第四个）：全部收在纯核里 ──
    # ⚠️ 它们**只吃一组条目、不拿锁**：调用方按自己手上的处境决定怎么拿锁 ——
    #    `Job.lock` 是**普通 `Lock`**（不是 `RLock`），在**已经持锁**的地方调一个自己拿锁的
    #    函数就是自己等自己（实测**永久挂住**，`/live` 上就是运营那一屏永远转圈）。
    #    ⇒ 形状是「**一个不拿锁的纯核 + 薄调用方**」：`_still_waiting` 自己拿锁再调纯核；
    #      `_inbox_plan` 在它**已经持着锁**的地方直接调纯核。两个要求于是同时成立：
    #      **判据只有一处**（下面这排），而且**没有一处**在持锁时再去拿锁。
    # ⚠️ **不许在别处读条目上那两个键**（`delivered` / `superseded`）：副本会**静默分岔**
    #    （修复轮 4 / F1：`_inbox_plan` 里那份「决定谁被标 `superseded`」的副本漂过了整整一轮，
    #    复审的变异 `R1e` 让两份分岔 ⇒ **全绿**）。机器守在
    #    `tests/test_service_input.py::test_the_inbox_criteria_live_in_exactly_one_place`。

    @staticmethod
    def _waiting_entries(entries: list) -> list:
        """（判据 ①）**真正还在等**的话：没送出、也不再摆给他。⚠️ 纯核，**不拿锁**。"""
        return [x for x in entries
                if not x.get("delivered") and not x.get("superseded")]

    @staticmethod
    def _delivered_by(entries: list, text: str) -> list:
        """（判据 ②）这一句送下去，哪些条目算**送到了**：同文、且还没送过。⚠️ 纯核，**不拿锁**。"""
        return [x for x in entries
                if not x.get("delivered") and str(x.get("text") or "") == text]

    @staticmethod
    def _steer_promised(entries: list) -> list:
        """（判据 ④，Task 9 回归 2）**答应过直达、而还没送到**的那些话。

        ⚠️ 纯核，**不拿锁**（与那三个同一条纪律）。`promised` 那一格是 `/say` 在
        `route == delivered` 那一刻盖的 —— 更正（`steer_missed`）**以它为准**：
        没承诺过的不报（那样会把一句从没给过的承诺收回来 = 编话），
        承诺过的**每个出口都要报**（到头 / 停在闸上 —— 不然承诺就烂在时间线上）。
        ⚠️ `superseded` **不排除**：那一格说的是「还摆不摆给他」（预填），
        与「答应过直达没有」是两件事 —— **不再摆给他的**那一条**照样答应过**，照样要收回。
        """
        return [x for x in entries if x.get("promised") and not x.get("delivered")]

    @staticmethod
    def _unsent_texts(entries: list) -> list:
        """（判据 ③）**没送到它手上**的那几句（`/again` 要带过去的；**含**不再摆给他的那些）。
        ⚠️ 纯核，**不拿锁**。
        """
        return [str(x.get("text") or "") for x in entries if not x.get("delivered")]

    @staticmethod
    def _still_waiting(job: Job) -> list:
        """队里**真正还在等**的那些话 —— 判据写在 `_waiting_entries`（**只有那一处**）。

        ⚠️ 为什么必须只有一处（修复轮 3 / NEW-R1）：同一个口径原先写了两处半
        （`_input_now` 一处、`_has_queued_words` 一处、`/say` 里的 `n` 半处），
        第三处漏了 ⇒ `/say` 的人话说「队列里现在排着 **2** 句」而同一刻
        `input.queued` 只有 1 条：那句话对一条**再也不会预填**的话也说「会进输入框」。
        ⚠️ 「这一条判据只有这一处」在修复轮 4 之前是**假话**（复审 3 一句 grep 就证伪）：
        `_inbox_plan` 里还**手写着一份副本**，而且是**承重的那一份**（它决定谁被标
        `superseded`），两份可以分岔且零红灯（F1）。现在副本没了，这句话才成立 ——
        判据在 `_waiting_entries`，**这一条只是自己拿锁的那个薄调用方**。
        ⇒ 要改口径（比如 Task 9 决定「不再摆给他的也喂下去」）就改 `_waiting_entries`，
        别去改调用点；也别在别处再抄一份（有机器守着，见上面那段）。
        """
        with job.lock:
            return Service._waiting_entries(job.inbox)

    def _has_queued_words(self, job: Job) -> bool:
        """队里还有没有**还等着送**的话（只影响那句人话要不要提它一句）。

        ⚠️ 不再摆给他的那几条**不算**：它们不会再进输入框，说「你说的话已经排好了，
        到那儿会进输入框」就是假话（判据见 `_still_waiting`）。
        """
        return bool(self._still_waiting(job))

    # ── 直达（Task 9）：把还在等的那几句交给探路的下一轮 ────────────────────────

    @staticmethod
    def _steer_plan(entries: list) -> tuple:
        """（Task 9 的判据）这一轮交给它的那几句 + 交完之后算**送到了**的那些条目。

        ⚠️ **纯核，不拿锁**（与那三个纯核同一条纪律）：调用方按自己手上的处境决定怎么拿锁。
        ⚠️ 判据一个字都不在这儿（R2/R3）——这里只把**那两处**的结果加起来：
          - **喂的集合** = `_waiting_entries`（真正还在等的那些：没送出、也不再摆给他的）；
          - **算送到了的** = `_delivered_by`（按「**这一句真的发出去了**」认，
            Task 8 那处立的判据：同文说两遍，那一句送出去 = 那两遍都送到了）。

        ⇒ 「不再摆给他的」（`superseded`）**不进喂的集合**（`_waiting_entries` 天然不含它们，
        一行特例都不用写，R3）—— 但要是**同一句话**另有一条还在等，`_delivered_by` 照样
        把那一条也算成送到了（那是「这句话到过它手上没有」，不是「还摆不摆给他」）。

        返回 `(要喂的那段话, 要翻的条目)`：话是**按人说过的先后**拼的（一次交完），
        空队就是 `("", [])`。
        """
        waiting = Service._waiting_entries(entries)
        texts = [t for t in (str(x.get("text") or "") for x in waiting) if t]
        if not texts:
            return "", []
        return "\n".join(texts), [x for t in texts for x in Service._delivered_by(entries, t)]

    def _note_steer_landed(self, job: Job, text: str, sent: list) -> None:
        """那一轮**真的发出去了** ⇒ 这才算「交给它了」：说一条 + 翻 `delivered`（Task 9 / F2③）。

        ⚠️ **顺序照 `/reply` 那条路同一条纪律**（那一处的原话：narrate 抛的话，这句话
        并没有送出去，那就一个字都不许翻 —— 翻了就是把没送到的话记成送到了）：
        「说」在前、「翻」在后。两者**不嵌套**：`narrate` 自己也拿 `job.lock`，
        套在持锁的块里就是自己等自己（`Job.lock` 不是 `RLock`）。
        ⚠️ 翻走 `_apply_inbox_plan`（Task 8 立的那个**唯一的写入口**）—— `delivered`
        这一格全仓只有它一处写（判据那一侧是三个纯核，两处都不许再抄）。
        """
        self.narrate(job, "steer_landed", STEER_LANDED_SAY, text=text)
        self._apply_inbox_plan(job, sent, [])

    def _note_steer_missed(self, job: Job, *, at_gate: bool = False) -> None:
        """**答应过直达的话没送到** ⇒ 说一条（回归 1 / F1b + F2②；回归 2 按 NEW-1 改准）。

        为什么非有它（Global Constraints 的「没有静默的路径」）：`/say` 在探路里回的是
        「直达下一轮」，而**送不到是可能的** —— 人刚按了停、话正好说在最后一轮之后、
        或者那一次调用自己炸了。话**不会丢**（一直排在队里：`/live.input.queued`、
        下一屏的预填、`/again` 都看得见），**丢的是那句承诺**；承诺兑现不了，就要说回来。

        ⚠️ **谁说**（回归 2 / NEW-1 的修正）：**当初被承诺过直达**的那些（纯核
        `_steer_promised` = 条目上 `promised` 那一格 + 还没送到）—— 不是「队里还有话」。
        排队收下的那些**不报**：`/say` 当时说的就是「到下一道闸进输入框，按一下才送」，
        那本来就是诚实的；替它收回一句从没给过的承诺就是**编话**，
        而且会把理由句也说错（「那一轮没发出去」跟它没经历过的事对不上）。

        ⚠️ **在哪儿说**（回归 2 / NEW-1 的修正）：**出口有三处，三句话各不相同**
        （`at_gate` / 跑挂 / 到头了）—— 停在闸上那一处原先没有，于是「承诺了却停在闸上」
        一个字都不更正（复审 O2）。三句**不许互换**（各自说的是各自那一刻发生的事）。

        ⚠️ **只在开关打开时才有这一句**：要说回来的是**「直达」那句承诺**，而它只有通道
        接上时才给得出来（`say_route` 的 `steer`/`held` 两个实参）。关着的时候 `/say` 说的是
        「排队、到下一道闸进输入框」——**那本来就是诚实的**（R1），今天生产那条路**一个字节都不变**。
        ⚠️ **同一条话只报一次**（`job.steer_missed_reported`，按条目的 `seq` 认）：
        同一趟里停在闸上说过一次、后来这一趟到头了**不许**再说一遍；
        而「同一句话说了两遍」= **两条**话（各自的 `seq` 不同）⇒ **两条都要收回**（R3）。
        ⚠️ 判据仍走纯核（**不拿锁的那个**）—— 持锁处不许调 `_still_waiting`。
        """
        if not STEER_WIRED:
            return
        with job.lock:
            # ⚠️ 去重按**条目**（`seq`）不按文本（回归 3 / R3）：同文说两遍 = **两条承诺**，
            # 两条都要在各自的出口收回（按文本去重时第二条永远收不回来）。
            # ⚠️ 「没话可说」的那一条**不许进 fresh**（回归 4 / G2）：先标记、再发现没话说而早退，
            # 就是把那一条记成「报过了」—— 它此后**每个出口**都被去重滤掉（永久静默）。
            # `/say` 今天挡着空文本（400），但形状不许留这个坑（下一个人挪一行它就可达了）。
            fresh = [x for x in Service._steer_promised(job.inbox)
                     if x.get("seq") not in job.steer_missed_reported
                     and str(x.get("text") or "").strip()]
            if not fresh:
                return
            # ⚠️ **这里原先就把 `seq` 记进 `steer_missed_reported` 了**（Task 8 补丁 A 挪走的那一行）：
            # 「先标记、后说」在**说得出**的时候看不出来，说不出的时候就是**永久静默**
            # （标了 = 此后每个出口都被去重滤掉）。所以标记挪到 `narrate` **之后**
            # （与 `_note_steer_landed` / `/reply` 同一条纪律：**说在前、翻在后**）。
            said = "\n".join(str(x.get("text") or "") for x in fresh)
            crashed = job.status == FAILED
        # ⚠️ **转抄的那一刻换掉线上写不出来的字节**（Task 8 补丁 A；与 `_note_step` 里
        # `expect` 那一行同一条纪律 —— 人打的字同样是**外面来的**）：不换的话 `events._facts`
        # 那道闸会**整条拒掉**这一条事件，于是「说不出」又回来了
        # （而丢记录比换一个字节坏得多 —— 契约 §二②）。
        said, replaced = events.safe_value(said)
        why = (STEER_MISSED_AT_GATE_SAY if at_gate
               else (STEER_MISSED_DIED_SAY if crashed else STEER_MISSED_ENDED_SAY))
        sentence = STEER_MISSED_SAY % (said, why)
        if replaced:
            sentence += "\n" + (UNWRITABLE_BYTES_SAY % replaced)
        self.narrate(job, "steer_missed", sentence, text=said)
        # ⚠️ **说出来了才算「报过了」**（标在说之后 —— 见上）。两条之间有一条缝，
        # 而这条缝里**没有第二个线程**：这四个出口全都在**工作线程**上
        # （`_advance` → `_note_after_advance` / `_note_end` / 跑挂那一支），
        # 所以不会把同一句承诺说两遍。
        with job.lock:
            job.steer_missed_reported.update(x.get("seq") for x in fresh)

    def _note_human_stop(self, job: Job, plan: dict) -> None:
        """按「停」那一刻的那条时间线（`who="you"`：这是人打过的一次回）。

        ⚠️ 与 `_note_human_said` **分开**：那一句说的是「你在闸上按了继续」（`reply` 那条路），
        照抄过来会说成「按了继续」—— 那是**假话**（人按的是停）。
        """
        self.narrate(job, "human_said", "你按了「停」：%s" % plan["will_stop_at"],
                     who="you", where=str(plan["where"] or ""))

    def again(self, job_id: str) -> dict:
        """`POST /job/{id}/again` —— 「重新来一遍」（设计注 §4.3 的那条替代品）。

        它**不是**「从断点接着走」（那一版不做，理由在 §4.3：探路一停下账本就缺了，
        「接着走」等于「重探一遍」，只是多一套状态）。这一条是：**同一份开场白 +
        你说过的话**，新起一趟（新 job、新时间线）。

        ⚠️ 起新 job 走的是 **`Service.start()` 那条路**（R6）—— **别另写一条起跑路径**：
        排队、记 `submitted`、拼图、起窗口探针那边全做过一遍了，两条路就是两份口径。
        """
        job = self._jobs.get(job_id) or self._recover(job_id)
        if job is None:
            raise KeyError(job_id)
        view = self._view(job_id)
        if view["status"] not in (DONE, FAILED):
            # ⚠️ 这一条**是本片自己拍的**（计划与裁定都没写）：页面上那个按钮只在 `over` 时
            #    露头，而「重来」对着一趟**正在动**的 run 说不通 —— 两趟会在同一个窗口上互相踩。
            raise HTTPException(status_code=409,
                                detail=AGAIN_RUNNING_SAY % self._status_say(view["status"]))
        words, unreadable = self._words_the_human_said(job, job_id)
        if unreadable:
            # 读不回旧那一趟在闸上说过的话 —— **不许静默少带一半**（R5 的代价那栏）
            self.narrate(job, "state_unreadable", AGAIN_WORDS_UNREADABLE_SAY % unreadable,
                         error=unreadable)
        given = {k: v for k, v in job.brief.items() if k in RunRequest.model_fields}
        given.update({"hints": words or None, "again_from": job_id})
        try:
            out = self.start(RunRequest(**given))
        except HTTPException as exc:
            # 新那一趟**没起得来**：他按的那一下也要留一笔（否则这一屏上什么都没发生）
            self.narrate(job, "human_said", AGAIN_FAILED_SAY % exc.detail, who="you")
            raise
        new_id = str(out["job_id"])
        self.narrate(job, "human_said", AGAIN_PRESSED_SAY % (new_id, len(words)), who="you")
        return {"job_id": new_id, "say": AGAIN_SAY % (new_id, job_id, len(words))}

    def _words_the_human_said(self, job: Job, job_id: str) -> tuple:
        """`/again` 要带过去的话（R5）：**两个来源都带**，各按自己的顺序，闸上的在前。

        ① checkpoint 的 `hints`：在闸上**真说过的**（`graph._enter` 一路攒下来的）；
        ② `Job.inbox` 里**还没送出去的**：说了、但还没到它手上（§4.1 第一行承诺的
           「你说的话我记着」就是这一批）。
        ⚠️ ②**包含不再摆给他的那几条**（`superseded`，NEW-1）：那一格只是**不再往输入框里摆**，
        **不是**「这句话就当没说过」—— 重新来一遍的那一趟照样要带上（R5）。
        ⚠️ 判据不在这儿：它走的是 `_unsent_texts`（判据 ③，同样只那一处、不拿锁）。
        返回 `(话, 读不回来的原因或空串)` —— 读不回来时**不许静默少带一半**（R5 的代价）。
        """
        words: list = []
        unreadable = ""
        try:
            values = dict(getattr(self._snapshot(job_id), "values", None) or {})
            words.extend(str(x) for x in (values.get("hints") or []))
        except Exception as exc:               # noqa: BLE001 —— 说得出就说，说不出来就明说
            traceback.print_exc()
            unreadable = "%s: %s" % (type(exc).__name__, exc)
        with job.lock:
            words.extend(Service._unsent_texts(job.inbox))
        return [w for w in words if w.strip()], unreadable


    def close_window(self, job_id: str) -> dict:
        """人按下「关掉这个窗口」—— **服务去关，并且确认真死了**（Task 12）。

        为什么要有这一下（用户 2026-09-20：「希望面板上运营就能操作」）：
        「跑完关窗」今天是**硬规矩**，而它落在**命令行**上（`bash bit.sh close …`）——
        运营不会去敲命令，于是要么窗口泄漏，要么没人关。

        ⚠️ **关的时机只由人给，绝不无条件自动关**（本仓的明文设计）：停在闸上是唯一适合
        人动手接管的时刻，**人可能正看着那个窗口** —— 服务自己挑时刻关，等于把他的手从
        键盘下抽走。所以这是一个**按钮**，不是一条自动规则。
        ⇒ 两档**不给关**（`running` / `queued`，见 `window_closable`）；其余照按。

        ⚠️ 「关掉了」这句话**只在真确认死掉之后才说**：`BitWindow.close()` 自己会探活
        （SKILL：`close` 返回成功 ≠ 窗口真关了），没确认就抛 —— 那条异常是**人话**，
        原样端出去（这一屏不许编一句「失败了」）。
        """
        job = self._jobs.get(job_id) or self._recover(job_id)
        if job is None:
            raise KeyError(job_id)
        view = self._view(job_id)
        status = view["status"]
        if not self.window_closable(status):
            if self._window is None or not hasattr(self._window, "close"):
                raise HTTPException(status_code=400, detail=CLOSE_WINDOW_NO_LAYER_SAY)
            raise HTTPException(status_code=409, detail=(
                CLOSE_WINDOW_WHILE_RUNNING_SAY % self._status_say(status)))
        before = None
        try:
            probe = (self._window.probe() if hasattr(self._window, "probe")
                     else {"alive": self._window.alive()})
            before = (probe or {}).get("alive")
        except Exception:                      # noqa: BLE001 —— 按之前那一问读不出来 = 不知道
            traceback.print_exc()
        try:
            self._window.close()               # 自己会探活确认真死了（没确认就抛）
        except Exception as exc:               # noqa: BLE001 —— 外面世界（Bit 的窗口服务）
            raise HTTPException(status_code=502, detail=CLOSE_WINDOW_FAILED_SAY % exc)
        # 记一行读数（**同一条口径**：`window.jsonl`），让面板上那一格立刻跟上 ——
        # 旁路，坏了不许带塌这次动作（它已经成了）。
        try:
            self._probe_window_row(job_id, note="人按了「关掉这个窗口」")
        except Exception:                      # noqa: BLE001
            traceback.print_exc()
        state = self.window_state(job_id)
        say = ((CLOSE_WINDOW_ALREADY_GONE_SAY if before is False else CLOSE_WINDOW_DONE_SAY)
               % state["state_say"])
        token, where = self._where_it_stopped(job_id)
        self.narrate(job, "window_closed", say, where=token)
        return {"state": state["state"], "state_say": state["state_say"], "say": say}

    def reopen(self, job_id: str, body: ReopenRequest) -> dict:
        """窗口没了 → 换一个新窗口，**从 checkpoint 接着跑**（P6）。

        接得住的是**窗口那一支**，两步：
        - **自测**（`no_window`）：探路那一段**不重来**（账本在 checkpoint 里）；
        - **探路**（`explore_unfinished` / `paused` / `window_gone`，或者探路里**炸了**
          的那个 `failed`）：探路重跑，但**不是从头再探**（Task 6 / §1.9）——
          `reopen` 从**最新那本账**切出可重放的前缀（`replayable_prefix`，R1–R4），
          第二次进 `explore` 时先照它走回去（**0 模型调用**），再从断点接着探。
          那句人话必须说清这件事（重放了几步、停在哪、接着探）—— 它意味着又一次真窗口，
          不许含糊过去。

        ★ Task 12：**没给 `ws_url` 就服务自己开**（`fresh_open`：关掉旧的、开一个干净的）——
        这一下原先要人在宿主上敲 `bit.sh open` 再把那串贴回来，而那正是「运营全程不碰
        命令行」上的一步。自己开的窗口与派一趟新活时用的是**同一条路**（同 `fresh_open`，
        同样清 cookie/缓存），所以「干净会话」这个前提不会因为少了一次人工而变松。
        开不出来就**照实说开不出来**（400/502 + 人话），绝不拿一个旧窗口顶替。
        """
        job = self._jobs.get(job_id) or self._recover(job_id)
        if job is None:
            raise KeyError(job_id)
        view = self._view(job_id)
        point = self._resume_point(job_id, view)
        if point is None:
            raise HTTPException(status_code=409, detail=self._cannot_reopen_say(job_id, view))
        ws_url = str(body.ws_url or "").strip()
        if not ws_url:
            if self._window is None or not hasattr(self._window, "fresh_open"):
                raise HTTPException(status_code=400, detail=REOPEN_NO_WINDOW_LAYER_SAY)
            try:
                ws_url = str(self._window.fresh_open() or "").strip()
            except Exception as exc:           # noqa: BLE001 —— 外面世界（Bit 的窗口服务）
                raise HTTPException(status_code=502, detail=REOPEN_OPEN_FAILED_SAY % exc)
            if not ws_url:
                raise HTTPException(status_code=502, detail=(
                    REOPEN_OPEN_FAILED_SAY % "开窗口没给出新的 `ws_url`（空串）。"))
        if body.set_viewport and not (self._window is not None
                                      and hasattr(self._window, "set_viewport")):
            raise HTTPException(status_code=400, detail=(
                "要接窗口层那根线（`set_viewport`），但这个部署没有窗口层 —— 换不了窗口大小。"
                "要么把窗口层接上（`BIT_WORKER_IP`/`BIT_ID`），要么重开时别要它"
                "（那就还是老样子：没人给这根线，图停在自测那一步点名）。"))

        resume_from, step = point
        # 把新窗口放回状态，并**把上一次那个诚实的停止收掉**（它是上一次的结论，不是这一次的）。
        # `as_node=<上一步>`：图接着跑的正是**停下来的那一步** ——
        # 自测接在 lint 上（探路与起草都不重来）、探路接在 intake 上（探路重跑）。
        patch = {"ws_url": ws_url, "end_reason": "", "end_note": ""}
        if body.entry_url:
            patch["entry_url"] = body.entry_url
        say = "窗口重开了，从上次停下的地方接着跑（探路那一段不重来）。"
        if step == "explore":
            patch["explore_say"] = ""          # 上一趟探路的说法收掉（新的探路会写新的）
            patch["end_note"] = ""
            # **接着走，不是从头再探**（§1.9）：从最新那本账切出可重放的前缀。
            # ⚠️ 这两样**无条件写**（切不出来就是 `None`）：上一趟 `reopen` 留下的前缀
            # 不许留在状态里被这一次复用 —— 那是**别的窗口**上的账。
            prefix, note = self._resume_for(job_id, job.brief)
            patch["resume_from"] = list(prefix) or None
            patch["resume_note"] = note
            # **把它前面那几趟的账读回来**（复审 ⑥）：探路抛异常时节点不返回，
            # `explore_spent` 那一整份都不会进 checkpoint —— 而盘上记着。
            # 与状态里那份**逐键取更紧的**（两边都是「花了多少」的下界）。
            patch["explore_spent"] = _tighter(
                dict(getattr(self._snapshot(job_id), "values", None) or {}).get("explore_spent"),
                self._spent_from_attempts(job_id))
            say = self._reopen_explore_say(prefix, note)
        # ⚠️ 窗口那一串（`bit.sh open` 吐的）也是**外面来的字**：消毒在载荷进来那一刻做过
        # （`_Intake`），那一句并在这儿 —— 它会进 `job.say`、进时间线（`window_reopened`）。
        say += body.unwritable_say()
        with job.lock:
            job.brief.update({"ws_url": ws_url})
            job.brief.pop("_failed_at", None)
            if body.entry_url:
                job.brief["entry_url"] = body.entry_url
            # ⚠️ **窗口一换就必须重拼那张图** —— 不是「只有新打开 set_viewport 时才要」。
            #
            # `Deps.explore`（`_explore_for`）与窗口层那根线（`_viewport_cb`）都是**拼图时**
            # 对 `brief["ws_url"]` 闭包出来的。只把新 url 写进 brief / checkpoint 而不重拼，
            # 得到的是：`reopen` 回 200、状态里写着新窗口，而探路手里那根线**还指着旧窗口** ——
            # 续跑会又一次死在旧窗口上，出路只剩「重新开一个任务」= 整轮重来（P6 明令不许）。
            # 探针那根线同理：不重拼它就一直量**旧**窗口（要么以莫名其妙的理由判没做成，
            # 要么旧窗口刚好是那个尺寸时**判成做成了**）。
            #
            # 换一张图接着跑是安全的：状态在 checkpoint 里（Test Graph 那条
            # 「另一个图对象接着跑」的用例钉的就是这件事）。
            job.brief["set_viewport"] = bool(job.brief.get("set_viewport") or body.set_viewport)
            job.graph = self._build_graph(job.brief, job_id)
            job.status = RUNNING
            job.error = None                    # 上一次那个失败不再是这个 job 的现状
            job.say = say
            # 换了一个窗口 = 上一趟那个「窗口没了」不再适用（新的那个也会死，那是**新**事实）
            job.window_dead = False
        with self._check.lock:
            job.graph.update_state(self._cfg(job_id), patch, as_node=resume_from)
        # 目录表第 2 行：**照搬它现有那句 `say`**（探路重跑 / 从断点接着跑，两句不同）。
        # ⚠️ 位置有讲究：放在 `update_state` **之后**（状态真写进去了才算「重开了」——
        #    写失败还报一句「重开了」，那句话就是假的），放在 `_submit` **之前**
        #    （交下去之后工作线程会立刻喊「在跑」）。
        self.narrate(job, "window_reopened", say, where=step, ws_url=ws_url)
        self._submit(job, None)                      # None = 「接着跑」，不是新的输入
        return self._view(job_id)

    def _resume_for(self, job_id: str, brief: dict) -> tuple:
        """能不能**接着走**：从**最新那本账**切出可重放的前缀（§1.9；切法归 Task 5 的 R1–R4）。

        返回 `(前缀, 人话)`。前缀为空时，人话**说清为什么** —— 不静默。

        ⚠️ **读不出来 = 没得重放，不是异常**（R-19 的判据）：账本不在、那是本空账、
        缺 `success_text`（`replayable_prefix` 会抛）、盘读不动 —— 一律回到「从入口重探」
        （也就是**今天那条路**，一个字节不差），只是**说出来**。账本在这条链上是**旁路**：
        它坏掉不许把续跑带塌（与 `_journal_for` 那条规矩同源）。

        ⚠️ 那些**读不出来的行**（被杀在写一半留下的半行）不算致命：`read` 把好行照读，
        而重放自己那四条判据（尤其 R2「这一步之后得有做成的观察」）本来就会把
        「尾巴上少了观察的动作」挡在边界之外 —— 所以照切，只在人话里说一句。
        """
        try:
            books = journal.attempts(self._explore_root, job_id)
            if not books:
                return [], "这个 job 还没有账本（一趟都没记上）"
            rows, skipped = journal.read(books[-1])
            if not rows:
                return [], "最新那本账是空的（%s）" % books[-1].name
            # R4 要「走过的页面地址」：最后一趟的 `pages` 在 checkpoint 里（探路炸掉那一支没有）。
            journey = dict(getattr(self._snapshot(job_id), "values", None) or {}).get("journey")
            prefix, why = browser_agent.replayable_prefix(
                rows, brief.get("success_text") or "",
                entry_url=str(brief.get("url") or ""),
                pages=list(getattr(journey, "pages", None) or []))
            if skipped:
                why += (" 另外：这本账里有 %d 行读不出来（多半是被杀在写一半的地方），"
                        "能重放的是**读得出来的那一段**。" % len(skipped))
            return list(prefix), why
        except Exception as exc:                        # noqa: BLE001 —— 旁路，见 docstring
            return [], ("账本读不出来（%s: %s）—— 这一次没有前缀可重放，探路从入口重新开始。"
                        % (type(exc).__name__, exc))

    def _spent_from_attempts(self, job_id: str) -> dict:
        """从 `attempts.jsonl` 把**已经记下来的**消耗读回来（`{steps, rounds, attempts}`）。

        为什么要有它（复审 ⑥ / 修复轮 2）：探路**抛异常**时节点不返回 ⇒ `explore_spent`
        （含那一次节点执行里**前面已经跑完的那几趟**）**不会进 checkpoint** ——
        而 `reopen`（**没有次数上限**）正是下一步，它按一份**满预算**再探一遍。
        那些账**就在盘上**：`attempts.jsonl` 一次尝试一行，`steps` / `rounds` 都在
        （正常收场那几趟一定记着；「连账本都没生成」的那种本来就 0 步）。

        ⚠️ **口径差异如实写着**：账上的 `steps` 把**重放的步**也算进去了
        （`_note_attempt` 记的是账本长度）⇒ 它只会**偏大** ⇒ 预算更**紧**
        （方向是对的：与 `_round_spends` 那条「不知道的一律按花算」同族）；
        而 `rounds` 里 `None`（没量到）在这里按 0 算 ⇒ 那一项偏松。取**逐键 max**
        （与状态里那份比），所以两边都不会被对方放松。

        ⚠️ **这一格 `rounds` 是「探路的模型轮数」**（`journey.rounds` 那条线），
        **不是**运营看见的那个「轮」（闸拍轮次 = 到过几道闸，投影在 `/live.rounds` /
        `/runs[].rounds`，算法在 `agent/rounds.py` 的 `count` —— ⚠️ **不是** `Job.pauses`：
        那是**闸拍张数**，跑完/跑挂那一次也拍 ⇒ 到头了那两档它 = 轮数+1）。
        """
        out = {"steps": 0, "rounds": 0, "attempts": 0}
        try:
            rows = measure.read_rows(self._explore_dir(job_id) / "attempts.jsonl")
        except Exception:                                   # noqa: BLE001 —— 旁路
            return out
        for row in rows:
            if not isinstance(row, dict) or row.get("_corrupt"):
                continue
            out["steps"] += int(row.get("steps") or 0)
            out["rounds"] += int(row.get("rounds") or 0)
            out["attempts"] += 1
        return out

    @staticmethod
    def _reopen_explore_say(prefix: list, note: str) -> str:
        """`reopen` 之后那句人话（§1.9）：**说清重放了几步、停在哪、接着探**。

        ⚠️ 原先那句是「探路要从头再走一遍」—— 在新形状下它是**假话**（账本还在，
        能接着走），而且它把代价说大了（人以为要再花一整趟）。
        """
        if prefix:
            return ("窗口重开了，探路**接着上一趟走**：先照账本重放 %d 行"
                    "（其中 %d 个动作，0 模型调用），再从断点接着探 —— 不用从头再探一遍。"
                    "停在这儿：%s" % (len(prefix),
                                      len(browser_agent.replay_actions(prefix)),
                                      note or "（没说明为什么停在这儿）"))
        return ("窗口重开了，探路从入口重新开始（**这一次没有可重放的前缀**：%s）—— "
                "你之前说的话和开场白都还在，图接着往下跑。"
                % (note or "账本里没有读得出的段"))

    def _resume_point(self, job_id: str, view: dict) -> Optional[tuple]:
        """这个 job 能不能用「重开窗口 + 接着跑」接住？能就回 `(接在哪一步, 要重跑哪一步)`。

        ⚠️ 判据**只有一份**（`_resume_point_from`）：`/reopen` 端点与 `/live` 的
        `can_reopen` 那一格走的是**同一个函数** —— 两处各写一遍，就会出现「按钮在、
        按下去 409」那种「点了没反应」的形状（Task 12 要治的正是它）。
        这里只负责**读**那份状态（读法见 `_snapshot`）。
        """
        values = dict(getattr(self._snapshot(job_id), "values", None) or {})
        return self._resume_point_from(values, view)

    @staticmethod
    def _resume_point_from(values: dict, view: dict) -> Optional[tuple]:
        """`_resume_point` 的**纯的那一半**：状态已经在手上时走这里（不碰 saver）。

        两种「停」，判据不同（这是这一条最容易写错的地方）：

        - **DONE**：图是**在那一步里**停下的 —— 那一步的结论已经落进状态了
          （`visits[-1]` 就是它）→ 接在它的**上一步**上，于是接着跑的正是它。
        - **FAILED**：图是**在那一步的下一跳里**炸的（那一步落下了、下一步没有）
          → 接在**最后落下的那一步**上。窗口在探路途中断开就是这个形状：
          `visits[-1] == "intake"`，炸掉的是 `explore`。

        两种情况都只认**窗口那一支**（`WINDOW_STEPS` 里那两步）。
        """
        visits = list((values or {}).get("visits") or [])
        last = str(visits[-1]) if visits else ""
        failed = view["status"] == FAILED
        if failed:
            step = _AFTER.get(last)             # 在「上一步」的下一跳里炸的
            return (last, step) if step else None
        if view["status"] != DONE:
            return None
        reason = str((values or {}).get("end_reason") or "")
        if last in WINDOW_STEPS and reason in WINDOW_END_REASONS.get(last, ()):
            return (WINDOW_STEPS[last], last)
        return None

    # ── 人话 ──────────────────────────────────────────────────────
    def _window_is_gone(self, ws_url) -> bool:
        """窗口死了吗。**只有明确说死了才拦**（问不出来一律当不知道 —— 不许误杀）。"""
        if not ws_url or self._window is None or not hasattr(self._window, "alive"):
            return False
        return self._window.alive() is False

    def _cannot_reopen_say(self, job_id: str, view: dict) -> str:
        """接不住时说的**人话**：这个任务现在什么形状、以及「重开窗口」接得住的是哪两种。"""
        can = ("能接住的是**窗口那一支**两种：①自测那一步发现窗口没了（探路不重来）；"
               "②探路没走完 / 人喊停 / 窗口没了、或者探路里炸了"
               "（探路重跑，但**按账本接着走**，不是从头再探）。")
        if view["status"] in (QUEUED, RUNNING):
            return ("重开窗口要等这个任务停下来 —— 它现在是「%s」。%s"
                    % (self._status_say(view["status"]), can))
        result = view.get("result") or {}
        reason = result.get("end_reason")
        if reason == END_DELIVERED:
            return ("不用重开：这一趟**已经交付**了（产物在 %s）。要再走一遍就另起一个任务。%s"
                    % (result.get("py_path"), can))
        # ⚠️ 不能从 `view["result"]` 里读 `visits` —— `FAILED` 的 job 那个字段是 `None`
        # （**那是对的**：跑挂的没有结果），于是这句会永远渲染成「不知道哪一步」。
        # 走到哪儿了这件事只在 checkpoint 里。
        visits = list((self._snapshot(job_id).values or {}).get("visits") or [])
        where = str(visits[-1]) if visits else ""
        if view["status"] == FAILED:
            return ("不用重开：这一趟是**炸**在「%s」那一步的（不是窗口没了）：\n%s\n%s\n"
                    "重开一个窗口解决不了它 —— 按上面那句话说的办。"
                    % (STEP_SAY.get(where, where or "不知道哪一步"),
                       str(view.get("say") or "")[:400], can))
        return ("不用重开：这一趟停下来不是因为窗口没了，而是「%s」：\n%s\n%s\n"
                "重开一个窗口解决不了它 —— 按上面那句话说的办。"
                % (STEP_SAY.get(where, reason or "没说清"),
                   str(view.get("say") or "")[:400], can))

    @staticmethod
    def _problems_say(problems: list) -> str:
        return ("这份开场白还开不了工（**没有**碰浏览器、没有跑模型、没有写任何文件）：\n  · "
                + "\n  · ".join(problems))

    @staticmethod
    def _status_say(status: str) -> str:
        return {QUEUED: "还在排队", RUNNING: "正在跑", WAITING: "在等人回话",
                DONE: "跑完了", FAILED: "跑挂了"}.get(status, status)


# ─────────────────────────────── 拼成 app ───────────────────────────────


def create_app(*, graph_factory: Optional[Callable] = None, window: Any = None,
               checkpointer=None, checkpointer_url: Optional[str] = None,
               out_dir: Optional[str] = None, viewport_probe: Optional[Callable] = None,
               explore_dir: Optional[str] = None,
               window_probe_seconds: Optional[float] = None,
               shots_dir: Optional[str] = None, capture: Optional[Callable] = None,
               shot_timeout: Optional[float] = None,
               capture_bin: Optional[str] = None,
               selftest_dir: Optional[str] = None,
               mcp_bin: Optional[str] = None, failures_reader: Any = None,
               json_ws_url: Optional[str] = None,
               json_rerun: Optional[Callable] = None,
               json_backup_dir: Optional[str] = None,
               json_ticket_store: Any = None,
               country_runner: Optional[Callable] = None,
               country_tool: Optional[str] = None) -> FastAPI:
    """拼一个 app。测试从这里注入桩图 / 桩窗口 / 内存 saver。

    `window=None` 是**默认且合法**的：这个部署没接窗口层 —— 于是 `set_viewport` 那根线
    不存在，图会在 `intake` 就**结束这一趟**并点名（R-31 要的正是这个，不是要服务糊一个
    假回调）。⚠️ 那句话走的是 `end_note`（**结束**这一趟），不是「停在闸上等人」——
    `intake` 2026-09-20 起不设闸。

    `explore_dir` 是**运行产物**落哪（`runtime/explore/<job_id>/`，Task 1）。默认给的是
    仓库里那个 `runtime/`（不进 git）；测试一律传自己的 `tmp_path`。

    `shots_dir` 是**闸拍与步拍**落哪（`runtime/shots/<job_id>/pause-<n>.png` /
    `<本趟标记>-step-…`，Task 3）—— 步拍的名字**带本趟标记**（6 位 hex，`_StepShots`），
    因为同一个 job 目录会被最多 3 趟重探共用（见 `shots.dir_for` 那段）：
    `None` ⇒ `SITEFORGE_SHOTS_DIR` ⇒ 仓库里的 `runtime/shots`；`capture_bin` 是那个 cdp
    二进制（`None` ⇒ `SITEFORGE_CDP_BIN` ⇒ `CDP_PATH` ⇒ 仓库里的 `tools/cdp/cdp`）。
    ⚠️ 这两样都在**构造时定死**（不是在每次抓拍时再看一眼环境）—— 见 `Service.__init__`。
    **上面那条链是「构造那一刻」的解析规则**：解析完就落进 `self._shots_dir` / `self._cdp_bin`，
    之后**环境再变也不影响这个服务**（`/health` 报的就是这两个落下来的值 ——
    报「环境里现在写着什么」曾经是第四条通道：名字说 A、量的是 B）。
    `capture` / `shot_timeout` 是给测试注入桩用的（与 `viewport_probe` 同一个理由）。
    """
    svc = Service(graph_factory=graph_factory, window=window, checkpointer=checkpointer,
                  checkpointer_url=checkpointer_url, out_dir=out_dir,
                  viewport_probe=viewport_probe, explore_dir=explore_dir,
                  window_probe_seconds=window_probe_seconds, shots_dir=shots_dir,
                  capture=capture, shot_timeout=shot_timeout, capture_bin=capture_bin,
                  selftest_dir=selftest_dir, mcp_bin=mcp_bin, failures_reader=failures_reader,
                  json_ws_url=json_ws_url, json_rerun=json_rerun,
                  json_backup_dir=json_backup_dir, json_ticket_store=json_ticket_store,
                  country_runner=country_runner, country_tool=country_tool)
    api = FastAPI(title="siteforge", version="0.1",
                  description="看着真页面产出 cdp-first py 脚本的 agent 服务（计划二 Task 8）")

    @api.get("/console", response_class=HTMLResponse)
    def console() -> HTMLResponse:
        """**给运营的那一屏**（设计注 §8.4）：仓库里那个文件原样读出来。

        为什么是「路由读文件」而不是 `StaticFiles` 挂一个目录：这一屏只此一页、
        没有静态资源（**零外部资源**是硬约束，CSS/JS 全内联在那个文件里），
        而 `StaticFiles` 会把整个目录暴露出去 —— 那是一个比它解决的问题更大的面。

        ⚠️ 读不到就**响**（500 + 一句人话）：这是「没有静默的路径」在这一屏的样子。
        给一页空白，运营看到的是「还没有任何运行」—— 和「服务找不到自己的页面」
        完全不是一件事（`CONSOLE_UNREADABLE_SAY`）。

        `no-store`：页面是**服务的一部分**（它按 `/live` 的形状渲染），
        缓存住会让「新服务 + 旧页面」拼出一个谁也不认识的画面。这一页很小，重下载很便宜。
        """
        try:
            html = CONSOLE_PATH.read_text(encoding="utf-8")
        except OSError as exc:
            raise HTTPException(status_code=500,
                                detail=CONSOLE_UNREADABLE_SAY % (exc, CONSOLE_PATH))
        return HTMLResponse(html, headers={"Cache-Control": "no-store"})

    #: ★ 运营手册（2026-09-21）：用户要一个**能直接打开**的地址（文档不该只有 `.md`）。
    #: 渲染的是 `docs/运营手册-面板修站.md` **那一份**（现读盘、每次请求都读）——
    #: 再写一份 HTML 就是两个来源，改一份忘一份，运营看到的就是旧那份。
    @api.get(manual.MANUAL_PATH, response_class=HTMLResponse)
    def manual_page() -> HTMLResponse:
        try:
            text = manual.OPERATOR_MANUAL.read_text(encoding="utf-8")
        except OSError as exc:
            raise HTTPException(status_code=500,
                                detail="读不了那份手册（%s）：%s" % (exc, manual.OPERATOR_MANUAL))
        return HTMLResponse(manual.page(manual.render(text), title="运营手册：用面板修一个坏掉的站"),
                            headers={"Cache-Control": "no-store"})

    @api.get("/")
    def root() -> RedirectResponse:
        """`GET /` → `/console`：运营手上的是 `http://<那台机器>:8080`，不带路径。

        ⚠️ 302（**不是** 307）：这里要的是「去那一页」，不是「用同一个方法再发一次」。
        """
        return RedirectResponse(url="/console", status_code=302)

    @api.get("/health")
    def health() -> dict:
        return {
            "ok": True,
            "service": "siteforge",
            "checkpointer": svc._check.kind,
            "say": svc._check.say(),
            "window_layer": (type(svc._window).__name__ if svc._window is not None
                             else "没接（换窗口大小那根线给不了）"),
            # ⚠️ 报的必须是**服务真正会用的那个**（构造时定死的），不是「环境里现在写着什么」：
            #    这两个东西可以不一样（显式给了 `capture_bin` 而环境里另有一个），
            #    而**名字说 A、量的是 B** 是这个项目最老的那条病。
            #    以前这里读活环境，两个变量都没设时还报 `null` —— 像「没有 cdp」，
            #    而服务实际会用**仓库里那个** `tools/cdp/cdp`（修复轮 2 的第四条，见 conftest）。
            "cdp": svc._cdp_bin,
            #: **哪一跳赢了**（`capture_bin` / `SITEFORGE_CDP_BIN` / `CDP_PATH` / `repo-default`）——
            #: 运维看到 `cdp` 会问的下一个问题。与 `cdp` 同一次解析的产物（不再读环境）。
            "cdp_source": svc._cdp_bin_source,
            "out_dir": svc._out_dir,
            "jobs": len(svc._jobs),
            #: ① 读失败记录那根线**配没配**（Task 13）。报的是**服务真正会用的那个客户端**
            #: 的那句人话 —— 一个没配 token 的部署上，「查失败」按下去只会红一次；
            #: 运维在这儿能先看到「这台机器上没有那个 token」，而不是去查网络。
            #: ⚠️ **绝不报 token 本身**（它是凭据）。
            "failures": {"configured": svc._fmr.configured, "say": svc._fmr.say()},
            "steps": {k: STEP_SAY[k] for k in NODES},
        }

    @api.get("/failures")
    def failures(site: str = "", since: str = "", limit: str = "") -> dict:
        """**这个站最近失败的那几趟**（Task 13 ②）—— 一行一句人话。

        ⚠️ 它**不是**「把 FMR 那个接口代理一下」：端出去的是人话 + 一个单号。
        ⚠️ **三种「量不到」一律非 2xx**（503 没配 token / 502 连不上 / 502 后端回码）——
        一个 `200 {"failures": []}` 在屏幕上与「这个站很健康」一模一样，
        而这一栏存在的理由正是「别把量不出来读成量出来了」。
        """
        return svc.failures(site, since=since or None, limit=_count(limit))

    @api.get("/failures/{task_id}/evidence")
    def failure_evidence(task_id: str, site: str = "", since: str = "") -> dict:
        """**这一条失败的证据**（Task 13 ②）—— 那段人话 + 该填进「站点网址」的那一串。

        页面拿它去填「开一趟」那张表（Task 12 那张）—— **页面自己不拼** evidence。
        """
        return svc.failure_evidence(task_id, site=site, since=since or None)

    @api.get("/rank")
    def rank(date: str = "", limit: str = "") -> dict:
        """**这一天哪些站在失败**（Task 4 ③）—— 一行一句人话。

        ⚠️ 与 `/failures` 同一个形状：**三种「量不到」一律非 2xx**。
        「今天一个站都没失败」是 `200` + 那句说清了「这是量到的」的 `say` ——
        两件事在屏幕上必须分得开（这一片从头到尾治的就是那个形状）。
        """
        return svc.rank(date=date or None, limit=_count(limit))

    @api.get("/diag/{task_id}")
    def diag(task_id: str) -> dict:
        """**这一单为什么失败**（Task 4 ④）—— 抬头 + 它自己报的那几行，原样。

        ⚠️ 走**单号**（`brief §2 R1`）：榜单那个站点键脏过，拿它当 join 键会静默查到 0 行。
        ⚠️ 这一单**还没有原因行**是很常见的，那**不是**错误：`200` + `diag: []` + 一句 `note`
        （页面照着 `note` 说「还没有原因」，不许留白）。
        """
        return svc.diag(task_id)

    @api.get(CONFIGCHECK_PATH)
    def configcheck_route(site: str = "") -> dict:
        """**这份配置执行器认不认**（合规闸，2026-09-21）—— 只读，一个字都不写。

        ⚠️ 站点键走**查询参数**（真键带斜杠，见 `CONFIGCHECK_PATH` 那段）。
        ⚠️ **不合规是 `200`**（读回来了、也看过了）；**读不回来才是非 2xx** ——
        两者在屏幕上都是「没东西可看」，而处置完全不同。
        """
        return svc.configcheck(site)

    @api.get(JSODIFF_PATH)
    def jsondiff(site: str = "") -> dict:
        """**这份 JSON 配置差在哪一格**（Task B2/B3）—— 读配置 → 复跑 → 逐格对照。

        ⚠️ 站点键走**查询参数**（真键带斜杠，见 `JSODIFF_PATH` 那段）。
        ⚠️ 「还没复跑」是 `200` + 一句说清的话；**「配置读不回来」与「复跑没量着」
        都是非 2xx** —— 四种空各有各的样子，页面照着 `say` 说，不自己编。
        ⚠️ **这一版没有写回**（只读）：写接口的语义没验过，见 `Service.jsondiff`。
        """
        return svc.jsondiff(site)

    @api.post(JSONWRITE_PREPARE_PATH)
    def jsonwrite_prepare(body: JsonWritePrepareRequest) -> dict:
        return svc.jsonwrite_prepare(body.site, body.config, body.operator)

    @api.post(JSONWRITE_COMMIT_PATH)
    def jsonwrite_commit(body: JsonWriteCommitRequest) -> dict:
        return svc.jsonwrite_commit(body.ticket)

    @api.post(JSONWRITE_ROLLBACK_PATH)
    def jsonwrite_rollback(body: JsonWriteRollbackRequest) -> dict:
        return svc.jsonwrite_rollback(body.backup_id, body.operator)

    @api.post(PYWRITE_PREPARE_PATH)
    def py_upload_prepare(job_id: str, body: PyWritePrepareRequest) -> dict:
        return svc.py_upload_prepare(job_id, body.operator)

    @api.post(PYWRITE_COMMIT_PATH)
    def py_upload_commit(job_id: str, body: PyWriteCommitRequest) -> dict:
        return svc.py_upload_commit(job_id, body.ticket)

    @api.post(PYWRITE_ROLLBACK_PATH)
    def py_upload_rollback(job_id: str, body: PyWriteRollbackRequest) -> dict:
        return svc.py_upload_rollback(job_id, body.backup_id, body.operator)

    @api.post("/run", status_code=202)
    def run(body: RunRequest) -> dict:
        return svc.start(body)

    @api.get("/runs")
    def runs() -> dict:
        """**能挑运行的最小列表**（设计注 §8.1）—— 页面左边那一栏只取它一个。

        ⚠️ 它是 **process-local** 的：登记表里只有**这个进程**记得的那些 job
        （`note` 在空列表时明说这件事）。状态本身在 checkpoint 里，所以
        「不在这儿」不等于「没发生过」——知道 job id 就还能看。
        """
        return svc.runs()

    @api.get("/job/{job_id}")
    def job(job_id: str) -> dict:
        try:
            return svc._view(job_id)
        except KeyError:
            raise HTTPException(status_code=404, detail=NO_SUCH_JOB_SAY % job_id)

    @api.get("/job/{job_id}/live")
    def live(job_id: str) -> dict:
        """**页面的唯一数据源**（Task 4 先出骨架）：一个轮询喂一个页面（设计注 §8.3）。

        与 `/job/{job_id}` 的关系：那边是**既有形状**，别的地方在读它，一个字段都不改；
        这边是新的那份（时间线 + 骨架里的闸口/输入/轮次/窗口）。**字节一个都不进来**（§8.3 第 2 条）。
        """
        try:
            return svc.live(job_id)
        except KeyError:
            raise HTTPException(status_code=404, detail=NO_SUCH_JOB_SAY % job_id)

    @api.get("/job/{job_id}/steps")
    def steps_view(job_id: str) -> dict:
        """运行那趟的**每一步**（三层 + 诊断）。与 `/live` 的分工：那个说「探路走到哪」，
        这个说「产物自己跑的时候，每一步成不成、为什么」。**只读**，一个字节都不写。

        ★ 2026-09-23 P0：运营要能自己看出「为什么失败」，而不是截图发群里找人。
        """
        try:
            return svc.steps(job_id)
        except KeyError:
            raise HTTPException(status_code=404, detail=NO_SUCH_JOB_SAY % job_id)

    @api.get("/job/{job_id}/artifact")
    def artifact(job_id: str):
        """这一趟写下的那份 py（设计注 §十五）：**字节走这儿**，文件名在 `Content-Disposition` 里。

        ⚠️ **不接受任何路径参数**（§15.3）：一旦这儿能传路径，它就是一个**任意文件读取** ——
        所以这个函数**没有第二个参数**，这不是省事，是判据的一部分。
        端出去的是**这一趟记录里那串字节**（`state["src"]`），不是盘上那个文件 ⇒
        **同一个站点跑两趟，各自拿到自己那一份**（A15 无条件成立），
        盘上那一份现在是不是它的，由那句话如实说。
        拿不到 → **409 + 一句人话**（为什么拿不到），不是 404、也不是一个空文件。
        """
        try:
            state = svc.artifact_file(job_id)
        except KeyError:
            raise HTTPException(status_code=404, detail=NO_SUCH_JOB_SAY % job_id)
        # ★ 端出去的**就是核对过的那串字节**（`state["bytes"]` 同一个对象）：
        # `FileResponse` 会**再开一次盘**，那两次之间被换掉的话，端出去的就是没核对过的字节
        # （复核 R2 实测复现过）。这里没有第二次读 —— 核对与发送之间没有缝。
        # 下载名来自**这一趟记录里的路径**（不是盘上那个文件的名字），并且只留安全字符
        # （它进的是头字段 —— 一个换行就是头注入）。
        return Response(content=state["bytes"], media_type="text/x-python",
                        headers={"Content-Disposition":
                                 'attachment; filename="%s"' % state["filename"]})

    @api.get("/job/{job_id}/shot/{name:path}")
    def shot(job_id: str, name: str):
        """一张闸拍图（设计注 §8.1）：**字节走这儿，不进 `/live` 的 JSON**。

        ⚠️ `{name:path}`（不是 `{name}`）：名字里带 `/` 的请求也要**落到人手里** ——
        不然框架会拿一个英文的 `{"detail":"Not Found"}` 先把它挡掉，
        而这条路上最该说清的就是「这个名字不能当图名」（它是一次路径穿越的尝试）。
        名字与路径的判据全在 `Service.shot_file` 里（白名单 + 解析后仍在那个目录里）。
        """
        path = svc.shot_file(job_id, name)
        # `no-cache`：文件名带轮号，正常永远不会变 —— 但**服务重启后捡回来的 job**
        # 轮号从 1 重新数，同一个名字可能换一张图。让浏览器每次回来问一句（304 很便宜），
        # 否则页面上会出现一张**对不上的旧图**（看着像证据，比不显示坏得多）。
        return FileResponse(str(path), media_type="image/png",
                            headers={"Cache-Control": "no-cache"})

    @api.post("/job/{job_id}/reply")
    def reply(job_id: str, body: ReplyRequest) -> dict:
        try:
            return svc.reply(job_id, body)
        except KeyError:
            raise HTTPException(status_code=404, detail="没这个任务：%s。" % job_id)

    @api.post("/job/{job_id}/say", status_code=202)
    def say(job_id: str, body: SayRequest) -> dict:
        """人说了一句（Task 8）：`{"text": "…"}` → `{queued|delivered, n, say}`。

        `202`：这句话**收下了**，但还没送到它手上（送到了才叫 `delivered`）——
        **它绝不替人往前走一步**（到下一道闸进输入框，人按按钮才发）。
        """
        try:
            return svc.say(job_id, body)
        except KeyError:
            raise HTTPException(status_code=404, detail="没这个任务：%s。" % job_id)

    @api.post("/job/{job_id}/stop")
    def stop(job_id: str) -> dict:
        """「停下，我要说一句」（Task 8）→ `{stop: {requested, where, will_stop_at, say}}`。

        `will_stop_at` 是**服务说它落在哪**的那句人话（页面把它摆在按钮底下，不自己编）。
        """
        try:
            return svc.stop(job_id)
        except KeyError:
            raise HTTPException(status_code=404, detail="没这个任务：%s。" % job_id)

    @api.post("/job/{job_id}/again", status_code=202)
    def again(job_id: str) -> dict:
        """「重新来一遍」（Task 8）→ `{job_id, say}`：**新的一趟**（同一份开场白 + 你说过的话）。

        `202`：与 `/run` 同一个语义（活交下去了、在排队）—— 两个端点做同一件事，
        就该有同一种答复。
        """
        try:
            return svc.again(job_id)
        except KeyError:
            raise HTTPException(status_code=404, detail="没这个任务：%s。" % job_id)

    @api.post("/job/{job_id}/reopen")
    def reopen(job_id: str, body: ReopenRequest) -> dict:
        try:
            return svc.reopen(job_id, body)
        except KeyError:
            raise HTTPException(status_code=404, detail="没这个任务：%s。" % job_id)

    @api.post("/job/{job_id}/window/close")
    def window_close(job_id: str) -> dict:
        """人按下「关掉这个窗口」（Task 12）→ `{state, state_say, say}`。

        ⚠️ 它**不是**一条自动规则：关的时机只由人给（`window_closable` 只拦「它正在跑」）。
        `state_say` 是关完之后**量到**的那句状态原话（页面把它摆回那一格 —— 这一下不
        自己编一句「关掉了」，因为确认死掉是窗口层自己的事）。
        """
        try:
            return svc.close_window(job_id)
        except KeyError:
            raise HTTPException(status_code=404, detail="没这个任务：%s。" % job_id)

    @api.get(COUNTRY_PATH)
    def country_now() -> dict:
        """**现在这个出口是哪国**（2026-09-22）—— 实测读数（经 :1081 问一句），**只读**。

        ⚠️ 问不出来就 **503 + 一句人话**（不是回一个空国家）：这条路上最容易变成谎的一格是
        「问不出来」被读成「没换」—— 它们不是一件事（`COUNTRY_UNREADABLE_SAY`）。
        """
        return svc.country_now()

    @api.post(COUNTRY_PATH)
    def country_switch(body: CountryRequest) -> dict:
        """**换成这个国家**（面板上那个按钮）→ `{ok, country, say, output}`。

        ⚠️ 同步等它核完（通常十几秒）—— 这一下**要么核到、要么说没核到**，没有第三态
        （后台跑着、页面显示「换好了」而其实没换，正是这一格绝不许长成的形状）。
        两条前置（400 国家码不成形状 / 409 有任务在跑）都**拦在动作之前**。
        """
        return svc.switch_country(body.country, body.url)

    api.state.service = svc
    return api


#: uvicorn 的入口（`entrypoint.sh` 里 `agent.service:app`）。
#: ⚠️ 导入这个模块**不碰**数据库：saver 是第一次真要用的时候才建的（`Checkpointer`）。
app = create_app(window=bit_window_from_env())
